:root {
  --admin-bg: #0b0f14;
  --admin-surface: #121821;
  --admin-surface-strong: #171f2b;
  --admin-surface-soft: #1a2431;
  --admin-border: rgba(255, 255, 255, 0.08);
  --admin-text: #eef4f7;
  --admin-muted: rgba(219, 230, 238, 0.62);
  --admin-shadow: 0 18px 40px rgba(0, 0, 0, 0.28);
  --admin-accent-primary: #9dff00;
  --admin-accent-secondary: #ffd400;
  --admin-accent-tertiary: #ff5252;
  --admin-accent-quaternary: #22d3ee;
}

/* Cash-flow visual reset: one continuous black financial report. */
.is-cash-flow {
  --admin-bg: #000;
  --admin-surface: #000;
  --admin-surface-strong: #080808;
  --admin-surface-soft: #0b0b0b;
  --admin-border: #252525;
  --admin-shadow: none;
  --cash-flow-surface: #000;
  --cash-flow-surface-soft: #0b0b0b;
  --cash-flow-border: #252525;
  --cash-flow-text: #f4f4f2;
  --cash-flow-muted: #8a8a86;
  --cash-flow-income: #21d99a;
  --cash-flow-cost: #ff666b;
  --cash-flow-accent: #e8ff65;
  background: #000 !important;
}

.is-cash-flow :is(.admin-app, .admin-shell, .admin-shell-main, .admin-topbar) {
  background: #000 !important;
}

.is-cash-flow .admin-rail {
  border-right-color: #1d1d1d;
  background: #050505;
}

.is-cash-flow .cash-flow-topbar {
  margin-bottom: 0;
  padding-bottom: 30px;
}

.is-cash-flow .cash-flow-topbar .admin-topbar-brand {
  gap: 3px;
}

.is-cash-flow .cash-flow-topbar .admin-topbar-brand h1 {
  color: #f4f4f2;
}

.is-cash-flow .cash-flow-topbar .admin-topbar-brand p {
  color: #858581;
}

.is-cash-flow .cash-flow-topbar [data-admin-home-chrome] {
  color: #f4f4f2;
}

.is-cash-flow .cash-flow-back {
  margin-bottom: 7px;
  color: #777;
  font-size: 0.68rem;
  letter-spacing: 0.13em;
}

.is-cash-flow .cash-flow-back:hover,
.is-cash-flow .cash-flow-back:focus-visible {
  color: #fff;
}

.is-cash-flow .cash-flow-page {
  gap: 0;
  width: min(100%, 1660px);
  padding: 0 clamp(18px, 3.2vw, 54px) 64px;
}

.is-cash-flow .cash-flow-toolbar,
.is-cash-flow .cash-flow-section,
.is-cash-flow .cash-flow-kpis,
.is-cash-flow .cash-flow-kpi,
.is-cash-flow .cash-flow-breakdown {
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.is-cash-flow .cash-flow-toolbar {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 30px;
  padding: 18px 0;
  border-top: 1px solid var(--cash-flow-border);
  border-bottom: 1px solid var(--cash-flow-border);
}

.is-cash-flow .cash-flow-toolbar h2,
.is-cash-flow .cash-flow-section h2 {
  margin: 5px 0 0;
  color: var(--cash-flow-text);
  font: 650 clamp(1.1rem, 1.75vw, 1.55rem)/1.12 "Space Grotesk", sans-serif;
  letter-spacing: -0.035em;
}

.is-cash-flow .cash-flow-toolbar p,
.is-cash-flow .cash-flow-section header p {
  margin: 6px 0 0;
  color: var(--cash-flow-muted);
  font-size: 0.72rem;
  line-height: 1.45;
}

.is-cash-flow .cash-flow-period-controls,
.is-cash-flow .cash-flow-ledger-filters {
  display: flex;
  align-items: end;
  gap: 8px;
}

.is-cash-flow .cash-flow-period-controls label,
.is-cash-flow .cash-flow-ledger-filters label {
  display: grid;
  gap: 5px;
}

.is-cash-flow :is(.cash-flow-period-controls, .cash-flow-ledger-filters) label > span {
  color: #70706d;
  font-size: 0.61rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.is-cash-flow :is(.cash-flow-period-controls, .cash-flow-ledger-filters) :is(select, input),
.is-cash-flow .cash-flow-period-controls button {
  min-height: 36px;
  padding: 0 11px;
  border: 1px solid #2b2b2b;
  border-radius: 3px;
  outline: none;
  background: #090909;
  color: #ededeb;
  box-shadow: none;
  font: 650 0.72rem/1 "Plus Jakarta Sans", sans-serif;
}

.is-cash-flow .cash-flow-period-controls button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
}

.is-cash-flow .cash-flow-period-controls button span {
  color: var(--cash-flow-accent);
  font-size: 1rem;
  line-height: 1;
}

.is-cash-flow :is(.cash-flow-period-controls, .cash-flow-ledger-filters) :is(select, input):focus,
.is-cash-flow .cash-flow-period-controls button:focus-visible,
.is-cash-flow .cash-flow-period-controls button:hover {
  border-color: #5a5a56;
  background: #0e0e0e;
}

.is-cash-flow .cash-flow-kpis {
  display: grid;
  grid-template-columns: 1.25fr 1fr 1fr;
  gap: 0;
  border-bottom: 1px solid var(--cash-flow-border);
}

.is-cash-flow .cash-flow-kpi {
  position: relative;
  display: grid;
  align-content: center;
  gap: 9px;
  min-width: 0;
  min-height: 164px;
  padding: 28px clamp(18px, 2.6vw, 42px);
  border: 0;
}

.is-cash-flow .cash-flow-kpi:first-child {
  padding-left: 0;
}

.is-cash-flow .cash-flow-kpi + .cash-flow-kpi {
  border-left: 1px solid var(--cash-flow-border);
}

.is-cash-flow .cash-flow-kpi > span {
  color: var(--cash-flow-muted);
  font-size: 0.68rem;
  font-weight: 750;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.is-cash-flow .cash-flow-kpi strong {
  overflow: hidden;
  color: var(--cash-flow-text);
  font: 700 clamp(1.55rem, 3vw, 2.7rem)/0.95 "Space Grotesk", sans-serif;
  letter-spacing: -0.055em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.is-cash-flow .cash-flow-kpi.is-net strong {
  font-size: clamp(1.85rem, 3.8vw, 3.35rem);
}

.is-cash-flow .cash-flow-kpi.is-income strong { color: var(--cash-flow-income); }
.is-cash-flow .cash-flow-kpi.is-cost strong,
.is-cash-flow .cash-flow-kpi.is-negative strong { color: var(--cash-flow-cost); }

.is-cash-flow .cash-flow-kpi small {
  color: #6f6f6b;
  font-size: 0.67rem;
  font-weight: 600;
}

.is-cash-flow .cash-flow-section {
  min-width: 0;
  padding: 38px 0 42px;
  border: 0;
  border-bottom: 1px solid var(--cash-flow-border);
}

.is-cash-flow .cash-flow-section > header,
.is-cash-flow .cash-flow-breakdown > header {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 20px;
}

.is-cash-flow .cash-flow-legend {
  display: flex;
  gap: 18px;
  color: var(--cash-flow-muted);
  font-size: 0.67rem;
  font-weight: 800;
}

.is-cash-flow .cash-flow-legend span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.is-cash-flow .cash-flow-legend span::before {
  width: 16px;
  height: 2px;
  border-radius: 0;
  background: currentColor;
  content: "";
}

.is-cash-flow .cash-flow-legend .is-income { color: var(--cash-flow-income); }
.is-cash-flow .cash-flow-legend .is-cost { color: var(--cash-flow-cost); }

.is-cash-flow .cash-flow-chart-stage {
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr);
  gap: 12px;
  min-width: 0;
  margin-top: 28px;
}

.is-cash-flow .cash-flow-chart-axis {
  display: grid;
  grid-template-rows: repeat(3, 1fr);
  height: 294px;
  padding-bottom: 22px;
  color: #646460;
  font: 650 0.6rem/1 "Plus Jakarta Sans", sans-serif;
  text-align: right;
}

.is-cash-flow .cash-flow-chart-axis span:nth-child(2) { align-self: center; }
.is-cash-flow .cash-flow-chart-axis span:last-child { align-self: end; }

.is-cash-flow .cash-flow-chart {
  display: grid;
  align-items: stretch;
  gap: clamp(2px, 0.34vw, 6px);
  min-height: 294px;
  margin: 0;
  padding: 0 0 0;
  border: 0;
  border-bottom: 1px solid #30302e;
  background: linear-gradient(to bottom, #242424 1px, transparent 1px) top / 100% 50% repeat-y;
}

.is-cash-flow .cash-flow-chart > .admin-empty {
  grid-column: 1 / -1;
  align-self: center;
}

.is-cash-flow .cash-flow-day {
  position: relative;
  display: grid;
  grid-template-rows: 1fr 22px;
  min-width: 0;
  outline: none;
}

.is-cash-flow .cash-flow-day-bars {
  display: flex;
  align-items: end;
  justify-content: center;
  gap: 2px;
  min-height: 0;
}

.is-cash-flow .cash-flow-day-bars i {
  width: min(6px, 44%);
  min-height: 0;
  border-radius: 2px 2px 0 0;
  transition: opacity 140ms ease, transform 140ms ease;
}

.is-cash-flow .cash-flow-day-bars .is-income { background: var(--cash-flow-income); }
.is-cash-flow .cash-flow-day-bars .is-cost { background: var(--cash-flow-cost); }

.is-cash-flow .cash-flow-day > span {
  align-self: end;
  padding-bottom: 6px;
  color: #676763;
  font-size: 0.59rem;
  font-weight: 650;
  text-align: center;
}

.is-cash-flow .cash-flow-day:hover i,
.is-cash-flow .cash-flow-day:focus i {
  opacity: 0.76;
  transform: scaleX(1.25);
}

.is-cash-flow .cash-flow-day:hover::after,
.is-cash-flow .cash-flow-day:focus::after {
  position: absolute;
  z-index: 10;
  bottom: calc(100% + 8px);
  left: 50%;
  width: max-content;
  max-width: min(270px, 70vw);
  padding: 9px 11px;
  border: 1px solid #383838;
  border-radius: 3px;
  background: #090909;
  color: #f5f5f2;
  content: attr(data-tooltip);
  font-size: 0.68rem;
  font-style: normal;
  font-weight: 650;
  line-height: 1.45;
  transform: translateX(-50%);
}

.is-cash-flow .cash-flow-breakdowns {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0;
  padding: 0;
}

.is-cash-flow .cash-flow-breakdown {
  min-width: 0;
  padding: 38px clamp(20px, 3vw, 48px) 42px 0;
}

.is-cash-flow .cash-flow-breakdown + .cash-flow-breakdown {
  padding-right: 0;
  padding-left: clamp(20px, 3vw, 48px);
  border-left: 1px solid var(--cash-flow-border);
}

.is-cash-flow .cash-flow-summary-list {
  display: grid;
  gap: 0;
  margin-top: 22px;
}

.is-cash-flow .cash-flow-summary-row {
  display: grid;
  grid-template-columns: minmax(150px, 0.9fr) minmax(80px, 1fr) auto;
  align-items: center;
  gap: 15px;
  min-height: 54px;
  border-top: 1px solid #1e1e1e;
}

.is-cash-flow .cash-flow-summary-row > div:first-child {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.is-cash-flow .cash-flow-summary-row strong,
.is-cash-flow .cash-flow-summary-row span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.is-cash-flow .cash-flow-summary-row strong {
  color: #dcdcd9;
  font-size: 0.75rem;
}

.is-cash-flow .cash-flow-summary-row span {
  color: #696965;
  font-size: 0.62rem;
}

.is-cash-flow .cash-flow-summary-row > b {
  color: #ececea;
  font: 680 0.76rem/1 "Space Grotesk", sans-serif;
  white-space: nowrap;
}

.is-cash-flow .cash-flow-summary-bar {
  height: 2px;
  overflow: hidden;
  border-radius: 0;
  background: #242424;
}

.is-cash-flow .cash-flow-summary-bar i {
  display: block;
  height: 100%;
  border-radius: 0;
  background: var(--cash-flow-income);
}

.is-cash-flow .cash-flow-summary-row.is-cost .cash-flow-summary-bar i { background: var(--cash-flow-cost); }

.is-cash-flow .cash-flow-ledger {
  padding-top: 44px;
}

.is-cash-flow .cash-flow-ledger-head {
  align-items: end !important;
}

.is-cash-flow .cash-flow-ledger-filters input {
  width: min(310px, 30vw);
}

.is-cash-flow .cash-flow-table-wrap {
  width: 100%;
  margin-top: 24px;
  overflow-x: auto;
}

.is-cash-flow .cash-flow-table {
  width: 100%;
  min-width: 1160px;
  border-collapse: collapse;
}

.is-cash-flow .cash-flow-table th,
.is-cash-flow .cash-flow-table td {
  padding: 14px 11px;
  border-bottom: 1px solid #1f1f1f;
  color: #cfcfcb;
  font-size: 0.7rem;
  line-height: 1.5;
  text-align: left;
  vertical-align: top;
}

.is-cash-flow .cash-flow-table th {
  position: sticky;
  top: 0;
  z-index: 2;
  border-top: 1px solid #2b2b2b;
  border-bottom-color: #353535;
  background: #000;
  color: #73736f;
  font-size: 0.59rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.is-cash-flow .cash-flow-table tbody tr:hover {
  background: #080808;
}

.is-cash-flow .cash-flow-table td strong,
.is-cash-flow .cash-flow-table td small {
  display: block;
}

.is-cash-flow .cash-flow-table td small {
  margin-top: 2px;
  color: #666662;
  font-size: 0.62rem;
}

.is-cash-flow .cash-flow-table .is-numeric {
  text-align: right;
  white-space: nowrap;
}

.is-cash-flow .cash-flow-table td.is-income strong { color: var(--cash-flow-income); }
.is-cash-flow .cash-flow-table td.is-cost strong { color: var(--cash-flow-cost); }
.is-cash-flow .cash-flow-table a { color: var(--cash-flow-accent); }

.is-cash-flow .cash-flow-chip {
  display: inline-flex;
  padding: 0;
  border: 0;
  border-radius: 0;
  font-size: 0.59rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  white-space: nowrap;
}

.is-cash-flow .cash-flow-chip::before {
  width: 5px;
  height: 5px;
  margin: 5px 6px 0 0;
  border-radius: 50%;
  background: currentColor;
  content: "";
}

.is-cash-flow .cash-flow-chip.is-income { color: var(--cash-flow-income); }
.is-cash-flow .cash-flow-chip.is-cost { color: var(--cash-flow-cost); }

.is-cash-flow .cash-flow-methodology {
  padding: 20px 0;
  border-bottom: 0;
}

.is-cash-flow .cash-flow-methodology summary {
  width: fit-content;
  cursor: pointer;
  color: #9b9b97;
  font-size: 0.7rem;
  font-weight: 750;
}

.is-cash-flow .cash-flow-methodology[open] summary { color: #f1f1ef; }

.is-cash-flow .cash-flow-methodology > div {
  display: grid;
  gap: 8px;
  max-width: 850px;
  margin-top: 17px;
}

.is-cash-flow .cash-flow-methodology p {
  margin: 0;
  color: #71716d;
  font-size: 0.7rem;
  line-height: 1.6;
}

@media (max-width: 980px) {
  .is-cash-flow .cash-flow-toolbar,
  .is-cash-flow .cash-flow-ledger-head {
    align-items: stretch !important;
    flex-direction: column;
  }

  .is-cash-flow .cash-flow-breakdowns {
    grid-template-columns: 1fr;
  }

  .is-cash-flow .cash-flow-breakdown,
  .is-cash-flow .cash-flow-breakdown + .cash-flow-breakdown {
    padding: 32px 0;
    border-left: 0;
  }

  .is-cash-flow .cash-flow-breakdown + .cash-flow-breakdown {
    border-top: 1px solid var(--cash-flow-border);
  }

  .is-cash-flow .cash-flow-ledger-filters input {
    width: min(430px, 58vw);
  }
}

@media (max-width: 680px) {
  .is-cash-flow .cash-flow-topbar {
    padding-bottom: 20px;
  }

  .is-cash-flow .cash-flow-page {
    padding-inline: 14px;
  }

  .is-cash-flow .cash-flow-period-controls,
  .is-cash-flow .cash-flow-ledger-filters {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .is-cash-flow .cash-flow-period-controls button,
  .is-cash-flow .cash-flow-ledger-filters label:last-child {
    grid-column: 1 / -1;
  }

  .is-cash-flow .cash-flow-ledger-filters input {
    width: 100%;
  }

  .is-cash-flow .cash-flow-kpis {
    grid-template-columns: 1fr 1fr;
  }

  .is-cash-flow .cash-flow-kpi {
    min-height: 118px;
    padding: 22px 0;
  }

  .is-cash-flow .cash-flow-kpi.is-net {
    grid-column: 1 / -1;
    min-height: 132px;
    border-bottom: 1px solid var(--cash-flow-border);
  }

  .is-cash-flow .cash-flow-kpi.is-income {
    padding-right: 16px;
  }

  .is-cash-flow .cash-flow-kpi.is-cost {
    padding-left: 16px;
  }

  .is-cash-flow .cash-flow-kpi.is-income,
  .is-cash-flow .cash-flow-kpi.is-cost {
    border-left: 0;
  }

  .is-cash-flow .cash-flow-kpi.is-cost {
    border-left: 1px solid var(--cash-flow-border);
  }

  .is-cash-flow .cash-flow-kpi strong {
    font-size: clamp(1.2rem, 6vw, 1.65rem);
  }

  .is-cash-flow .cash-flow-chart-stage {
    grid-template-columns: 44px minmax(520px, 1fr);
    overflow-x: auto;
  }

  .is-cash-flow .cash-flow-chart-axis {
    position: sticky;
    left: 0;
    z-index: 4;
    background: #000;
  }

  .is-cash-flow .cash-flow-summary-row {
    grid-template-columns: minmax(120px, 1fr) auto;
  }

  .is-cash-flow .cash-flow-summary-bar {
    grid-column: 1 / -1;
    grid-row: 2;
    margin-bottom: 8px;
  }

  .is-cash-flow .cash-flow-table {
    min-width: 0;
  }

  .is-cash-flow .cash-flow-table thead {
    display: none;
  }

  .is-cash-flow .cash-flow-table tbody,
  .is-cash-flow .cash-flow-table tr,
  .is-cash-flow .cash-flow-table td {
    display: block;
    width: 100%;
  }

  .is-cash-flow .cash-flow-table tr {
    position: relative;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px 16px;
    padding: 18px 0;
    border-bottom: 1px solid #282828;
  }

  .is-cash-flow .cash-flow-table td {
    padding: 0;
    border: 0;
  }

  .is-cash-flow .cash-flow-table td::before {
    display: block;
    margin-bottom: 3px;
    color: #5f5f5b;
    content: attr(data-label);
    font-size: 0.55rem;
    font-weight: 800;
    letter-spacing: 0.09em;
    text-transform: uppercase;
  }

  .is-cash-flow .cash-flow-table td:nth-child(3),
  .is-cash-flow .cash-flow-table td:nth-child(7) {
    grid-column: 1 / -1;
  }

  .is-cash-flow .cash-flow-table td.is-numeric {
    position: absolute;
    top: 18px;
    right: 0;
    width: auto;
    text-align: right;
  }

  .is-cash-flow .cash-flow-table td.is-numeric::before {
    display: none;
  }

  .is-cash-flow .cash-flow-table td:first-child,
  .is-cash-flow .cash-flow-table td:nth-child(2) {
    padding-right: 110px;
  }
}

/* Website commerce notifications and irreversible Hard Set cutover. */
.admin-notification-button {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 54px;
  padding: 6px 16px 6px 7px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 999px;
  overflow: hidden;
  background: linear-gradient(180deg, rgba(255,255,255,.075), transparent 62%), #101012;
  color: #fff;
  box-shadow: 0 18px 54px rgba(0,0,0,.38), inset 0 1px 0 rgba(255,255,255,.07);
  cursor: pointer;
  transition: transform 180ms ease, border-color 180ms ease;
}

.admin-notification-button:hover { transform: translateY(-2px); border-color: rgba(255,255,255,.18); }
.admin-notification-button-icon {
  position: relative;
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  border-radius: 50%;
  background: rgba(255,255,255,.075);
}
.admin-notification-button svg,
.admin-notification-drawer svg {
  width: 21px;
  height: 21px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.admin-notification-button-icon > span {
  position: absolute;
  top: -3px;
  right: -3px;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border-radius: 999px;
  background: #fff;
  color: #000;
  font: 800 10px/20px "Space Grotesk", sans-serif;
  text-align: center;
  box-shadow: 0 4px 14px rgba(0,0,0,.35);
}
.admin-notification-button-copy { display: grid; gap: 2px; text-align: left; }
.admin-notification-button-copy strong { color: #fff; font: 650 13px/1.2 "Space Grotesk", sans-serif; letter-spacing: -.02em; }
.admin-notification-button-copy small { color: rgba(255,255,255,.38); font: 500 11px/1.2 "Plus Jakarta Sans", sans-serif; white-space: nowrap; }
.admin-notification-button:not(:has(.admin-notification-button-icon > span:not([hidden]))) .admin-notification-button-icon {
  animation: none;
}
.admin-notification-button:has(.admin-notification-button-icon > span:not([hidden])) .admin-notification-button-icon {
  animation: admin-notification-bell 3.6s ease-in-out infinite;
}

.admin-notification-drawer {
  position: fixed;
  z-index: 10030;
  top: 82px;
  right: 22px;
  width: min(440px, calc(100vw - 28px));
  max-height: calc(100vh - 102px);
  padding: 20px;
  overflow-y: auto;
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 38px;
  background: linear-gradient(180deg, rgba(255,255,255,.07), transparent 32%), #101012;
  color: #fff;
  box-shadow: 0 38px 130px rgba(0,0,0,.72), inset 0 1px 0 rgba(255,255,255,.08);
  opacity: 0;
  pointer-events: none;
  transform: translateY(-16px) scale(.94);
  transform-origin: top right;
  filter: blur(12px);
  transition: opacity 320ms ease, transform 420ms cubic-bezier(.16,1,.3,1), filter 320ms ease;
}

.admin-notification-drawer.is-open { opacity: 1; pointer-events: auto; transform: translateY(0) scale(1); filter: blur(0); }
.admin-notification-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 14px; margin-bottom: 18px; }
.admin-notification-head-main { display: flex; align-items: center; gap: 11px; min-width: 0; }
.admin-notification-head h2 { margin: 0; color: #fff; font: 650 24px/.95 "Space Grotesk", sans-serif; letter-spacing: -.05em; }
.admin-notification-mode { margin: 7px 0 0; color: rgba(255,255,255,.38); font-size: 12px; line-height: 1.35; letter-spacing: -.01em; }
.admin-notification-store-icon,
.admin-notification-round-btn {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  flex: 0 0 48px;
  border: 0;
  border-radius: 19px;
  background: rgba(255,255,255,.075);
  color: #fff;
}
.admin-notification-round-btn { width: 40px; height: 40px; flex-basis: 40px; border-radius: 50%; cursor: pointer; }
.admin-notification-round-btn[hidden] { display: none; }
.admin-notification-drawer .admin-notification-head .admin-orders-icon-btn {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  border: 0 !important;
  border-radius: 50%;
  background: transparent !important;
  color: rgba(255,255,255,.42);
}
.admin-notification-drawer .admin-notification-head .admin-orders-icon-btn:hover { background: rgba(255,255,255,.06) !important; color: rgba(255,255,255,.85); }
.admin-notification-backdrop { position: fixed; z-index: 10020; inset: 0; background: transparent; }
.admin-notification-list { display: grid; gap: 8px; min-height: 90px; }

.admin-notification-order-row {
  --notification-index: 0;
  position: relative;
  display: flex;
  align-items: center;
  gap: 11px;
  width: 100%;
  padding: 11px;
  border: 1px solid rgba(255,255,255,.075);
  border-radius: 26px;
  background: rgba(255,255,255,.04);
  color: #fff;
  text-align: left;
  cursor: pointer;
  opacity: 0;
  animation: admin-notification-row-in 300ms ease forwards;
  animation-delay: calc(var(--notification-index) * 45ms);
  transition: background 180ms ease, border-color 180ms ease, transform 180ms ease;
}
.admin-notification-order-row:hover { background: rgba(255,255,255,.07); border-color: rgba(255,255,255,.13); transform: translateX(2px); }
.admin-notification-user-icon,
.admin-notification-package-icon {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  flex: 0 0 46px;
  border-radius: 18px;
  background: #fff;
  color: #000;
}
.admin-notification-order-copy { display: grid; min-width: 0; flex: 1; }
.admin-notification-customer { display: flex; align-items: center; gap: 7px; min-width: 0; }
.admin-notification-customer strong { overflow: hidden; color: #fff; font: 650 14px/1.2 "Space Grotesk", sans-serif; letter-spacing: -.03em; text-overflow: ellipsis; white-space: nowrap; }
.admin-notification-customer i { width: 7px; height: 7px; flex: 0 0 7px; border-radius: 50%; background: #fff; }
.admin-notification-order-copy small { margin-top: 4px; color: rgba(255,255,255,.4); font: 500 12px/1.25 "Plus Jakarta Sans", sans-serif; }
.admin-notification-order-copy em { margin-top: 4px; overflow: hidden; color: rgba(255,255,255,.27); font: 500 10px/1.25 "Plus Jakarta Sans", sans-serif; text-overflow: ellipsis; white-space: nowrap; }
.admin-notification-row-time { display: flex; align-items: center; gap: 2px; color: rgba(255,255,255,.28); font-size: 10px; white-space: nowrap; }
.admin-notification-row-time svg { width: 15px; height: 15px; }

.admin-notification-detail { animation: admin-notification-panel-in 320ms cubic-bezier(.22,1,.36,1) both; }
.admin-notification-order-card,
.admin-notification-paid-banner,
.admin-notification-deadline {
  border: 1px solid rgba(255,255,255,.075);
  background: rgba(255,255,255,.04);
}
.admin-notification-order-card { padding: 15px; border-radius: 30px; }
.admin-notification-order-identity { display: flex; align-items: flex-start; gap: 11px; }
.admin-notification-order-identity > div { min-width: 0; }
.admin-notification-order-identity small { color: rgba(255,255,255,.3); font-size: 10px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
.admin-notification-order-identity h3 { margin: 4px 0 0; color: #fff; font: 650 21px/1 "Space Grotesk", sans-serif; letter-spacing: -.05em; }
.admin-notification-order-identity p { margin: 6px 0 0; color: rgba(255,255,255,.4); font-size: 12px; }
.admin-notification-order-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 14px; }
.admin-notification-order-stats div { padding: 11px; border-radius: 20px; background: rgba(0,0,0,.2); }
.admin-notification-order-stats small { display: block; color: rgba(255,255,255,.3); font-size: 10px; }
.admin-notification-order-stats strong { display: block; margin-top: 4px; color: #fff; font: 650 16px/1.15 "Space Grotesk", sans-serif; letter-spacing: -.04em; }
.admin-notification-line-items { display: grid; gap: 6px; margin-top: 10px; }
.admin-notification-line-items div { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 3px 8px; padding: 8px 10px; border-radius: 15px; background: rgba(0,0,0,.15); font-size: 11px; }
.admin-notification-line-items span { overflow: hidden; color: rgba(255,255,255,.7); text-overflow: ellipsis; white-space: nowrap; }
.admin-notification-line-items strong { color: #fff; }
.admin-notification-line-items small { grid-column: 1 / -1; color: rgba(255,255,255,.26); }
.admin-notification-warning { display: flex; align-items: flex-start; gap: 8px; margin-top: 11px; padding: 11px; border: 1px solid rgba(255,255,255,.07); border-radius: 20px; background: rgba(255,255,255,.035); }
.admin-notification-warning svg { width: 16px; height: 16px; flex: 0 0 16px; color: rgba(255,255,255,.48); }
.admin-notification-warning p { margin: 0; color: rgba(255,255,255,.4); font-size: 11px; line-height: 1.5; }
.admin-notification-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 13px; }
.admin-notification-actions button,
.admin-notification-submit { min-height: 48px; border: 1px solid rgba(255,255,255,.09); border-radius: 999px; background: rgba(255,255,255,.045); color: rgba(255,255,255,.68); font: 650 13px/1 "Space Grotesk", sans-serif; cursor: pointer; }
