.admin-notification-paid-banner { display: flex; align-items: center; gap: 11px; margin-bottom: 13px; padding: 11px; border-radius: 25px; }
.admin-notification-paid-banner > span { display: grid; place-items: center; width: 42px; height: 42px; flex: 0 0 42px; border-radius: 16px; background: #fff; color: #000; }
.admin-notification-paid-banner strong,
.admin-notification-paid-banner small { display: block; }
.admin-notification-paid-banner strong { color: #fff; font: 650 14px/1.2 "Space Grotesk", sans-serif; }
.admin-notification-paid-banner small { margin-top: 4px; color: rgba(255,255,255,.38); font-size: 11px; }
.admin-notification-dropzone { display: flex; min-height: 165px; align-items: center; justify-content: center; flex-direction: column; border: 1px dashed rgba(255,255,255,.14); border-radius: 30px; background: rgba(255,255,255,.035); color: #fff; cursor: pointer; transition: background 180ms ease, border-color 180ms ease; }
.admin-notification-dropzone:hover,
.admin-notification-dropzone.is-dragging { border-color: rgba(255,255,255,.35); background: rgba(255,255,255,.075); }
.admin-notification-upload-icon { display: grid; place-items: center; width: 62px; height: 62px; margin-bottom: 11px; border-radius: 23px; background: rgba(255,255,255,.075); color: rgba(255,255,255,.78); animation: admin-notification-upload-float 2s ease-in-out infinite; }
.admin-notification-dropzone.has-file .admin-notification-upload-icon { background: #fff; color: #000; animation: none; }
.admin-notification-upload-icon svg { width: 28px; height: 28px; }
.admin-notification-dropzone > strong { max-width: 280px; overflow: hidden; color: #fff; font: 650 14px/1.2 "Space Grotesk", sans-serif; text-overflow: ellipsis; white-space: nowrap; }
.admin-notification-dropzone > small { margin-top: 5px; color: rgba(255,255,255,.34); font-size: 11px; }
.admin-notification-deadline { margin-top: 13px; padding: 14px; border-radius: 27px; }
.admin-notification-deadline > div,
.admin-notification-deadline > small { display: flex; align-items: center; justify-content: space-between; }
.admin-notification-deadline > div > span { display: flex; align-items: center; gap: 7px; color: rgba(255,255,255,.74); font-size: 12px; font-weight: 650; }
.admin-notification-deadline > div svg { width: 16px; height: 16px; }
.admin-notification-deadline > div > strong { padding: 5px 11px; border-radius: 999px; background: #fff; color: #000; font: 700 11px/1 "Space Grotesk", sans-serif; }
.admin-notification-deadline input { width: 100%; margin: 13px 0 8px; accent-color: #fff; }
.admin-notification-deadline > small { color: rgba(255,255,255,.3); font-size: 9px; }
.admin-notification-submit { display: flex; align-items: center; justify-content: center; gap: 7px; width: 100%; margin-top: 13px; }
.admin-notification-submit svg { width: 17px; height: 17px; }
.admin-notification-submit:disabled { border-color: transparent; background: rgba(255,255,255,.07); color: rgba(255,255,255,.28); box-shadow: none; cursor: not-allowed; }
.admin-order-publication-error { color: #ff6678 !important; font-size: 12px; }
.admin-notification-result { display: flex; min-height: 315px; align-items: center; justify-content: center; flex-direction: column; text-align: center; animation: admin-notification-panel-in 340ms ease both; }
.admin-notification-result-icon { display: grid; place-items: center; width: 82px; height: 82px; margin-bottom: 18px; border-radius: 50%; background: rgba(255,255,255,.075); color: #fff; }
.admin-notification-result-icon.is-submitted { background: #fff; color: #000; }
.admin-notification-result-icon svg { width: 38px; height: 38px; }
.admin-notification-result h3 { margin: 0; color: #fff; font: 650 25px/1 "Space Grotesk", sans-serif; letter-spacing: -.06em; }
.admin-notification-result p { max-width: 300px; margin: 10px 0 0; color: rgba(255,255,255,.42); font-size: 12px; line-height: 1.55; }
.admin-notification-empty { display: grid; min-height: 220px; place-items: center; align-content: center; text-align: center; }
.admin-notification-empty span { display: grid; place-items: center; width: 58px; height: 58px; margin-bottom: 12px; border-radius: 50%; background: rgba(255,255,255,.075); color: #fff; font-size: 24px; }
.admin-notification-empty strong { color: #fff; font-family: "Space Grotesk", sans-serif; }
.admin-notification-empty p { margin: 6px 0 0; color: rgba(255,255,255,.34); font-size: 11px; }

