.admin-accounting-receipt-gallery > aside span { display:grid; gap:2px; min-width:0; }
.admin-accounting-receipt-gallery > aside strong { overflow:hidden; font-size:.64rem; text-overflow:ellipsis; white-space:nowrap; }
.admin-accounting-receipt-gallery > aside small { color:var(--accounting-muted); font-size:.55rem; }

.admin-accounting-receipt-stage {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  min-width: 0;
  min-height: 0;
  background: #fff;
}

.admin-accounting-receipt-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 42px;
  padding: 6px 10px;
  border-bottom: 1px solid #e7e7e7;
  background: #f8f8f8;
  color: #333;
}

.admin-accounting-receipt-nav[hidden] { display:none; }
.admin-accounting-receipt-nav strong { min-width:56px; font-size:.66rem; text-align:center; }
.admin-accounting-receipt-nav button { width:28px; height:28px; padding:0; border:1px solid #d8d8d8; border-radius:50%; background:#fff; color:#333; cursor:pointer; }
.admin-accounting-receipt-nav button:disabled { opacity:.32; cursor:default; }

.admin-accounting-receipt-preview {
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  background: #ffffff;
  overflow: auto;
}

.admin-accounting-receipt-preview > p {
  max-width: 520px;
  margin: 0;
  padding: 30px;
  color: #676767;
  font-size: .78rem;
  font-weight: 750;
  line-height: 1.5;
  text-align: center;
}

.admin-accounting-receipt-preview > img {
  display: block;
  max-width: 100%;
  max-height: 100%;
  margin: auto;
  object-fit: contain;
}

.admin-accounting-receipt-preview > object {
  width: 100%;
  height: 100%;
  border: 0;
}

.admin-accounting-receipt-preview > [hidden] {
  display: none !important;
}

.admin-accounting-receipt-actions {
  display: flex;
  align-items: center;
  gap: 14px;
}

.admin-accounting-receipt-actions > span { color:var(--accounting-text); font-size:.65rem; font-weight:850; white-space:nowrap; }
.admin-accounting-receipt-actions > .admin-soft-btn { min-height:30px; padding:0 10px; font-size:.62rem; white-space:nowrap; }

.admin-accounting-receipt-actions > a {
  color: var(--accounting-muted);
  font-size: .7rem;
  font-weight: 800;
  text-decoration: none;
}

.admin-accounting-receipt-actions > a:hover {
  color: var(--accounting-text);
}

.admin-accounting-receipt-close {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: var(--accounting-muted);
  cursor: pointer;
}

.admin-accounting-receipt-close:hover,
.admin-accounting-receipt-close:focus-visible {
  color: var(--accounting-text);
  background: color-mix(in srgb, var(--accounting-text) 7%, transparent);
}

.admin-accounting-receipt-close svg {
  width: 19px;
  height: 19px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
}

.admin-accounting-review {
  padding: 0;
}

.admin-accounting-review > summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 20px;
  cursor: pointer;
}

.admin-accounting-review > summary span {
  color: var(--accounting-text);
  font-size: .78rem;
  font-weight: 800;
}

.admin-accounting-review > summary b {
  display: inline-grid;
  place-items: center;
  min-width: 24px;
  height: 24px;
  margin-right: 7px;
  border-radius: 999px;
  background: var(--accounting-text);
  color: var(--admin-bg);
}

.admin-accounting-review > summary small {
  color: var(--accounting-muted);
  font-size: .68rem;
}

.admin-accounting-review > div {
  padding: 0 20px 20px;
}

.admin-accounting-breakdown-card,
.admin-accounting-reconcile-card {
  width: min(720px, calc(100vw - 28px));
  max-height: calc(100svh - 28px);
  border-radius: 20px;
  background: var(--accounting-surface);
  color: var(--accounting-text);
}

.admin-accounting-breakdown-card {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.admin-accounting-breakdown-card > .admin-modal-head {
  flex: 0 0 auto;
}

.admin-accounting-reconcile-card {
  overflow: auto;
}

.admin-accounting-breakdown-card .admin-modal-head p,
.admin-accounting-reconcile-card .admin-modal-head p {
  max-width: 560px;
  margin: 6px 0 0;
  color: var(--accounting-muted);
  font-size: .76rem;
  line-height: 1.5;
}

.admin-accounting-breakdown-body {
  display: grid;
  flex: 1 1 auto;
  gap: 8px;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding-right: 4px;
  scrollbar-gutter: stable;
  touch-action: pan-y;
}

.admin-accounting-breakdown-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(105px, auto) minmax(120px, auto);
  gap: 18px;
  align-items: center;
  width: 100%;
  padding: 14px;
  border: 1px solid var(--accounting-border);
  border-radius: 12px;
  background: transparent;
  color: var(--accounting-text);
  font: inherit;
  text-align: left;
}

button.admin-accounting-breakdown-row {
  cursor: pointer;
}

button.admin-accounting-breakdown-row:hover {
  background: color-mix(in srgb, var(--accounting-text) 4%, transparent);
}

.admin-accounting-breakdown-row > span {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.admin-accounting-breakdown-row > span:not(:first-child) {
  text-align: right;
}

.admin-accounting-breakdown-row strong,
.admin-accounting-breakdown-row small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-accounting-breakdown-row strong {
  font-size: .78rem;
}

.admin-accounting-breakdown-row small {
  color: var(--accounting-muted);
  font-size: .65rem;
}

.admin-accounting-partner-bill-toolbar,
.admin-accounting-partner-orders-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.admin-accounting-partner-bill-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid var(--accounting-border);
  border-radius: 14px;
}

.admin-accounting-partner-bill-summary > div {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 14px;
  border-right: 1px solid var(--accounting-border);
}

.admin-accounting-partner-bill-summary > div:last-child {
  border-right: 0;
}

.admin-accounting-partner-bill-summary span,
.admin-accounting-partner-orders-head span,
.admin-accounting-partner-order small {
  color: var(--accounting-muted);
  font-size: .65rem;
}

.admin-accounting-partner-bill-summary strong {
  overflow: hidden;
  font-size: .78rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-accounting-partner-orders {
  overflow: hidden;
  border: 1px solid var(--accounting-border);
  border-radius: 14px;
}

.admin-accounting-partner-orders-head {
  padding: 13px 15px;
  border-bottom: 1px solid var(--accounting-border);
  font-size: .76rem;
}

.admin-accounting-partner-order {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
  padding: 13px 15px;
  border-bottom: 1px solid var(--accounting-border);
}

.admin-accounting-partner-order:last-child {
  border-bottom: 0;
}

.admin-accounting-partner-order > span {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.admin-accounting-partner-order > span:last-child {
  text-align: right;
}

.admin-accounting-partner-order strong,
.admin-accounting-partner-order small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-accounting-partner-order strong {
  font-size: .73rem;
}

.admin-accounting-partner-order.is-removed {
  opacity: .58;
}

.admin-accounting-reconcile-card > form {
  display: grid;
  gap: 14px;
}

.admin-accounting-reconcile-card > form label {
  display: grid;
  gap: 7px;
}

.admin-accounting-reconcile-card > form label span {
  color: var(--accounting-muted);
  font-size: .7rem;
  font-weight: 800;
}

.admin-accounting-reconcile-card > form input {
  width: 100%;
  min-height: 46px;
  padding: 0 13px;
  border: 1px solid var(--accounting-border);
  border-radius: 10px;
  outline: 0;
  background: var(--accounting-surface);
  color: var(--accounting-text);
  font: 800 .86rem/1 "Space Grotesk", sans-serif;
}

.admin-accounting-reconcile-card > form > p {
  margin: 0;
  color: var(--accounting-muted);
  font-size: .68rem;
  line-height: 1.5;
}

.admin-accounting-reconcile-card > form > div {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.admin-accounting-view select,
.admin-accounting-view select option {
  color-scheme: dark;
}

:root[data-admin-theme='light'] .admin-accounting-view select,
:root[data-admin-theme='light'] .admin-accounting-view select option {
  color-scheme: light;
}

.admin-accounting-view select {
  appearance: auto;
  text-overflow: ellipsis;
}

.admin-accounting-view select option {
  background: var(--admin-bg);
  color: var(--admin-text);
}

@media (max-width: 1180px) {
  .admin-accounting-ledger-row {
    grid-template-columns: 76px 8px minmax(180px, 1fr) minmax(150px, .75fr) auto auto minmax(110px, auto);
    gap: 10px;
  }

  .admin-accounting-ledger-note {
    grid-column: 3 / 5;
    grid-row: 2;
  }

  .admin-accounting-ledger-row > .admin-accounting-review-receipt {
    grid-column: 5;
    grid-row: 1;
  }

  .admin-accounting-receipt-links.is-compact {
    grid-column: 5;
    grid-row: 1;
  }

  .admin-accounting-ledger-state {
    grid-column: 6;
    grid-row: 1;
  }

  .admin-accounting-ledger-amount-wrap {
    grid-column: 7;
    grid-row: 1;
  }
}

@media (max-width: 980px) {
  .admin-accounting-pulse {
    grid-template-columns: 1fr;
  }

  .admin-accounting-pulse-main {
    min-height: 0;
    border-right: 0;
    border-bottom: 1px solid var(--accounting-border);
  }

  .admin-accounting-more > div {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 680px) {
  .admin-accounting-pulse-main,
  .admin-accounting-wallets {
    padding: 18px;
  }

  .admin-accounting-pulse-main > strong {
    font-size: clamp(1.8rem, 10vw, 2.65rem);
  }

  .admin-accounting-wallet-strip,
  .admin-accounting-more > div {
    grid-template-columns: 1fr;
  }

  .admin-accounting-receipt-selection-head,
  .admin-accounting-receipt-management-list > div { align-items:stretch; flex-direction:column; }

  .admin-accounting-receipt-selection-grid { grid-template-columns:1fr; }

  .admin-accounting-receipt-card { height:calc(100svh - 14px); }
  .admin-accounting-receipt-card > .admin-modal-head { align-items:flex-start; }
  .admin-accounting-receipt-actions { flex-wrap:wrap; justify-content:flex-end; gap:7px; }
  .admin-accounting-receipt-actions > span { flex-basis:100%; text-align:right; }
  .admin-accounting-receipt-gallery { grid-template-columns:1fr; grid-template-rows:auto minmax(0,1fr); height:calc(100% - 112px); }
  .admin-accounting-receipt-gallery > aside { display:flex; gap:7px; padding:8px; overflow-x:auto; overflow-y:hidden; border-right:0; border-bottom:1px solid var(--accounting-border); }
  .admin-accounting-receipt-gallery > aside > button { flex:0 0 190px; }

  .admin-accounting-wallet-strip {
    max-height: 190px;
  }

  .admin-accounting-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .admin-accounting-ledger-row {
    grid-template-columns: 8px minmax(0, 1fr) auto;
    gap: 10px;
    padding: 12px 2px;
  }

  .admin-accounting-ledger-row time {
    display: none;
  }

  .admin-accounting-ledger-mark {
    grid-column: 1;
    grid-row: 1;
  }

  .admin-accounting-ledger-copy {
    grid-column: 2;
    grid-row: 1;
  }

  .admin-accounting-ledger-category {
    grid-column: 2;
    grid-row: 2;
  }

  .admin-accounting-ledger-note {
    grid-column: 2;
    grid-row: 3;
  }

  .admin-accounting-ledger-row > .admin-accounting-review-receipt {
    grid-column: 2;
    grid-row: 4;
    justify-self: start;
  }

  .admin-accounting-receipt-links.is-compact {
    grid-column: 2;
    grid-row: 4;
    justify-self: start;
  }

  .admin-accounting-ledger-state {
    display: none;
  }

  .admin-accounting-ledger-amount-wrap {
    grid-column: 3;
    grid-row: 1;
  }

  .admin-accounting-ledger-amount-wrap > small {
    display: none;
  }

  .admin-accounting-ledger-amount {
    font-size: .74rem;
  }

  .admin-accounting-breakdown-row {
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 10px;
  }

  .admin-accounting-breakdown-row > span:nth-child(2) {
    display: none;
  }

  .admin-accounting-partner-bill-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .admin-accounting-partner-bill-summary > div:nth-child(2) {
    border-right: 0;
  }

  .admin-accounting-partner-bill-summary > div:nth-child(-n + 2) {
    border-bottom: 1px solid var(--accounting-border);
  }

  .admin-accounting-review > summary {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-accounting-more > summary span {
    display: none;
  }
}

/* Accounting balance roles: bank, physical cash, and controlled entry accounts. */
.admin-accounting-view .admin-accounting-metrics {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.admin-accounting-pulse-main > .admin-accounting-cash-pocket {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 5px 16px;
  margin-top: 14px;
  padding: 13px 14px;
  border: 1px solid var(--accounting-border);
  border-radius: 13px;
  background: color-mix(in srgb, var(--accounting-text) 3%, transparent);
}

.admin-accounting-cash-pocket > span {
  color: var(--accounting-muted);
  font-size: .68rem;
  font-weight: 800;
}

.admin-accounting-cash-pocket > strong {
  color: var(--accounting-text);
  font: 800 1.05rem/1.1 "Space Grotesk", sans-serif;
}

.admin-accounting-cash-pocket > div {
  grid-column: 1 / -1;
  display: flex;
  gap: 8px;
}

.admin-accounting-cash-pocket button {
  min-height: 30px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--accounting-text);
  font: 800 .66rem/1 "Space Grotesk", sans-serif;
  cursor: pointer;
}

.admin-accounting-cash-pocket button + button {
  padding-left: 9px;
  border-left: 1px solid var(--accounting-border);
}

.admin-accounting-reconcile-card > form select {
  width: 100%;
  min-height: 46px;
  padding: 0 13px;
  border: 1px solid var(--accounting-border);
  border-radius: 10px;
  outline: 0;
  background: var(--accounting-surface);
  color: var(--accounting-text);
  font: 800 .8rem/1 "Space Grotesk", sans-serif;
}

.admin-accounting-account-settings-card {
  width: min(820px, calc(100vw - 28px));
  max-height: calc(100svh - 28px);
  overflow: auto;
  border-radius: 20px;
  background: var(--accounting-surface);
  color: var(--accounting-text);
}

.admin-accounting-account-settings-grid {
  display: grid;
  grid-template-columns: minmax(220px, .8fr) minmax(280px, 1.2fr);
  gap: 18px;
}

.admin-accounting-account-settings-grid > div {
  display: grid;
  align-content: start;
  gap: 7px;
}

.admin-accounting-account-settings-grid > div > button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  padding: 11px 12px;
  border: 1px solid var(--accounting-border);
  border-radius: 10px;
  background: transparent;
  color: var(--accounting-text);
  text-align: left;
  cursor: pointer;
}

.admin-accounting-account-settings-grid > div > button span {
  display: grid;
  gap: 3px;
  color: var(--accounting-muted);
  font-size: .6rem;
}

.admin-accounting-account-settings-grid > div > button strong {
  color: var(--accounting-text);
  font-size: .75rem;
}

.admin-accounting-account-settings-grid form {
  display: grid;
  gap: 11px;
  padding: 15px;
  border: 1px solid var(--accounting-border);
  border-radius: 13px;
}

.admin-accounting-account-settings-grid form > label:not(.admin-accounting-account-toggle) {
  display: grid;
  gap: 6px;
}

.admin-accounting-account-settings-grid form label > span {
  color: var(--accounting-muted);
  font-size: .68rem;
  font-weight: 800;
}

.admin-accounting-account-settings-grid form :is(input[type="text"], select) {
  width: 100%;
  min-height: 42px;
  padding: 0 11px;
  border: 1px solid var(--accounting-border);
  border-radius: 9px;
  background: var(--accounting-surface);
  color: var(--accounting-text);
}

.admin-accounting-account-toggle {
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 30px;
}

.admin-accounting-account-toggle input {
  width: 16px;
  height: 16px;
}

.admin-accounting-account-settings-grid form > div {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

@media (max-width: 980px) {
  .admin-accounting-view .admin-accounting-metrics {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 680px) {
  .admin-accounting-view .admin-accounting-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .admin-accounting-account-settings-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 1180px) {
  .admin-notification-button { width: 44px; min-height: 44px; padding: 1px; justify-content: center; }
  .admin-notification-button-icon { width: 40px; height: 40px; }
  .admin-notification-button-copy { display: none; }
}

:root[data-admin-theme='light'] {
  --admin-bg: #f3f5f2;
  --admin-surface: #ffffff;
  --admin-surface-strong: #ffffff;
  --admin-surface-soft: #f6f8f4;
  --admin-border: rgba(17, 24, 39, 0.08);
  --admin-text: #0c1117;
  --admin-muted: rgba(55, 65, 81, 0.68);
  --admin-shadow: 0 12px 28px rgba(15, 23, 42, 0.08);
}

* {
  box-sizing: border-box;
}

html, body {
  min-height: 100%;
  margin: 0;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  font-family: 'Plus Jakarta Sans', sans-serif;
  color: var(--admin-text);
  background: var(--admin-bg);
  overflow-x: hidden;
}

.admin-build-badge {
  position: fixed;
  right: 14px;
  bottom: 14px;
  z-index: 13000;
  padding: 8px 10px;
  border: 1px solid var(--admin-border);
  border-radius: 999px;
  background: rgba(9, 13, 18, 0.88);
  color: var(--admin-muted);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  box-shadow: var(--admin-shadow);
  backdrop-filter: blur(10px);
}

:root[data-admin-theme='light'] .admin-build-badge {
  background: rgba(255, 255, 255, 0.92);
}

a {
  color: inherit;
  text-decoration: none;
}

button, input {
  font: inherit;
}

.admin-body.is-loading {
  overflow: hidden;
}

.admin-body.is-loading .admin-app {
  opacity: 0;
  visibility: hidden;
}

.admin-rotate-screen {
  display: none;
}

.admin-login-shell,
.admin-app {
  min-height: 100svh;
  position: relative;
}

.admin-login-shell {
  display: grid;
  place-items: center;
  padding: 32px;
}

.admin-loader {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: grid;
  place-items: center;
  padding: 24px;
  background: #090d12;
  transition: opacity 0.35s ease, visibility 0.35s ease;
}

.admin-body.is-ready .admin-loader {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.admin-loader-panel,
.admin-login-card,
.admin-hero-panel,
.admin-metric-card,
.admin-panel,
.admin-control-strip {
  border: 1px solid var(--admin-border);
  background: var(--admin-surface);
  box-shadow: var(--admin-shadow);
}

.admin-loader-panel {
  width: min(520px, 100%);
  padding: 32px;
  border-radius: 28px;
}

.admin-loader-panel h2,
.admin-login-brand h1,
.admin-topbar-brand h1,
.admin-hero-copy h2,
.admin-panel-head h3 {
  margin: 14px 0 10px;
  font-family: 'Space Grotesk', sans-serif;
  letter-spacing: -0.04em;
}

.admin-loader-panel h2,
.admin-login-brand h1,
.admin-topbar-brand h1 {
  font-size: clamp(2rem, 5vw, 4rem);
}

.admin-loader-panel p,
.admin-loader-label,
.admin-login-brand p,
.admin-topbar-brand p,
.admin-hero-copy p,
.admin-note-card span,
.admin-event-item span,
.admin-event-item small,
.admin-metric-card small,
.admin-empty,
.admin-live-status span {
  color: var(--admin-muted);
}

.admin-loader-bar {
  width: 100%;
  height: 12px;
  margin: 22px 0 14px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.08);
}

.admin-loader-progress {
  display: block;
  width: 8%;
  height: 100%;
  background: var(--admin-accent-primary);
  transition: width 0.25s ease;
}

.admin-login-card {
  width: min(560px, 100%);
  padding: 36px;
  border-radius: 28px;
}

.admin-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 13px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  border: 1px solid var(--admin-border);
  background: rgba(255, 255, 255, 0.04);
  color: var(--admin-text);
}

.admin-chip-accent {
  background: rgba(157, 255, 0, 0.12);
  border-color: rgba(157, 255, 0, 0.22);
}

.admin-login-form {
  display: grid;
  gap: 14px;
  margin-top: 26px;
}

.admin-login-form label,
.admin-control-label {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--admin-muted);
}

.admin-login-form input {
  width: 100%;
  padding: 18px;
  border-radius: 16px;
  border: 1px solid var(--admin-border);
  background: var(--admin-surface-soft);
  color: var(--admin-text);
  outline: none;
}

.admin-login-form input:focus {
  border-color: rgba(157, 255, 0, 0.42);
  box-shadow: inset 0 0 0 1px rgba(157, 255, 0, 0.32);
}

.admin-inline-input {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
}

.admin-primary-btn,
.admin-ghost-btn,
.admin-danger-btn,
.admin-soft-btn,
.admin-toggle-pill {
  border: 1px solid transparent;
  border-radius: 14px;
  padding: 13px 16px;
  cursor: pointer;
  transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
}

.admin-primary-btn {
  background: var(--admin-accent-primary);
  color: #091006;
  font-weight: 800;
}

.admin-link-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.admin-danger-btn {
  background: rgba(255, 82, 82, 0.14);
  border-color: rgba(255, 82, 82, 0.26);
  color: #ffd9d9;
  font-weight: 800;
}

.admin-ghost-btn,
.admin-soft-btn,
.admin-toggle-pill {
  background: var(--admin-surface-soft);
  border-color: var(--admin-border);
  color: var(--admin-text);
}

.admin-primary-btn:hover,
.admin-ghost-btn:hover,
.admin-danger-btn:hover,
.admin-soft-btn:hover,
.admin-toggle-pill:hover,
.admin-panel:hover,
.admin-metric-card:hover {
  transform: translateY(-2px);
}

.admin-select-wrap {
  position: relative;
  display: block;
  min-width: 220px;
}

.admin-select {
  width: 100%;
  padding: 13px 16px;
  border-radius: 14px;
  border: 1px solid var(--admin-border);
  background: var(--admin-surface-soft);
  color: var(--admin-text);
  outline: none;
  color-scheme: dark;
}

.admin-select:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.admin-select.admin-select-needs-brand {
  border-color: rgba(255, 90, 90, 0.34);
  color: var(--admin-accent-tertiary);
}

.admin-select option,
.admin-select optgroup,
.admin-sku-builder select option,
.admin-sku-builder select optgroup,
.admin-sku-form-grid select option,
.admin-sku-form-grid select optgroup {
  background: #111;
  color: var(--admin-text);
}

.admin-danger-btn:disabled,
.admin-primary-btn:disabled,
.admin-ghost-btn:disabled {
  opacity: 0.6;
  cursor: wait;
  transform: none;
}

.admin-panel-affiliates {
  margin-top: 28px;
}

.admin-affiliate-list {
  display: grid;
  gap: 18px;
}

.admin-affiliate-card {
  border: 1px solid var(--admin-border);
  border-radius: 22px;
  padding: 22px;
  background: var(--admin-surface-soft);
}

.admin-affiliate-head,
.admin-affiliate-actions,
.admin-modal-head,
.admin-modal-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.admin-affiliate-head h4,
.admin-modal-head h3 {
  margin: 12px 0 0;
  font-family: 'Space Grotesk', sans-serif;
  letter-spacing: -0.03em;
}

.admin-affiliate-meta {
  display: grid;
  gap: 6px;
  color: var(--admin-muted);
  font-size: 13px;
  text-align: right;
}

.admin-affiliate-editor,
.admin-affiliate-form {
  display: grid;
  gap: 18px;
  margin-top: 18px;
}

.admin-affiliate-field,
.admin-affiliate-form label,
.admin-affiliate-platforms {
  display: grid;
  gap: 12px;
}

.admin-affiliate-form label span,
.admin-affiliate-platforms legend {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--admin-muted);
}

.admin-affiliate-form input[type='text'] {
  width: 100%;
  padding: 16px 18px;
  border-radius: 16px;
  border: 1px solid var(--admin-border);
  background: var(--admin-surface-soft);
  color: var(--admin-text);
  outline: none;
}

.admin-affiliate-platforms {
  margin: 0;
  padding: 0;
  border: 0;
}

.admin-affiliate-platform-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 12px;
}

.admin-platform-choice,
.admin-affiliate-platform-grid label {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 52px;
  padding: 14px 16px;
  border: 1px solid var(--admin-border);
  border-radius: 16px;
  background: var(--admin-surface);
}

.admin-affiliate-url-list {
  display: grid;
  gap: 10px;
}

.admin-affiliate-url {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 16px;
  border: 1px solid var(--admin-border);
  border-radius: 16px;
  background: var(--admin-surface);
}

.admin-affiliate-url span,
.admin-form-error,
.admin-table-note {
  color: var(--admin-muted);
}

.admin-table-note {
  display: block;
  margin-top: 4px;
  font-size: 12px;
}

.admin-modal-shell {
  position: fixed;
  inset: 0;
  z-index: 10000;
  display: grid;
  place-items: center;
  padding: 24px;
}

.admin-modal-shell[hidden] {
  display: none;
}

.admin-modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(6, 10, 16, 0.72);
}

.admin-modal-card {
  position: relative;
  width: min(620px, 100%);
  padding: 26px;
  border-radius: 28px;
  border: 1px solid var(--admin-border);
  background: var(--admin-surface);
  box-shadow: var(--admin-shadow);
}

.admin-modal-card-partner {
  width: min(1120px, calc(100vw - 32px));
  max-height: min(88vh, 960px);
  overflow-y: auto;
}

.admin-form-error {
  margin: 0;
  font-size: 14px;
  color: #ff8e8e;
}

@media (max-width: 900px) {
  .admin-affiliate-head,
  .admin-affiliate-actions,
  .admin-modal-head,
  .admin-modal-actions,
  .admin-affiliate-url {
    flex-direction: column;
    align-items: flex-start;
  }

  .admin-affiliate-meta {
    text-align: left;
  }
}

/* Ad View: live-campaign workspace */
.admin-ad-view-toolbar {
  grid-template-columns: minmax(150px, 0.8fr) minmax(130px, 0.6fr) minmax(130px, 0.6fr) minmax(220px, 1.25fr) auto;
}

.admin-ad-view-search-field {
  min-width: 0;
}

.admin-ad-view-workspace {
  display: grid;
  grid-template-columns: minmax(360px, 0.82fr) minmax(0, 1.55fr);
  gap: 16px;
  align-items: start;
}

.admin-ad-view-live-panel,
.admin-ad-view-detail-panel,
.admin-ad-view-analysis-column,
.admin-ad-view-trend-panel {
  min-width: 0;
}

.admin-ad-view-analysis-column {
  display: grid;
  gap: 16px;
}

.admin-ad-view-live-panel {
  padding: 0;
  overflow: hidden;
}

.admin-ad-view-live-panel > .admin-panel-head {
  padding: 20px 20px 14px;
}

.admin-ad-view-live-list {
  display: grid;
  max-height: 980px;
  overflow: auto;
  border-top: 1px solid var(--admin-border);
}

.admin-ad-view-live-row {
  display: grid;
  grid-template-columns: 50px minmax(120px, 1fr) minmax(78px, auto) minmax(62px, auto);
  gap: 11px;
  align-items: center;
  width: 100%;
  padding: 14px 16px;
  border: 0;
  border-bottom: 1px solid var(--admin-border);
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition: background 160ms ease, box-shadow 160ms ease;
}

.admin-ad-view-live-row > .admin-ad-view-live-metric:nth-child(4) {
  display: none;
}

.admin-ad-view-live-row:hover {
  background: var(--admin-surface-soft);
}

.admin-ad-view-live-row.is-selected {
  background: color-mix(in srgb, var(--admin-accent-primary) 8%, var(--admin-surface));
  box-shadow: inset 3px 0 0 var(--admin-accent-primary);
}

.admin-ad-view-product-image {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  overflow: hidden;
  border: 1px solid var(--admin-border);
  border-radius: 10px;
  background: var(--admin-surface-soft);
  color: var(--admin-text);
  font-size: 1rem;
  font-weight: 900;
}

.admin-ad-view-product-image.is-large {
  width: 76px;
  height: 76px;
  border-radius: 15px;
}

.admin-ad-view-product-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.admin-ad-view-live-copy,
.admin-ad-view-live-metric,
.admin-ad-view-live-roas {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.admin-ad-view-live-copy strong {
  overflow: hidden;
  font-size: 0.78rem;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-ad-view-live-copy small,
.admin-ad-view-live-metric small,
.admin-ad-view-live-roas small {
  color: var(--admin-muted);
  font-size: 0.61rem;
}

.admin-ad-view-live-metric,
.admin-ad-view-live-roas {
  text-align: right;
}

.admin-ad-view-live-metric strong,
.admin-ad-view-live-roas strong {
  font-size: 0.72rem;
}

.admin-ad-view-live-roas strong {
  color: var(--admin-accent-primary);
}

.admin-ad-view-detail-panel {
  display: grid;
  gap: 22px;
  padding: 22px;
}

.admin-ad-view-detail-empty {
  display: grid;
  place-items: center;
  gap: 7px;
  min-height: 180px;
  padding: 24px;
  color: var(--admin-muted);
  text-align: center;
}

.admin-ad-view-detail-empty strong {
  color: var(--admin-text);
  font-size: 1rem;
}

.admin-ad-view-detail-head {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 16px;
  align-items: start;
}

.admin-ad-view-detail-head h3 {
  margin: 7px 0 5px;
  font-size: clamp(1.05rem, 2vw, 1.45rem);
  line-height: 1.2;
}

.admin-ad-view-detail-head p,
.admin-ad-view-detail-head small {
  margin: 0;
  color: var(--admin-muted);
  font-size: 0.72rem;
  line-height: 1.5;
}

.admin-ad-view-live-badge {
  display: inline-flex;
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(0, 211, 137, 0.12);
  color: #00d389;
  font-size: 0.62rem;
  font-weight: 900;
  text-transform: uppercase;
}

.admin-ad-view-shopee-metrics,
.admin-ad-view-profit-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.admin-ad-view-shopee-metrics article,
.admin-ad-view-profit-grid article {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 13px;
  border: 1px solid var(--admin-border);
  border-radius: 12px;
  background: var(--admin-surface-soft);
}

.admin-ad-view-shopee-metrics span,
.admin-ad-view-profit-grid span,
.admin-ad-view-shopee-metrics small,
.admin-ad-view-profit-grid small {
  color: var(--admin-muted);
  font-size: 0.62rem;
  line-height: 1.4;
}

.admin-ad-view-shopee-metrics strong,
.admin-ad-view-profit-grid strong {
  overflow: hidden;
  font-size: 0.92rem;
  text-overflow: ellipsis;
}

.admin-ad-view-profit-grid strong.is-negative {
  color: #ff6f7d;
}

.admin-ad-view-detail-section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 12px;
  padding-top: 2px;
}

.admin-ad-view-direct-metrics {
  border-top: 1px solid var(--admin-border);
  border-bottom: 1px solid var(--admin-border);
}

.admin-ad-view-direct-metrics > summary {
  padding: 10px 2px;
  color: var(--admin-muted);
  cursor: pointer;
  font-size: 0.66rem;
  font-weight: 800;
}

.admin-ad-view-direct-metrics[open] > .admin-ad-view-shopee-metrics {
  padding: 0 0 12px;
}

.admin-ad-view-detail-section-head h4 {
  margin: 3px 0 0;
  font-size: 0.94rem;
}

.admin-ad-view-detail-section-head > small {
  color: var(--admin-muted);
  font-size: 0.65rem;
}

.admin-ad-view-settings-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
}

.admin-ad-view-settings-grid > span {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 11px 12px;
  border: 1px solid var(--admin-border);
  border-radius: 10px;
}

.admin-ad-view-settings-grid small {
  color: var(--admin-muted);
  font-size: 0.6rem;
}

.admin-ad-view-settings-grid strong {
  overflow: hidden;
  font-size: 0.7rem;
  text-overflow: ellipsis;
  text-transform: capitalize;
  white-space: nowrap;
}

.admin-ad-view-insights {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.admin-ad-view-insights article {
  padding: 12px 14px;
  border: 1px solid var(--admin-border);
  border-left: 3px solid var(--admin-muted);
  border-radius: 10px;
  background: var(--admin-surface-soft);
}

.admin-ad-view-insights article.is-positive { border-left-color: #00d389; }
.admin-ad-view-insights article.is-warning { border-left-color: #ffbc3e; }
.admin-ad-view-insights article.is-danger { border-left-color: #ff6073; }

.admin-ad-view-insights strong {
  font-size: 0.74rem;
}

.admin-ad-view-insights p {
  margin: 5px 0 0;
  color: var(--admin-muted);
  font-size: 0.67rem;
  line-height: 1.5;
}

.admin-ad-view-tools-panel,
.admin-ad-view-compare-panel {
  padding: 0;
  overflow: hidden;
}

.admin-ad-view-tools-panel > summary,
.admin-ad-view-compare-panel > summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 17px 20px;
  cursor: pointer;
  list-style: none;
}

.admin-ad-view-tools-panel > summary::-webkit-details-marker,
.admin-ad-view-compare-panel > summary::-webkit-details-marker {
  display: none;
}

.admin-ad-view-tools-panel > summary span,
.admin-ad-view-compare-panel > summary span {
  display: grid;
  gap: 3px;
}

.admin-ad-view-tools-panel > summary small,
.admin-ad-view-compare-panel > summary small,
.admin-ad-view-tools-panel > summary i,
.admin-ad-view-compare-panel > summary i {
  color: var(--admin-muted);
  font-size: 0.68rem;
  font-style: normal;
}

.admin-ad-view-tools-panel[open] > summary,
.admin-ad-view-compare-panel[open] > summary {
  border-bottom: 1px solid var(--admin-border);
}

.admin-ad-view-tools-panel .admin-ad-view-grid,
.admin-ad-view-compare-content {
  padding: 18px;
}

.admin-ad-view-editor {
  width: min(540px, calc(100vw - 30px));
  padding: 0;
  border: 1px solid var(--admin-border);
  border-radius: 18px;
  background: var(--admin-surface);
  color: var(--admin-text);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.55);
}

.admin-ad-view-editor::backdrop {
  background: rgba(0, 0, 0, 0.72);
  backdrop-filter: blur(5px);
}

.admin-ad-view-editor-card {
  display: grid;
  gap: 14px;
  padding: 22px;
}

.admin-ad-view-editor-card > p,
.admin-ad-view-editor-card > small {
  margin: 0;
  color: var(--admin-muted);
  font-size: 0.7rem;
  line-height: 1.5;
}

.admin-ad-view-editor-card label {
  display: grid;
  gap: 6px;
  color: var(--admin-muted);
  font-size: 0.68rem;
  font-weight: 800;
  text-transform: uppercase;
}

.admin-ad-view-editor-card input {
  min-height: 42px;
  padding: 0 12px;
  border: 1px solid var(--admin-border);
  border-radius: 10px;
  background: var(--admin-input-bg);
  color: var(--admin-text);
  font: inherit;
  text-transform: none;
}

.admin-ad-view-editor-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.admin-ad-view-library-panel[hidden] {
  display: none !important;
}

@media (max-width: 1320px) {
  .admin-ad-view-workspace {
    grid-template-columns: 1fr;
  }

  .admin-ad-view-live-list {
    max-height: 520px;
  }
}

@media (max-width: 980px) {
  .admin-ad-view-toolbar {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .admin-ad-view-shopee-metrics,
  .admin-ad-view-profit-grid,
  .admin-ad-view-settings-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 680px) {
  .admin-ad-view-live-row {
    grid-template-columns: 42px minmax(0, 1fr) auto;
  }

  .admin-ad-view-live-metric {
    display: none;
  }

  .admin-ad-view-detail-head {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .admin-ad-view-detail-head > button {
    grid-column: 1 / -1;
  }

  .admin-ad-view-shopee-metrics,
  .admin-ad-view-profit-grid,
  .admin-ad-view-settings-grid,
  .admin-ad-view-insights {
    grid-template-columns: 1fr;
  }
}


/* Final sidebar behavior: full-height icon rail that expands on hover/focus. */
@media (min-width: 821px) {
  :root,
  :root[data-admin-theme='dark'],
  :root[data-admin-theme='light'] {
    --admin-rail-width: 64px;
    --admin-rail-collapsed-width: 64px;
    --admin-rail-expanded-width: 168px;
  }

  .admin-shell,
  .admin-app[data-sku-db] .admin-shell {
    grid-template-columns: var(--admin-rail-collapsed-width) minmax(0, 1fr);
    gap: 28px;
  }

  .admin-shell .admin-rail,
  .admin-app.admin-app-suite .admin-rail,
  .admin-app[data-sku-db] .admin-rail {
    position: sticky;
    top: 0;
    width: var(--admin-rail-collapsed-width);
    min-height: 100svh;
    height: 100svh;
    margin-top: -24px;
    padding: 18px 8px 14px;
    overflow: hidden;
    border-width: 0 1px 0 0;
    border-radius: 0;
    box-shadow: none;
    transition: width 180ms ease, background 180ms ease, border-color 180ms ease;
    will-change: width;
  }

  .admin-shell .admin-rail:hover,
  .admin-shell .admin-rail:focus-within,
  .admin-app.admin-app-suite .admin-rail:hover,
  .admin-app.admin-app-suite .admin-rail:focus-within,
  .admin-app[data-sku-db] .admin-rail:hover,
  .admin-app[data-sku-db] .admin-rail:focus-within {
    width: var(--admin-rail-expanded-width);
    box-shadow: 18px 0 44px rgba(0, 0, 0, 0.22);
  }

  :root[data-admin-theme='light'] .admin-shell .admin-rail:hover,
  :root[data-admin-theme='light'] .admin-shell .admin-rail:focus-within,
  :root[data-admin-theme='light'] .admin-app.admin-app-suite .admin-rail:hover,
  :root[data-admin-theme='light'] .admin-app.admin-app-suite .admin-rail:focus-within,
  :root[data-admin-theme='light'] .admin-app[data-sku-db] .admin-rail:hover,
  :root[data-admin-theme='light'] .admin-app[data-sku-db] .admin-rail:focus-within {
    box-shadow: 18px 0 44px rgba(15, 23, 42, 0.12);
  }

  .admin-shell .admin-rail-brand,
  .admin-app[data-sku-db] .admin-rail-brand {
    grid-template-columns: 1fr;
    justify-items: center;
    gap: 0;
    height: 36px;
    padding: 0 0 18px;
