}

.admin-range-weekdays span {
  color: var(--admin-muted);
  text-align: center;
  font-size: 0.62rem;
  font-weight: 800;
}

.admin-range-day {
  position: relative;
  z-index: 0;
  display: grid;
  place-items: center;
  min-width: 0;
  height: 34px;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--admin-text);
  font: 800 0.72rem/1 "Plus Jakarta Sans", sans-serif;
  cursor: pointer;
}

.admin-range-day::before {
  content: "";
  position: absolute;
  top: 50%;
  right: 0;
  left: 0;
  height: 26px;
  z-index: -2;
  background: transparent;
  transform: translateY(-50%);
}

.admin-range-day::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 26px;
  height: 26px;
  z-index: -1;
  border-radius: 999px;
  background: transparent;
  transform: translate(-50%, -50%);
}

.admin-range-day-label {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  line-height: 1;
}

.admin-range-day.is-outside {
  color: rgba(255, 255, 255, 0.32);
}

.admin-range-day.is-today::after {
  border: 1px solid rgba(255, 255, 255, 0.18);
}

.admin-range-day.is-in-range::before {
  background: rgba(255, 210, 86, 0.26);
}

.admin-range-day.is-preview::before {
  background: rgba(255, 210, 86, 0.2);
}

.admin-range-day.is-final-range::before {
  background: rgba(255, 210, 86, 0.8);
}

.admin-range-day.is-selected-start::before {
  left: 50%;
}

.admin-range-day.is-selected-end::before {
  right: 50%;
}

.admin-range-day.is-selected-start::after,
.admin-range-day.is-selected-end::after {
  border: 2px solid #ffd256;
  background: #050505;
  color: var(--admin-text);
  box-shadow: none;
}

.admin-range-day.is-final-range {
  color: #050505;
}

.admin-range-day.is-final-range.is-outside {
  color: rgba(5, 5, 5, 0.52);
}

.admin-range-day.is-selected-start,
.admin-range-day.is-selected-end {
  color: var(--admin-text);
}

.admin-range-day.is-final-range.is-selected-start,
.admin-range-day.is-final-range.is-selected-end {
  color: var(--admin-text);
}

