.admin-order-view-btn {
  min-height: 24px;
  padding: 4px 8px;
  border-radius: 999px;
  border: 1px solid var(--admin-border);
  background: rgba(255, 255, 255, 0.06);
  color: var(--admin-text);
  font: 800 9.5px/1 "Plus Jakarta Sans", sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  cursor: pointer;
}

.admin-order-view-btn:hover,
.admin-order-view-btn:focus-visible {
  border-color: rgba(255, 217, 141, 0.58);
  color: #ffd98d;
}

.admin-order-popover {
  position: fixed;
  z-index: 2000;
  max-width: min(520px, calc(100vw - 24px));
