}

.admin-event-feed,
.admin-note-stack {
  display: grid;
  gap: 10px;
}

.admin-sandbox-stack {
  display: grid;
  gap: 12px;
}

.admin-sandbox-label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--admin-muted);
}

.admin-sandbox-textarea {
  width: 100%;
  min-height: 180px;
  padding: 16px 18px;
  border-radius: 18px;
  border: 1px solid var(--admin-border);
  background: var(--admin-surface-soft);
  color: var(--admin-text);
  font: 500 15px/1.6 "Plus Jakarta Sans", sans-serif;
  resize: vertical;
}

.admin-sandbox-textarea:focus {
  outline: none;
  border-color: rgba(41, 214, 107, 0.48);
  box-shadow: 0 0 0 1px rgba(41, 214, 107, 0.18);
}

.admin-sandbox-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.admin-code-block {
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  padding: 8px 10px;
  border-radius: 12px;
  background: rgba(10, 16, 23, 0.08);
  border: 1px solid var(--admin-border);
  color: var(--admin-text);
  font: 700 12px/1.4 "Space Grotesk", sans-serif;
  letter-spacing: 0.04em;
  overflow-wrap: anywhere;
}

.admin-event-feed {
  flex: 1 1 auto;
  min-height: 0;
  position: relative;
  max-height: 332px;
  overflow-y: auto;
  padding: 0 6px 0 0;
  align-content: start;
}

.admin-event-feed::before,
.admin-event-feed::after {
  content: '';
  position: sticky;
  left: 0;
  right: 6px;
  display: block;
  height: 26px;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.16s ease;
  z-index: 2;
}

.admin-event-feed::before {
  top: 0;
  margin-bottom: -26px;
  background: linear-gradient(to bottom, var(--admin-surface), transparent);
}

.admin-event-feed::after {
  bottom: 0;
  margin-top: -26px;
  background: linear-gradient(to top, var(--admin-surface), transparent);
}

.admin-event-feed.has-top-fade::before,
.admin-event-feed.has-bottom-fade::after {
  opacity: 1;
}

.admin-event-feed::-webkit-scrollbar {
  width: 10px;
}

.admin-event-feed::-webkit-scrollbar-thumb {
  background: var(--admin-border);
  border-radius: 999px;
}

.admin-event-item small {
  display: block;
  margin-top: 6px;
}

.admin-settings-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.admin-settings-card {
  display: grid;
  gap: 16px;
}

.admin-settings-card-wide {
  grid-column: 1 / -1;
}

.admin-settings-copy {
  margin: 0;
  color: var(--admin-muted);
  line-height: 1.6;
}

.admin-settings-form {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr) auto;
  gap: 14px;
  align-items: end;
}

.admin-settings-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.admin-settings-chip {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 48px;
  padding: 12px 14px;
  border-radius: 999px;
  border: 1px solid var(--admin-border);
  background: var(--admin-surface-soft);
}

.admin-settings-chip strong {
  font-size: 13px;
}

.admin-settings-chip span {
  color: var(--admin-muted);
  font-size: 12px;
}

.admin-settings-chip button {
  border: 0;
  background: transparent;
  color: var(--admin-accent-tertiary);
  font-weight: 800;
  cursor: pointer;
}

@keyframes adminFloat {
  from { transform: translate3d(0, 0, 0); }
  to { transform: translate3d(0, 16px, 0); }
}

@media (max-width: 1180px) {
