  .admin-control-strip,
  .admin-metric-grid,
  .admin-main-grid,
  .admin-chart-legend {
    grid-template-columns: 1fr 1fr;
  }

  .admin-menu-panel {
    min-width: 220px;
  }

  .admin-panel-wide {
    grid-column: auto;
  }

  .admin-settings-grid,
  .admin-settings-form {
    grid-template-columns: 1fr;
  }
