@media (max-width: 820px) {
  html, body {
    width: 100%;
    height: 100%;
  }

  .admin-app,
  .admin-login-shell {
    padding: 10px;
  }

  .admin-topbar {
    display: grid;
    grid-template-columns: 1fr auto;
    align-items: start;
    gap: 12px;
    margin-bottom: 12px;
  }

  .admin-hero-panel {
    grid-template-columns: 1.18fr 0.82fr;
    gap: 12px;
  }

  .admin-control-strip {
    grid-template-columns: 1fr 1fr auto;
    gap: 10px;
  }

  .admin-metric-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 10px;
  }

  .admin-main-grid {
    grid-template-columns: 1fr 1fr;
    gap: 10px;
  }

  .admin-chart-legend {
    grid-template-columns: 1fr 1fr;
  }

  .admin-login-card,
  .admin-loader-panel,
  .admin-hero-panel,
  .admin-control-strip,
  .admin-panel,
  .admin-metric-card {
