  }

  .admin-table th,
  .admin-table td {
    padding: 10px 8px;
    font-size: 12px;
  }

  .admin-chart-canvas {
    height: 220px;
  }

  .admin-chart-canvas-lg {
    height: 260px;
  }

  .admin-panel-head {
    gap: 6px;
  }

  .admin-live-status,
  .admin-status-pill {
    padding: 10px 12px;
  }

  .admin-settings-form {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 820px) and (orientation: portrait) {
