.admin-table-note {
  display: block;
  margin-top: 4px;
  font-size: 12px;
}

.admin-main-grid-sku {
  align-items: start;
}

.admin-sku-form-grid,
.admin-sku-builder,
.admin-sku-master-grid,
.admin-request-stack {
  display: grid;
  gap: 18px;
}

.admin-sku-form-grid {
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.admin-sku-master-create-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.admin-sku-master-create-grid .admin-sku-mini-form {
  align-content: start;
  gap: 8px;
}

.admin-sku-master-create-grid .admin-sku-mini-form input,
.admin-sku-master-create-grid .admin-sku-mini-form .admin-select {
  padding: 10px 12px;
}

.admin-sku-master-create-grid .admin-primary-btn {
  min-height: 36px;
  padding: 9px 12px;
  font-size: 12px;
}

.admin-sku-mini-form,
.admin-sku-builder label {
  display: grid;
  gap: 10px;
}

.admin-sku-mini-form input,
.admin-sku-builder input,
.admin-sku-cell-input,
.admin-sku-form-grid input {
  width: 100%;
  padding: 13px 16px;
  border-radius: 14px;
  border: 1px solid var(--admin-border);
  background: var(--admin-surface-soft);
  color: var(--admin-text);
  outline: none;
}

.admin-sku-mini-form input:focus,
.admin-sku-builder input:focus,
.admin-sku-cell-input:focus,
.admin-sku-form-grid input:focus {
  border-color: rgba(157, 255, 0, 0.42);
  box-shadow: inset 0 0 0 1px rgba(157, 255, 0, 0.32);
}

.admin-sku-builder {
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  align-items: end;
}

.admin-sku-preview {
  display: grid;
  gap: 8px;
  min-height: 100%;
  padding: 16px 18px;
  border-radius: 18px;
  border: 1px solid var(--admin-border);
  background: var(--admin-surface-soft);
}

.admin-sku-preview strong {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.35rem;
  letter-spacing: 0.08em;
}

.admin-sku-preview small,
.admin-muted-copy {
  color: var(--admin-muted);
}

.admin-sku-preview-wide,
.admin-sku-full-span {
  grid-column: 1 / -1;
}

.admin-sku-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

[data-cogs-modal] {
  --sku-bg: #090909;
  --sku-ink: #f5f5f5;
  --sku-muted: #969696;
  --sku-line: rgba(255, 255, 255, 0.13);
  --sku-panel: #121212;
  --cogs-accent: #f5f5f5;
  --cogs-accent-ink: #090909;
  --cogs-warning: #f2c94c;
  --sku-radius: 8px;
}

:root[data-admin-theme='light'] [data-cogs-modal] {
  --sku-bg: #f5f5f5;
  --sku-ink: #111111;
  --sku-muted: #686868;
  --sku-line: rgba(0, 0, 0, 0.14);
  --sku-panel: #ffffff;
  --cogs-accent: #111111;
  --cogs-accent-ink: #ffffff;
}

[data-cogs-modal] .admin-modal-card {
  display: flex;
  flex-direction: column;
  width: min(1040px, calc(100vw - 32px));
  height: min(900px, calc(100vh - 40px));
  max-height: 900px;
  padding: 0;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--sku-line) 82%, var(--cogs-accent));
  border-radius: 20px;
  background: var(--sku-bg);
}

[data-cogs-modal] .admin-modal-backdrop {
  background: rgba(0, 0, 0, 0.78);
}

.admin-cogs-editor-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  padding: 22px 24px 18px;
  border-bottom: 1px solid var(--sku-line);
  background: color-mix(in srgb, var(--sku-panel) 92%, transparent);
  flex: 0 0 auto;
}

.admin-cogs-editor-head h3 {
  margin: 5px 0 4px;
  color: var(--sku-ink);
  font: 850 clamp(1.35rem, 2vw, 1.7rem)/1.1 "Space Grotesk", Inter, sans-serif;
  letter-spacing: -0.025em;
}

.admin-cogs-editor-head p {
  margin: 0;
  color: var(--sku-muted);
  font-size: 0.82rem;
}

.admin-cogs-close {
  display: grid;
  flex: 0 0 36px;
  place-items: center;
  width: 36px;
  height: 36px;
  padding: 0;
  border: 1px solid var(--sku-line);
  border-radius: 50%;
  background: transparent;
  color: var(--sku-muted);
  font: 400 1.6rem/1 Inter, sans-serif;
  cursor: pointer;
}

.admin-cogs-close:hover,
.admin-cogs-close:focus-visible {
  border-color: var(--cogs-accent);
  color: var(--sku-ink);
  outline: none;
}

.admin-cogs-editor-form {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
}

.admin-cogs-context {
  display: grid;
  grid-template-columns: minmax(170px, 0.8fr) minmax(240px, 1.4fr) minmax(120px, 0.55fr);
  gap: 1px;
  margin: 16px 22px 0;
  overflow: hidden;
  border: 1px solid var(--sku-line);
  border-radius: 12px;
  background: var(--sku-line);
  flex: 0 0 auto;
}

.admin-cogs-context > div {
  display: grid;
  gap: 3px;
  min-width: 0;
  padding: 10px 12px;
  background: var(--sku-panel);
}

.admin-cogs-context span,
.admin-cogs-current-price span,
.admin-cogs-new-price > span {
  color: var(--sku-muted);
  font-size: 0.64rem;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.admin-cogs-context strong {
  overflow: hidden;
  color: var(--sku-ink);
  font-size: 0.83rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-cogs-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(300px, 340px);
  gap: 16px;
  min-height: 0;
  padding: 16px 22px 20px;
  overflow-y: auto;
  flex: 1 1 auto;
}

.admin-cogs-main-column,
.admin-cogs-side-column {
  display: grid;
  align-content: start;
  gap: 14px;
  min-width: 0;
}

.admin-cogs-side-column {
  position: sticky;
  top: 0;
}

.admin-cogs-step-card,
.admin-cogs-review {
  padding: 16px;
  border: 1px solid var(--sku-line);
  border-radius: 14px;
  background: var(--sku-panel);
}

.admin-cogs-step-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.admin-cogs-step-head > div:not(.admin-cogs-batch-tools) {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.admin-cogs-step-head strong {
  color: var(--sku-ink);
  font: 800 0.88rem/1.2 "Space Grotesk", Inter, sans-serif;
}

.admin-cogs-step-head small {
  overflow: hidden;
  color: var(--sku-muted);
  font-size: 0.7rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-cogs-step-number {
  display: grid;
  flex: 0 0 28px;
  place-items: center;
  width: 28px;
  height: 28px;
  border: 1px solid color-mix(in srgb, var(--cogs-accent) 48%, var(--sku-line));
  border-radius: 50%;
  background: color-mix(in srgb, var(--cogs-accent) 8%, transparent);
  color: var(--cogs-accent);
  font: 850 0.72rem/1 "Space Grotesk", Inter, sans-serif;
}

.admin-cogs-price-flow {
  display: grid;
  grid-template-columns: minmax(130px, 0.7fr) 28px minmax(200px, 1.25fr);
  align-items: center;
  gap: 10px;
}

.admin-cogs-current-price,
.admin-cogs-new-price {
  display: grid;
  gap: 7px;
}

.admin-cogs-current-price {
  padding: 12px 14px;
  border: 1px solid var(--sku-line);
  border-radius: 11px;
  background: color-mix(in srgb, var(--sku-bg) 55%, transparent);
}

.admin-cogs-current-price strong {
  color: var(--sku-ink);
  font: 850 1.15rem/1.2 "Space Grotesk", Inter, sans-serif;
}

.admin-cogs-price-arrow {
  color: var(--sku-muted);
  font-size: 1.25rem;
  text-align: center;
}

.admin-cogs-money-input {
  display: flex;
  align-items: center;
  min-height: 54px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--cogs-accent) 50%, var(--sku-line));
  border-radius: 11px;
  background: var(--sku-bg);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--cogs-accent) 5%, transparent);
}

.admin-cogs-money-input:focus-within {
  border-color: var(--cogs-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--cogs-accent) 12%, transparent);
}

.admin-cogs-money-input b {
  padding-left: 14px;
  color: var(--sku-muted);
  font: 800 0.82rem/1 Inter, sans-serif;
}

.admin-cogs-money-input input {
  width: 100%;
  min-width: 0;
  padding: 10px 13px 10px 5px;
  border: 0;
  background: transparent;
  color: var(--sku-ink);
  font: 850 1.35rem/1 "Space Grotesk", Inter, sans-serif;
  outline: none;
}

.admin-cogs-delta {
  grid-column: 3;
  justify-self: start;
  margin-top: -3px;
  color: var(--sku-muted);
  font-size: 0.72rem;
  font-weight: 750;
}

.admin-cogs-delta.is-up,
.admin-cogs-delta.is-down { color: var(--sku-ink); }

.admin-cogs-mode-panel {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  border: 0;
}

.admin-cogs-mode-option {
  position: relative;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  min-height: 68px;
  padding: 11px 12px;
  border: 1px solid var(--sku-line);
  border-radius: 11px;
  background: color-mix(in srgb, var(--sku-bg) 52%, transparent);
  cursor: pointer;
}

.admin-cogs-mode-option:has(input:checked) {
  border-color: color-mix(in srgb, var(--cogs-accent) 52%, var(--sku-line));
  background: color-mix(in srgb, var(--cogs-accent) 7%, transparent);
}

.admin-cogs-mode-option-danger:has(input:checked) {
  border-style: dashed;
  border-color: var(--cogs-accent);
  background: color-mix(in srgb, var(--cogs-accent) 7%, transparent);
}

.admin-cogs-mode-option input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.admin-cogs-mode-option > span:last-child {
  display: grid;
  gap: 4px;
}

.admin-cogs-mode-option strong {
  color: var(--sku-ink);
  font-size: 0.8rem;
}

.admin-cogs-mode-check {
