  .admin-cogs-batch-row em {
    grid-column: 3;
    grid-row: 1;
  }

  .admin-cogs-footer-actions {
    width: 100%;
  }

  .admin-cogs-footer-actions button {
    flex: 1;
    min-width: 0;
  }

  .admin-cogs-footer-actions [data-cogs-submit] {
    min-width: 0;
  }
