.admin-sku-tag-copy {
  display: inline-flex;
  align-items: center;
  max-width: 240px;
  padding: 6px 0;
  border: 0;
  background: transparent;
  color: var(--admin-text);
  cursor: pointer;
  font: inherit;
  font-weight: 700;
  overflow-wrap: anywhere;
  text-align: left;
}

.admin-sku-tag-copy:hover,
.admin-sku-tag-copy:focus-visible {
  color: var(--admin-accent-primary);
  outline: none;
}

.admin-sku-switch {
  position: relative;
  display: inline-flex;
  width: 48px;
  height: 26px;
  align-items: center;
  cursor: pointer;
}

.admin-sku-switch input {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: inherit;
}

.admin-sku-switch span {
  width: 100%;
  height: 100%;
  border-radius: 999px;
  border: 1px solid var(--admin-border);
  background: rgba(255, 255, 255, 0.08);
  transition: background 0.18s ease, border-color 0.18s ease;
}

.admin-sku-switch span::after {
  content: "";
  position: absolute;
  top: 4px;
  left: 4px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--admin-text);
  transition: transform 0.18s ease;
}

.admin-sku-switch input:checked + span {
  border-color: rgba(157, 255, 0, 0.46);
  background: rgba(157, 255, 0, 0.22);
}

.admin-sku-switch input:checked + span::after {
  transform: translateX(22px);
}

.admin-sku-switch input:focus-visible + span {
  outline: 2px solid rgba(157, 255, 0, 0.42);
  outline-offset: 2px;
}

.admin-sku-switch input:disabled + span {
  opacity: 0.58;
}

.admin-sku-copy-message {
  position: fixed;
  right: 22px;
  bottom: 22px;
  z-index: 10020;
  max-width: min(360px, calc(100vw - 32px));
  padding: 10px 14px;
  border: 1px solid rgba(157, 255, 0, 0.32);
  border-radius: 14px;
  background: rgba(12, 16, 20, 0.88);
  color: var(--admin-text);
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.28);
  font-size: 13px;
  font-weight: 700;
  line-height: 1.35;
  opacity: 1;
  transform: translateY(0);
  transition: opacity 0.34s ease, transform 0.34s ease;
}

.admin-sku-copy-message[hidden] {
  display: none;
}

.admin-sku-copy-message.is-error {
  border-color: rgba(255, 90, 90, 0.38);
}

.admin-sku-copy-message.is-center {
  top: 50%;
  right: auto;
  bottom: auto;
  left: 50%;
  transform: translate(-50%, -50%);
  padding: 16px 20px;
  border-color: rgba(157, 255, 0, 0.46);
  background: rgba(12, 16, 20, 0.94);
  font-size: 15px;
}

.admin-sku-copy-message.is-hiding {
  opacity: 0;
  transform: translateY(14px);
}

.admin-sku-copy-message.is-center.is-hiding {
  transform: translate(-50%, calc(-50% + 18px));
}

.admin-sku-master-grid {
