}

.admin-sku-token-action:focus-visible {
  border-color: rgba(0, 224, 184, 0.42);
  outline: none;
  box-shadow: 0 0 0 1px rgba(0, 224, 184, 0.18);
}

.admin-sku-token-remove {
  display: none;
  border: 1px solid rgba(255, 82, 82, 0.28);
  border-radius: 999px;
  background: rgba(255, 82, 82, 0.1);
  color: #ffb3b3;
  cursor: pointer;
  font: inherit;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
