@media (max-width: 700px) {
  .admin-sku-master-create-grid {
    grid-template-columns: 1fr;
  }
}

.admin-sku-brand-block {
  display: grid;
  gap: 10px;
}

.admin-sku-brand-block strong {
  font-size: 14px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
