.admin-modal-shell[hidden] {
  display: none;
}

.admin-modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(6, 10, 16, 0.72);
}

.admin-modal-card {
  position: relative;
  width: min(760px, 100%);
