/* Premium dark refinement: visual-only pass */
:root,
:root[data-admin-theme='light'] {
  --admin-bg: #000000;
  --admin-surface: transparent;
  --admin-surface-strong: transparent;
  --admin-surface-soft: rgba(255, 255, 255, 0.03);
  --admin-border: rgba(255, 255, 255, 0.08);
  --admin-text: #eaeaea;
  --admin-muted: #9a9a9a;
  --admin-shadow: none;
  --admin-accent-primary: #afff00;
  --admin-accent-secondary: #00ff88;
  --admin-accent-tertiary: #ff6b6b;
  --admin-accent-quaternary: #00e0b8;
  --admin-accent-gradient: linear-gradient(135deg, #afff00 0%, #00ff88 52%, #00e0b8 100%);
}

body {
  font-family: Inter, "Plus Jakarta Sans", sans-serif;
  background: #000000;
  color: var(--admin-text);
}

.admin-app {
  position: relative;
  padding: 28px 32px 40px;
}

.admin-topbar,
.admin-layout,
