/* Executive dashboard shell revamp */
:root,
:root[data-admin-theme='light'] {
  --admin-shell-max-width: 1680px;
  --admin-rail-width: 92px;
  --admin-surface-glass: rgba(255, 255, 255, 0.055);
  --admin-surface-glass-strong: rgba(255, 255, 255, 0.08);
  --admin-surface-panel: rgba(255, 255, 255, 0.028);
  --admin-surface-panel-strong: rgba(255, 255, 255, 0.04);
  --admin-rail-border: rgba(255, 255, 255, 0.1);
  --admin-green-soft: rgba(175, 255, 0, 0.18);
  --admin-green-line: rgba(175, 255, 0, 0.52);
}

body::before,
body::after {
  content: '';
  position: fixed;
  inset: auto;
  pointer-events: none;
  z-index: 0;
}

body::before {
  left: -12vw;
  bottom: -16vh;
  width: 48vw;
  height: 52vh;
  border-radius: 46px;
  background:
    linear-gradient(180deg, rgba(86, 255, 0, 0.14) 0%, rgba(0, 0, 0, 0) 78%),
    linear-gradient(135deg, rgba(175, 255, 0, 0.12) 0%, rgba(0, 224, 184, 0.06) 100%);
  filter: blur(18px);
  clip-path: polygon(0 84%, 17% 24%, 35% 0, 67% 0, 86% 22%, 100% 84%, 83% 84%, 64% 18%, 50% 18%, 31% 84%);
  opacity: 0.9;
}

body::after {
  top: 60px;
  right: 8vw;
  width: 24vw;
  height: 24vw;
  min-width: 220px;
  min-height: 220px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(0, 224, 184, 0.08) 0%, rgba(0, 0, 0, 0) 72%);
  filter: blur(24px);
}

.admin-app {
  width: min(100%, var(--admin-shell-max-width));
  margin: 0 auto;
  padding: 24px 28px 40px;
}

