}

.admin-rail-icon-overview::before,
.admin-rail-icon-overview::after,
.admin-rail-icon-overview span::before {
  content: '';
  position: absolute;
  border-radius: 999px;
  background: currentColor;
}

.admin-rail-icon-overview::before {
  left: 2px;
  right: 2px;
  bottom: 2px;
  height: 2px;
  opacity: 0.7;
}

.admin-rail-icon-overview::after {
  left: 4px;
  bottom: 5px;
  width: 5px;
  height: 9px;
  box-shadow: 7px -4px 0 currentColor, 14px -1px 0 currentColor;
}

.admin-rail-icon-overview span::before {
  left: 3px;
  top: 5px;
  width: 18px;
  height: 2px;
  transform: rotate(-24deg);
  transform-origin: left center;
}

.admin-rail-icon-campaigns::before,
.admin-rail-icon-campaigns::after,
.admin-rail-icon-campaigns span::before {
  content: '';
  position: absolute;
  background: currentColor;
}

.admin-rail-icon-rocket {
  transform: rotate(45deg);
}

.admin-rail-icon-rocket::before {
  content: '';
  position: absolute;
  left: 7px;
  top: 1px;
  width: 10px;
  height: 18px;
  border: 1.8px solid currentColor;
  border-radius: 70% 70% 42% 42%;
  clip-path: polygon(0 0, 100% 0, 100% 82%, 76% 82%, 50% 100%, 24% 82%, 0 82%);
}

.admin-rail-icon-rocket::after {
  content: '';
  position: absolute;
  left: 10px;
  top: 18px;
  width: 4px;
  height: 7px;
  border-radius: 0 0 70% 70%;
  background: currentColor;
  box-shadow: -5px -4px 0 -1px currentColor, 5px -4px 0 -1px currentColor;
}

.admin-rail-icon-rocket span {
  width: 4px;
  height: 4px;
  margin-top: -6px;
  border: 1.5px solid currentColor;
  border-radius: 50%;
}

.admin-rail-icon-campaigns::before {
  left: 2px;
  top: 8px;
  width: 13px;
  height: 8px;
  border-radius: 3px 8px 8px 3px;
  transform: skewX(-14deg);
}

.admin-rail-icon-campaigns::after {
  left: 14px;
  top: 10px;
  width: 7px;
  height: 4px;
  border-radius: 0 999px 999px 0;
}

.admin-rail-icon-campaigns span::before {
  left: 6px;
  top: 15px;
  width: 3px;
  height: 7px;
  border-radius: 999px;
  box-shadow: 7px -5px 0 0 rgba(255, 255, 255, 0.18);
}

.admin-rail-icon-affiliate::before,
.admin-rail-icon-affiliate::after,
.admin-rail-icon-affiliate span::before,
.admin-rail-icon-affiliate span::after {
  content: '';
  position: absolute;
  border-radius: 50%;
  border: 2px solid currentColor;
}

.admin-rail-icon-affiliate::before {
  top: 0;
  left: 8px;
  width: 7px;
  height: 7px;
}

.admin-rail-icon-affiliate::after {
  bottom: 0;
  left: 0;
  width: 10px;
  height: 10px;
}

.admin-rail-icon-affiliate span::before {
  right: 0;
  bottom: 0;
  width: 10px;
  height: 10px;
}

.admin-rail-icon-affiliate span::after {
  left: 8px;
  top: 7px;
  width: 6px;
  height: 6px;
  border-width: 4px;
}

.admin-rail-icon-affiliate {
