/* Profit and Loss workspace */
.is-profit-loss {
  --pl-green: #d7dfcb;
  --pl-yellow: #ffd166;
  --pl-blue: #6ee7ff;
  --pl-profit: #9dff8f;
  --pl-cost: #ffc56f;
  --pl-red: #ff4d57;
  --pl-border: rgba(238, 235, 228, 0.1);
  --pl-muted: #918f8a;
  --pl-panel: rgba(18, 18, 17, 0.94);
  overflow-x: hidden;
  background: #090908;
  color: #eeeeea;
}

.is-profit-loss .admin-app::after {
  display: none;
}

.is-profit-loss .admin-shell-main {
  min-width: 0;
}

.profit-loss-topbar {
  position: sticky;
  top: 0;
  z-index: 30;
  min-height: 82px;
  padding-block: 14px;
  background: rgba(10, 10, 9, 0.9);
  backdrop-filter: blur(18px);
}

.profit-loss-controls,
.pl-ledger-tools {
  display: flex;
  align-items: center;
  gap: 8px;
}

.pl-compact-control {
  display: grid;
  gap: 3px;
  min-width: 116px;
}

.pl-compact-control span {
  display: inline-flex;
  align-items: center;
  color: var(--pl-muted);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pl-compact-control select,
.pl-form-grid input,
.pl-form-grid select,
.pl-form-grid textarea {
  width: 100%;
  border: 1px solid var(--pl-border);
  border-radius: 8px;
  outline: none;
  background: #111110;
  color: #eeeeea;
  font: inherit;
}

.pl-compact-control select {
  height: 36px;
  padding: 0 30px 0 10px;
  font-size: 0.76rem;
}

.pl-icon-button,
.pl-row-edit {
  display: grid;
  place-items: center;
  border: 1px solid var(--pl-border);
  border-radius: 8px;
  background: #111110;
  color: #bebbb4;
  cursor: pointer;
}

.pl-icon-button {
  width: 38px;
  height: 38px;
  margin-top: 14px;
}

.pl-settings-icon {
  flex: 0 0 auto;
  width: 31px;
  height: 31px;
  margin-top: 0;
}

.pl-icon-button svg,
.pl-row-edit svg,
.pl-search svg {
  width: 17px;
  height: 17px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.8;
}

.pl-icon-button:hover,
.pl-row-edit:hover {
  border-color: rgba(215, 223, 203, 0.36);
  color: var(--pl-green);
}

.pl-icon-button:disabled,
.pl-row-edit:disabled {
  cursor: not-allowed;
  opacity: 0.34;
}

.profit-loss-layout {
  display: grid;
  gap: 12px;
  padding: 12px 18px 34px;
}

.pl-kpi-strip {
  display: grid;
  grid-template-columns: repeat(8, minmax(120px, 1fr));
  overflow: hidden;
  border: 1px solid var(--pl-border);
  border-radius: 10px;
  background: var(--pl-panel);
}

.pl-kpi-strip article {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 13px 12px;
  border-right: 1px solid var(--pl-border);
}

.pl-kpi-strip article:last-child {
  border-right: 0;
}

.pl-kpi-strip article.is-net {
  background: rgba(215, 223, 203, 0.04);
}

.pl-kpi-strip span,
.pl-inline-title {
  color: #a09d96;
  font-size: 0.67rem;
  font-weight: 650;
}

.pl-kpi-strip strong {
  overflow: hidden;
  color: #f2f1ed;
  font: 700 clamp(0.86rem, 1.15vw, 1.15rem) "Space Grotesk", sans-serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pl-kpi-strip small {
  overflow: hidden;
  color: #77746e;
  font-size: 0.57rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.is-profit-loss i[data-pl-help],
.is-profit-loss .pl-help-icon {
  display: inline-grid;
  place-items: center;
  width: 14px;
  height: 14px;
  margin-left: 3px;
  border: 1px solid #66635c;
  border-radius: 50%;
  color: #a19e97;
  font: 700 0.56rem/1 "Space Grotesk", sans-serif;
  cursor: pointer;
  user-select: none;
  vertical-align: 0.08em;
}

.is-profit-loss i[data-pl-help]:hover,
.is-profit-loss i[data-pl-help]:focus-visible,
.is-profit-loss i[data-pl-help][aria-expanded="true"] {
  border-color: #66635c;
  color: #a19e97;
  outline: none;
}

.pl-help-popover {
  position: fixed;
  z-index: 140;
  padding: 9px 10px;
  border: 1px solid rgba(110, 231, 255, 0.28);
  border-radius: 8px;
  background: #171918;
  color: #eeeae2;
  box-shadow: 0 16px 50px rgba(0, 0, 0, 0.48);
  font: 600 0.66rem/1.45 "Plus Jakarta Sans", sans-serif;
}

.pl-help-popover[hidden] {
  display: none;
}

.is-negative {
  color: var(--pl-red) !important;
}

.pl-legacy-star {
  margin-left: 3px;
  color: var(--pl-red);
  font: 800 0.78em "Space Grotesk", sans-serif;
  cursor: help;
  vertical-align: 0.08em;
}

.pl-workspace-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  align-items: start;
  gap: 12px;
}

.pl-side-stack {
  display: grid;
  gap: 12px;
}

.pl-main-stack {
  display: grid;
  align-content: start;
  gap: 12px;
  min-width: 0;
}

.pl-surface {
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--pl-border);
  border-radius: 10px;
  background: var(--pl-panel);
}

.pl-surface-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 46px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--pl-border);
}

.pl-surface-actions {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
  gap: 12px;
}

.pl-inline-title {
  display: flex;
  align-items: center;
}

.pl-inline-title strong {
  color: #eeeeea;
  font-size: 0.76rem;
}

.pl-text-button {
  padding: 5px 0;
  border: 0;
  background: transparent;
  color: var(--pl-green);
  font: 700 0.67rem "Plus Jakarta Sans", sans-serif;
  cursor: pointer;
}

.pl-text-button.pl-edit-text {
  color: var(--pl-yellow);
}

.pl-add-text {
  color: #4ade80 !important;
}

.pl-edit-text {
  color: var(--pl-yellow) !important;
}

.pl-search {
  display: grid;
  grid-template-columns: 22px minmax(100px, 180px);
  align-items: center;
  height: 31px;
  padding: 0 8px;
  border: 1px solid var(--pl-border);
  border-radius: 7px;
  background: #111110;
  color: #7e7b74;
}

.pl-search input {
  min-width: 0;
  border: 0;
  outline: none;
  background: transparent;
  color: #eeeeea;
  font: 500 0.68rem "Plus Jakarta Sans", sans-serif;
}

.pl-data-badge {
  padding: 5px 7px;
  border: 1px solid rgba(215, 223, 203, 0.22);
  border-radius: 6px;
  color: #c4c2ba;
  font-size: 0.58rem;
  white-space: nowrap;
}

.pl-data-badge.is-warning {
  border-color: rgba(255, 184, 77, 0.3);
  color: #ffc56f;
}

.pl-product-card-stack {
  display: grid;
  gap: 10px;
  padding: 10px;
}

.pl-product-card {
  min-width: 0;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.075);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.02);
}

.pl-product-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
