.pl-sku-chip {
  display: inline-grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  max-width: 290px;
  min-height: 30px;
  gap: 6px;
  padding: 5px 7px;
  border: 1px solid rgba(215, 223, 203, 0.18);
  border-radius: 7px;
  background: rgba(215, 223, 203, 0.055);
  color: #eeeeea;
  cursor: pointer;
}

.pl-sku-chip.is-offscreen {
  border-color: rgba(110, 231, 255, 0.18);
}

.pl-sku-chip:disabled {
  cursor: default;
  opacity: 0.78;
}

.pl-product-card-preview {
  display: grid;
  gap: 8px;
  padding: 10px;
  background: rgba(0, 0, 0, 0.11);
}

.pl-product-preview-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.pl-product-preview-head span {
  display: inline-flex;
  align-items: center;
  color: #85827b;
  font-size: 0.58rem;
  font-weight: 800;
  text-transform: uppercase;
}

.pl-editor-section-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 24px;
}

.pl-editor-section-title span {
  display: inline-flex;
  align-items: center;
  color: #85827b;
  font-size: 0.58rem;
  font-weight: 800;
  text-transform: uppercase;
}

.pl-product-preview-head strong {
  color: #dcdad3;
  font-size: 0.62rem;
}

.pl-preview-row-editor,
.pl-preview-metric-editor {
  display: grid;
  gap: 6px;
}

.pl-preview-metric-editor {
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.055);
}

.pl-preview-row,
.pl-preview-metric-row {
  display: grid;
  grid-template-columns: auto minmax(180px, 1fr) auto;
  align-items: center;
  gap: 7px;
  min-height: 39px;
  padding: 6px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.018);
}

.pl-preview-row.is-hidden,
.pl-preview-metric-row.is-hidden {
  opacity: 0.58;
}

.pl-preview-row.is-row-dragging,
.pl-preview-metric-row.is-row-dragging {
  border-color: rgba(110, 231, 255, 0.44);
}

.pl-preview-row-drag,
.pl-preview-row-actions button {
  min-height: 27px;
  padding: 0 8px;
  border: 1px solid var(--pl-border);
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.03);
  color: #d8d5ce;
  font-size: 0.57rem;
  font-weight: 750;
  cursor: pointer;
}

.pl-preview-row-drag {
  cursor: grab;
}

.pl-preview-row-drag:active {
  cursor: grabbing;
}

.pl-preview-row input[data-pl-variant-row-label],
.pl-preview-metric-row input[data-pl-metric-panel-label] {
  width: 100%;
  min-height: 29px;
  border: 1px solid var(--pl-border);
  border-radius: 7px;
  background: #0e0e0d;
  color: #eeeeea;
  font: 650 0.64rem "Plus Jakarta Sans", sans-serif;
  outline: none;
  padding: 5px 8px;
}

.pl-preview-row-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.pl-preview-row-actions label {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: #aaa7a0;
  font-size: 0.58rem;
  font-weight: 700;
  white-space: nowrap;
}

.pl-preview-row-actions input[type="checkbox"] {
  width: 14px;
  height: 14px;
  accent-color: #d7dfcb;
}

.pl-preview-row-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.44;
}

.pl-product-preview-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
}

.pl-modal-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  padding: 10px 14px 14px;
}

.pl-modal-actions > span {
  flex: 1;
}

.pl-primary-button,
.pl-secondary-button,
.pl-danger-button,
.pl-trash-button {
  min-height: 36px;
  padding: 0 13px;
  border-radius: 7px;
  font: 700 0.65rem "Plus Jakarta Sans", sans-serif;
  cursor: pointer;
}

.pl-primary-button {
  border: 1px solid rgba(215, 223, 203, 0.36);
  background: #d7dfcb;
  color: #10100f;
}

.pl-secondary-button {
  border: 1px solid var(--pl-border);
  background: #111110;
  color: #c8c5be;
}

.pl-danger-button {
  border: 1px solid rgba(255, 93, 93, 0.25);
  background: rgba(255, 93, 93, 0.08);
  color: #ff9292;
}

.pl-trash-button {
  display: grid;
  place-items: center;
  width: 36px;
  padding: 0;
  border: 1px solid rgba(255, 93, 93, 0.28);
  background: rgba(255, 93, 93, 0.08);
  color: #ff7070;
}

.pl-trash-button:hover {
  border-color: rgba(255, 93, 93, 0.48);
  background: rgba(255, 93, 93, 0.14);
  color: #ff9a9a;
}

.pl-trash-button svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.9;
}

.pl-form-error {
  margin: 0 14px;
  color: #ff8d8d;
  font-size: 0.62rem;
}

.pl-toast {
  position: fixed;
  right: 22px;
  bottom: 22px;
  z-index: 120;
  max-width: 360px;
  padding: 10px 13px;
  border: 1px solid rgba(215, 223, 203, 0.24);
  border-radius: 8px;
  background: #171815;
  color: #eeeeea;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.45);
  font-size: 0.68rem;
}

.pl-toast.is-error {
  border-color: rgba(255, 93, 93, 0.3);
  background: #1b1010;
  color: #ffb5b5;
}

@media (max-width: 1320px) {
  .pl-kpi-strip {
    grid-template-columns: repeat(4, minmax(140px, 1fr));
  }

  .pl-kpi-strip article:nth-child(4) {
    border-right: 0;
  }

  .pl-kpi-strip article:nth-child(-n+4) {
    border-bottom: 1px solid var(--pl-border);
  }

  .pl-ledger-head,
  .pl-ledger-group > summary,
  .pl-ledger-row {
    grid-template-columns: minmax(210px, 1.5fr) repeat(7, minmax(70px, 0.7fr)) 32px;
  }

  .pl-syrup-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pl-product-metric-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 1080px) {
  .pl-workspace-grid {
    grid-template-columns: 1fr;
  }

  .pl-side-stack {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .pl-product-ledger {
    overflow-x: auto;
  }

  .pl-ledger-head,
  .pl-ledger-groups {
    min-width: 980px;
  }
}

@media (max-width: 760px) {
  .profit-loss-topbar {
    align-items: flex-start;
  }

  .profit-loss-controls {
    width: 100%;
  }

  .pl-compact-control {
    flex: 1;
    min-width: 0;
  }

  .profit-loss-layout {
    padding-inline: 8px;
  }

  .pl-kpi-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pl-kpi-strip article {
    border-bottom: 1px solid var(--pl-border);
  }

  .pl-kpi-strip article:nth-child(even) {
    border-right: 0;
  }

  .pl-side-stack {
    grid-template-columns: 1fr;
  }

  .pl-ledger-tools {
    align-items: stretch;
    flex-direction: column;
  }

  .pl-search {
    grid-template-columns: 22px minmax(100px, 1fr);
  }

  .pl-form-grid {
    grid-template-columns: 1fr;
  }

  .pl-form-grid label.is-wide {
    grid-column: auto;
  }

  .pl-product-settings-card {
    width: min(100%, calc(100vw - 14px));
  }

  .pl-config-row-head,
  .pl-config-row-actions,
  .pl-sku-picker-actions,
  .pl-product-preview-head {
    align-items: stretch;
    flex-direction: column;
  }

  .pl-config-row-actions {
    width: 100%;
  }

  .pl-config-row-actions button {
    width: 100%;
  }

  .pl-sku-filter-grid,
  .pl-sku-picker-grid {
    grid-template-columns: 1fr;
  }

  .pl-sku-picker-actions button {
    width: 100%;
  }

  .pl-sku-chip {
    max-width: 100%;
  }

  .pl-preview-row,
  .pl-preview-metric-row {
    grid-template-columns: 1fr;
  }

  .pl-preview-row-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .pl-product-card-head,
  .pl-product-card-summary {
    align-items: stretch;
    flex-direction: column;
  }

  .pl-product-card-summary {
    width: 100%;
  }

  .pl-product-card-summary span {
    min-width: 0;
    text-align: left;
  }

  .pl-syrup-grid,
  .pl-syrup-metrics {
    grid-template-columns: 1fr;
  }

  .pl-syrup-metrics span,
  .pl-syrup-metrics span:nth-child(3n),
  .pl-syrup-metrics span:nth-last-child(-n+3) {
    border-right: 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.045);
  }

  .pl-syrup-metrics span:last-child {
    border-bottom: 0;
  }
}

.admin-app.admin-app-suite .admin-menu-item-danger {
  color: #ff8e8e;
}

.is-profit-loss :is(.pl-text-button, .pl-secondary-button).pl-add-text {
  color: #4ade80 !important;
}

.is-profit-loss :is(.pl-text-button, .pl-secondary-button).pl-add-text:hover,
.is-profit-loss :is(.pl-text-button, .pl-secondary-button).pl-add-text:focus-visible {
  color: #86efac !important;
}

.is-profit-loss :is(.pl-text-button, .pl-secondary-button).pl-edit-text {
  color: #ffd166 !important;
}

.admin-app.admin-app-suite .admin-menu-item-danger:hover {
  border-color: rgba(255, 82, 82, 0.28);
  background: rgba(255, 82, 82, 0.12);
  color: #ffd0d0;
}

.admin-app.admin-app-suite .admin-search-shell {
  position: relative;
  display: grid;
  grid-template-columns: 34px minmax(280px, 1fr);
  align-items: center;
  gap: 8px;
  min-width: min(100%, 420px);
  padding: 8px 12px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-bottom: 2px solid rgba(157, 255, 0, 0.34);
  border-radius: 18px;
  background: rgba(5, 8, 12, 0.9);
  box-shadow: none;
}

.admin-app.admin-app-suite .admin-search-icon {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  font-size: 1.35rem;
  line-height: 1;
  color: rgba(255, 255, 255, 0.82);
}

.admin-app.admin-app-suite .admin-search-form {
  width: 100%;
}

.admin-app.admin-app-suite .admin-search-input {
  width: 100%;
  min-width: 0;
  height: 42px;
  padding: 0;
}

.admin-app.admin-app-suite .admin-search-results {
  position: absolute;
  top: calc(100% + 12px);
  left: 0;
  right: 0;
  z-index: 80;
  display: grid;
  gap: 8px;
  padding: 12px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-bottom: 2px solid rgba(157, 255, 0, 0.34);
  border-radius: 18px;
  background: rgba(5, 8, 12, 0.94);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.admin-app.admin-app-suite .admin-search-results[hidden] {
  display: none !important;
}

.admin-app.admin-app-suite .admin-search-result {
  display: grid;
  gap: 4px;
  padding: 12px 14px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.02);
  transition: border-color 0.18s ease, background 0.18s ease;
}

.admin-app.admin-app-suite .admin-search-result:hover {
  border-color: rgba(157, 255, 0, 0.34);
  background: rgba(255, 255, 255, 0.04);
}

.admin-app.admin-app-suite .admin-search-result strong {
  font-size: 0.96rem;
  color: #f3f6f8;
}

.admin-app.admin-app-suite .admin-search-result span,
.admin-app.admin-app-suite .admin-search-result small,
.admin-app.admin-app-suite .admin-search-empty {
  color: rgba(255, 255, 255, 0.62);
}

.admin-app.admin-app-suite .admin-search-empty {
  padding: 8px 4px 2px;
  font-size: 0.94rem;
}

.admin-home-search-wrap {
  position: relative;
  z-index: 10;
  display: flex;
  justify-content: center;
  min-width: 0;
  min-height: 76px;
  margin: -2px 0 14px;
}

.admin-app.admin-app-suite .admin-search-shell.admin-search-shell-home {
  position: relative;
  display: block;
  grid-template-columns: none;
  flex: 0 0 64px;
  width: 64px;
  min-width: 64px;
  max-width: min(430px, 100%);
  height: 64px;
  padding: 0;
  overflow: visible;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-bottom: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 999px;
  background: #111114;
  box-shadow:
    0 18px 60px rgba(0, 0, 0, 0.7),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
  transition:
    width 0.52s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.42s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.42s cubic-bezier(0.22, 1, 0.36, 1);
}

.admin-app.admin-app-suite .admin-search-shell.admin-search-shell-home.is-search-open {
  flex-basis: min(430px, 100%);
  width: min(430px, 100%);
  min-width: min(430px, 100%);
}

.admin-search-surface,
.admin-search-surface-glow,
.admin-search-topline,
.admin-search-sweep,
.admin-search-focus-ring {
  position: absolute;
  pointer-events: none;
}

.admin-search-surface {
  inset: 0;
  overflow: hidden;
  border-radius: inherit;
  opacity: 0.65;
  transition: opacity 0.4s ease;
}

.admin-search-shell-home.is-search-open .admin-search-surface {
  opacity: 1;
}

.admin-search-surface-glow {
  inset: 0;
  background: linear-gradient(to bottom, rgba(255, 255, 255, 0.085), transparent);
}

.admin-search-topline {
  top: 0;
  left: 12px;
  right: 12px;
  height: 1px;
  background: rgba(255, 255, 255, 0.15);
}

.admin-search-sweep {
  top: 0;
  left: -120px;
  width: 112px;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.08), transparent);
  opacity: 0;
  transition:
    left 0.7s cubic-bezier(0.16, 1, 0.3, 1),
    opacity 0.18s ease;
}

.admin-search-shell-home.is-search-open .admin-search-sweep {
  left: calc(100% - 40px);
  opacity: 1;
}

.admin-search-icon-button,
.admin-search-close-button {
  position: absolute;
  z-index: 20;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: rgba(255, 255, 255, 0.82);
  cursor: pointer;
}

.admin-search-icon-button {
  top: 0;
  left: 0;
  width: 64px;
  height: 64px;
}

.admin-search-icon-button svg,
.admin-search-close-button svg {
  width: 23px;
  height: 23px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.admin-search-icon-button svg {
  transform: rotate(-8deg) scale(1);
  opacity: 1;
  transition:
    transform 0.42s cubic-bezier(0.22, 1, 0.36, 1),
    opacity 0.42s cubic-bezier(0.22, 1, 0.36, 1);
}

.admin-search-shell-home.is-search-open .admin-search-icon-button svg {
  transform: rotate(0deg) scale(0.86);
  opacity: 0.72;
}

.admin-search-icon-button:active,
.admin-search-close-button:active {
  transform: scale(0.94);
}

.admin-search-close-button {
  top: 8px;
  right: 8px;
  width: 48px;
  height: 48px;
  color: rgba(255, 255, 255, 0.5);
  opacity: 0;
  pointer-events: none;
  transform: translateX(10px);
  transition:
    opacity 0.34s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.34s cubic-bezier(0.22, 1, 0.36, 1),
    background 0.18s ease,
    color 0.18s ease;
}

.admin-search-close-button:hover {
  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.85);
}

.admin-search-shell-home.is-search-open .admin-search-close-button {
  opacity: 1;
  pointer-events: auto;
  transform: translateX(0);
}

.admin-app.admin-app-suite .admin-search-shell-home .admin-search-form {
  position: absolute;
  inset: 0 56px 0 64px;
  z-index: 12;
  display: flex;
  align-items: center;
  width: auto;
  min-width: 0;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
  clip-path: inset(0 100% 0 0);
  transform: translateY(6px);
  transition:
    opacity 0.46s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.46s cubic-bezier(0.22, 1, 0.36, 1),
    clip-path 0.46s cubic-bezier(0.22, 1, 0.36, 1);
}

.admin-app.admin-app-suite .admin-search-shell-home.is-search-open .admin-search-form {
  opacity: 1;
  pointer-events: auto;
  clip-path: inset(0 0 0 0);
  transform: translateY(0);
}

.admin-app.admin-app-suite .admin-search-shell-home .admin-search-input {
  width: 100%;
  min-width: 0;
  height: 64px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #ffffff;
  font-size: 17px;
  letter-spacing: 0;
  outline: none;
}

.admin-app.admin-app-suite .admin-search-shell-home .admin-search-input::placeholder {
  color: rgba(255, 255, 255, 0.35);
}

.admin-search-focus-ring {
  inset: 0;
  border-radius: inherit;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.08),
    0 0 0 0 rgba(255, 255, 255, 0);
  transition: box-shadow 0.42s cubic-bezier(0.22, 1, 0.36, 1);
}

.admin-search-shell-home.is-search-open .admin-search-focus-ring {
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.13),
    0 0 0 6px rgba(255, 255, 255, 0.025);
}

.admin-app.admin-app-suite .admin-search-shell-home .admin-search-results {
  top: calc(100% + 12px);
  left: 0;
  right: 0;
  z-index: 90;
  width: 100%;
  gap: 8px;
  padding: 10px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 18px;
  background: rgba(17, 17, 20, 0.96);
  box-shadow:
    0 18px 60px rgba(0, 0, 0, 0.55),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.admin-app.admin-app-suite .admin-search-shell-home .admin-search-result {
  border-radius: 14px;
}

@media (max-width: 820px) {
  .admin-home-search-wrap {
    justify-content: flex-start;
    min-height: 72px;
  }

  .admin-app.admin-app-suite .admin-search-shell.admin-search-shell-home {
    max-width: 100%;
  }

  .admin-app.admin-app-suite .admin-search-shell.admin-search-shell-home.is-search-open {
    flex-basis: 100%;
    width: 100%;
    min-width: 100%;
  }
}

.admin-primary-btn,
.admin-ghost-btn,
.admin-danger-btn,
.admin-soft-btn,
.admin-toggle-pill,
.admin-view-indicator,
.admin-menu-trigger,
.admin-menu-item {
  cursor: pointer;
  transition:
    transform 0.16s ease,
    box-shadow 0.16s ease,
    border-color 0.16s ease,
    background 0.16s ease,
    color 0.16s ease,
    filter 0.16s ease;
  will-change: transform;
}

.admin-primary-btn:hover,
.admin-ghost-btn:hover,
.admin-danger-btn:hover,
.admin-soft-btn:hover,
.admin-toggle-pill:hover,
.admin-view-indicator:hover,
.admin-menu-trigger:hover,
.admin-menu-item:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 22px rgba(0, 0, 0, 0.18);
  filter: brightness(1.04);
}

.admin-primary-btn:active,
.admin-ghost-btn:active,
.admin-danger-btn:active,
.admin-soft-btn:active,
.admin-toggle-pill:active,
.admin-view-indicator:active,
.admin-menu-trigger:active,
.admin-menu-item:active {
  transform: translateY(0);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
  filter: brightness(0.98);
}

.admin-primary-btn:disabled,
.admin-ghost-btn:disabled,
.admin-danger-btn:disabled,
.admin-soft-btn:disabled,
.admin-toggle-pill:disabled {
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
  filter: none;
}

.admin-api-health-grid {
  grid-template-columns: minmax(0, 1fr);
}

.admin-health-table td strong,
.admin-health-table td small,
.admin-health-table td code,
.admin-health-table td span {
  display: block;
}

.admin-health-table td small,
.admin-api-log-item small {
  color: var(--admin-text-muted);
  margin-top: 4px;
}

.admin-health-table td code,
.admin-api-log-item code {
  max-width: 100%;
  overflow-wrap: anywhere;
  color: var(--admin-text-muted);
