/* Settings theme picker */
.admin-theme-options {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.admin-theme-option {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  min-height: 76px;
  padding: 12px;
  border: 1px solid var(--admin-border);
  border-radius: 16px;
  background: var(--admin-surface-soft);
  color: var(--admin-text);
  text-align: left;
  cursor: pointer;
  transition: border-color 0.16s ease, background 0.16s ease, transform 0.16s ease;
}

.admin-theme-option:hover,
.admin-theme-option.is-active {
  border-color: var(--admin-green-line, var(--admin-accent-primary));
  background: var(--admin-surface-glass-strong, var(--admin-surface-soft));
}

.admin-theme-option:hover {
  transform: translateY(-1px);
}

.admin-theme-option strong,
.admin-theme-option small {
  display: block;
  min-width: 0;
}

.admin-theme-option strong {
  color: var(--admin-text);
  font-size: 0.88rem;
  line-height: 1.25;
}

.admin-theme-option small {
  margin-top: 4px;
  color: var(--admin-muted);
  font-size: 0.76rem;
  line-height: 1.35;
}

.admin-theme-swatch {
  width: 42px;
  height: 42px;
  border: 1px solid var(--admin-border);
  border-radius: 12px;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.08);
}

.admin-theme-swatch-current {
  background:
    linear-gradient(135deg, #000 0 58%, #afff00 58% 72%, #00ff88 72% 100%);
}

.admin-theme-swatch-dark {
  background:
    linear-gradient(135deg, #000000 0 70%, #202020 70% 86%, #f5f5f5 86% 100%);
}

.admin-theme-swatch-light {
  background:
    linear-gradient(135deg, #ffffff 0 70%, #f0f0f0 70% 86%, #111111 86% 100%);
}

.admin-theme-swatch-minimal-white {
  background:
    linear-gradient(135deg, #ffffff 0 68%, #e5e7eb 68% 100%);
}

.admin-theme-swatch-classic-white {
  background:
    radial-gradient(circle at 26% 28%, rgba(175, 255, 0, 0.75), transparent 32%),
    linear-gradient(135deg, #ffffff 0%, #eef5ec 52%, #dfeee7 100%);
}

.admin-theme-swatch-minimal-black {
  background:
    linear-gradient(135deg, #000000 0 68%, #1a1a1a 68% 84%, #ffffff 84% 100%);
}

.admin-theme-swatch-prism {
  background:
    radial-gradient(circle at 18% 20%, #ff4ecd, transparent 42%),
    radial-gradient(circle at 86% 18%, #37d7ff, transparent 38%),
    linear-gradient(135deg, #0b0714 0%, #7c5cff 56%, #ff8f70 100%);
}

/* Dashboard theme variants. */
:root[data-admin-theme='dark'] {
  --admin-bg: #0b0f14;
  --admin-surface: rgba(18, 24, 33, 0.88);
  --admin-surface-strong: rgba(23, 31, 43, 0.94);
  --admin-surface-soft: rgba(26, 36, 49, 0.82);
  --admin-border: rgba(255, 255, 255, 0.08);
  --admin-text: #eef4f7;
  --admin-muted: rgba(219, 230, 238, 0.68);
  --admin-shadow: 0 18px 40px rgba(0, 0, 0, 0.28);
  --admin-accent-primary: #9dff00;
  --admin-accent-secondary: #ffd400;
  --admin-accent-tertiary: #ff5252;
  --admin-accent-quaternary: #22d3ee;
  --admin-accent-gradient: linear-gradient(135deg, #9dff00 0%, #00ff88 52%, #22d3ee 100%);
  --admin-shell-edge: rgba(157, 255, 0, 0.14);
  --admin-panel-outline-hover: rgba(157, 255, 0, 0.36);
  --admin-panel-shadow: 0 22px 54px rgba(0, 0, 0, 0.28);
  --admin-panel-shadow-hover: 0 28px 64px rgba(0, 0, 0, 0.34);
  --admin-panel-glass-bg: rgba(18, 24, 33, 0.72);
  --admin-copy-soft: rgba(219, 230, 238, 0.74);
  --admin-surface-glass: rgba(18, 24, 33, 0.58);
  --admin-surface-glass-strong: rgba(23, 31, 43, 0.82);
  --admin-surface-panel: rgba(18, 24, 33, 0.62);
  --admin-surface-panel-strong: rgba(23, 31, 43, 0.82);
  --admin-rail-border: rgba(157, 255, 0, 0.14);
  --admin-green-soft: rgba(157, 255, 0, 0.14);
  --admin-green-line: rgba(157, 255, 0, 0.5);
  color-scheme: dark;
}

:root[data-admin-theme='minimal-white'] {
  --admin-bg: #f7f8f5;
  --admin-surface: #ffffff;
  --admin-surface-strong: #ffffff;
  --admin-surface-soft: #eef1ec;
  --admin-border: rgba(15, 23, 42, 0.13);
  --admin-text: #111827;
  --admin-muted: #596171;
  --admin-shadow: none;
  --admin-accent-primary: #217a3c;
