}

.admin-context-period.is-active {
  border-color: rgba(157, 255, 0, 0.2);
  background: rgba(157, 255, 0, 0.08);
  color: #fff;
}

.admin-context-editor {
  display: grid;
  align-content: center;
  gap: 24px;
