/* Sliding metric selectors for Executive Sales charts. */
.admin-app.admin-app-suite .admin-sliding-chart-toggle {
  --sliding-toggle-pad: 4px;
  position: relative;
  z-index: 10;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  flex-wrap: nowrap;
  width: auto;
  max-width: 100%;
  gap: 0;
  margin: -2px 0 12px;
  padding: var(--sliding-toggle-pad);
  overflow-x: auto;
  overflow-y: hidden;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 999px;
  background: #141414;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.035),
    inset 0 -1px 0 rgba(0, 0, 0, 0.36);
  scrollbar-width: none;
}

.admin-app.admin-app-suite .admin-sliding-chart-toggle::-webkit-scrollbar {
  display: none;
}

.admin-app.admin-app-suite .admin-sliding-toggle-indicator {
  position: absolute;
  z-index: 2;
  left: 0;
  top: var(--sliding-toggle-pad);
  bottom: var(--sliding-toggle-pad);
  width: var(--sliding-toggle-width, 0);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
  opacity: 0;
  transform: translate3d(var(--sliding-toggle-x, 0), 0, 0);
  transition:
    width 420ms cubic-bezier(0.2, 0.9, 0.25, 1.18),
    transform 420ms cubic-bezier(0.2, 0.9, 0.25, 1.18),
    opacity 160ms ease;
  will-change: width, transform;
  pointer-events: none;
}

.admin-app.admin-app-suite .admin-sliding-chart-toggle.has-active-toggle .admin-sliding-toggle-indicator {
  opacity: 1;
}

.admin-app.admin-app-suite .admin-sliding-toggle-indicator.is-positioning {
  transition: none;
}

.admin-app.admin-app-suite .admin-sliding-chart-toggle > .admin-toggle-pill,
.admin-app.admin-app-suite .admin-sliding-chart-toggle > .admin-toggle-pill:hover,
