  cursor: help;
}

.admin-view-daily {
  --daily-black: #050505;
  --daily-panel: #080808;
  --daily-head: #101010;
  --daily-total: #0d0d0d;
  --daily-line: rgba(255, 255, 255, 0.11);
  --daily-soft-line: rgba(255, 255, 255, 0.07);
  --daily-text: #f4f4f2;
  --daily-muted: rgba(255, 255, 255, 0.58);
  --daily-qty: #ffe45e;
}

.admin-app[data-active-view='daily'] {
  background: var(--daily-black);
}

.admin-app[data-active-view='daily']::after,
.admin-app[data-active-view='daily'] .admin-backdrop,
.admin-app[data-active-view='daily'] .admin-backdrop::before,
.admin-app[data-active-view='daily'] .admin-backdrop::after {
  content: none;
  display: none;
}

.admin-view-daily .admin-chip-accent {
  width: fit-content;
  background: transparent;
  color: #9dff00;
}

.daily-sheet-shell {
  display: grid;
  gap: 14px;
  min-width: 0;
  padding: 16px;
  border: 1px solid var(--daily-line);
  border-radius: 8px;
  background: var(--daily-black);
  box-shadow: none;
}

.daily-sheet-toolbar {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
  min-width: 0;
}

.daily-sheet-title {
  display: grid;
  gap: 7px;
  min-width: 0;
}

.daily-sheet-title h2 {
  margin: 0;
  color: var(--daily-text);
  font: 700 clamp(1.35rem, 2.4vw, 2rem) "Space Grotesk", sans-serif;
  letter-spacing: 0;
}

.daily-sheet-title p {
  margin: 0;
  color: var(--daily-muted);
  font-size: 0.86rem;
  font-weight: 750;
}

.daily-sheet-actions {
  display: flex;
  align-items: end;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 10px;
}

.daily-trend-panel {
  display: grid;
  gap: 12px;
  min-width: 0;
  padding: 14px;
  border: 1px solid var(--daily-line);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0)),
    #080808;
}

.daily-trend-head {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 14px;
  min-width: 0;
}

.daily-trend-head h3 {
  margin: 3px 0 4px;
  color: var(--daily-text);
  font: 750 1.05rem/1.2 "Space Grotesk", sans-serif;
  letter-spacing: 0;
}

.daily-trend-head .admin-panel-meta {
  color: var(--daily-muted);
  font-size: 0.78rem;
  font-weight: 760;
}

.daily-trend-toggle {
  flex: 0 0 auto;
}

.daily-trend-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(180px, 240px);
  gap: 12px;
  min-width: 0;
  align-items: stretch;
}

.daily-trend-chart-surface {
  position: relative;
  min-width: 0;
  min-height: 230px;
  border: 1px solid var(--daily-soft-line);
  border-radius: 8px;
  background: var(--daily-panel);
  overflow: hidden;
}

.daily-trend-chart {
  display: block;
  width: 100%;
  height: 230px;
}

.daily-trend-stats {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
  min-width: 0;
}

.daily-trend-stats > div {
  display: grid;
  gap: 4px;
  min-width: 0;
  padding: 11px 12px;
  border: 1px solid var(--daily-soft-line);
  border-radius: 8px;
  background: var(--daily-total);
}

.daily-trend-stats span {
  color: var(--daily-muted);
  font-size: 0.66rem;
  font-weight: 850;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.daily-trend-stats strong {
  overflow: hidden;
  color: var(--daily-text);
  font: 850 1rem/1.15 "Space Grotesk", sans-serif;
  letter-spacing: 0;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.daily-month-picker {
  display: grid;
  gap: 7px;
  min-width: 178px;
}

.daily-month-picker > span,
.daily-platform-form label > span {
  color: var(--daily-muted);
  font-size: 0.7rem;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.daily-month-picker input,
.daily-platform-form input[type="text"] {
  width: 100%;
  min-height: 40px;
  padding: 0 11px;
  border: 1px solid var(--daily-line);
  border-radius: 8px;
  outline: none;
  background: #0d0d0d;
  color: var(--daily-text);
  color-scheme: dark;
}

.daily-month-picker input:focus,
.daily-platform-form input[type="text"]:focus {
  border-color: rgba(255, 228, 94, 0.5);
}

.daily-export-btn,
.daily-add-platform-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 40px;
  border-color: var(--daily-line);
  background: #0d0d0d;
  color: var(--daily-text);
}

.daily-export-btn svg,
.daily-add-platform-btn svg,
.daily-platform-chip svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.daily-export-btn:disabled {
  opacity: 0.48;
}

.daily-sheet-scroll {
  max-height: min(72vh, 760px);
  overflow: auto;
  border: 1px solid var(--daily-line);
  border-radius: 8px;
  background: var(--daily-panel);
}

.daily-sheet-table {
  width: 100%;
  min-width: 980px;
  border-collapse: separate;
  border-spacing: 0;
  color: var(--daily-text);
  font-size: 0.82rem;
  line-height: 1.2;
}

.daily-sheet-table th,
.daily-sheet-table td {
  min-width: 94px;
  height: 42px;
  padding: 8px 10px;
  border-right: 1px solid var(--daily-soft-line);
  border-bottom: 1px solid var(--daily-soft-line);
  background: var(--daily-panel);
  text-align: right;
  vertical-align: middle;
  white-space: nowrap;
}

.daily-sheet-table thead th {
  position: sticky;
  top: 0;
  z-index: 4;
  background: var(--daily-head);
  color: rgba(255, 255, 255, 0.74);
  font-size: 0.68rem;
  font-weight: 850;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.daily-sheet-table thead tr + tr th {
  top: 40px;
  z-index: 5;
}

.daily-sheet-table tfoot th,
.daily-sheet-table tfoot td {
  position: sticky;
  bottom: 0;
  z-index: 3;
  background: #0b0b0b;
  font-weight: 850;
}

.daily-sheet-table tfoot tr:first-child th,
.daily-sheet-table tfoot tr:first-child td {
  bottom: 42px;
}

.daily-day-header,
.daily-day-cell {
  left: 0;
  min-width: 160px !important;
  max-width: 160px;
  text-align: left !important;
}

.daily-sheet-table .daily-day-header {
  position: sticky;
  z-index: 8;
}

.daily-sheet-table .daily-day-cell {
  position: sticky;
  z-index: 2;
  background: #090909;
}

.daily-sheet-table thead .daily-day-header,
.daily-sheet-table tfoot .daily-day-cell {
  z-index: 9;
  background: var(--daily-head);
}

.daily-day-cell strong {
  display: block;
  color: var(--daily-text);
  font-size: 0.84rem;
}

.daily-day-cell small,
.daily-account-header small {
  display: block;
  margin-top: 3px;
  overflow: hidden;
  color: var(--daily-muted);
  font-size: 0.64rem;
  font-weight: 760;
  letter-spacing: 0;
  text-overflow: ellipsis;
  text-transform: none;
}

.daily-account-header {
  min-width: 188px !important;
  text-align: center !important;
}

.daily-account-header span {
  display: block;
  overflow: hidden;
  color: var(--daily-text);
  text-overflow: ellipsis;
}

.daily-subhead {
  text-align: right !important;
}

.daily-qty-head {
  color: var(--daily-qty) !important;
}

.daily-total-header,
.daily-total-subhead,
.daily-total-cell {
  background: var(--daily-total) !important;
}

.daily-number-cell {
  font-variant-numeric: tabular-nums;
  font-weight: 760;
}

.daily-qty-value {
  color: var(--daily-qty);
  font-weight: 900;
}

.daily-rp-value {
  color: rgba(255, 255, 255, 0.88);
  font-weight: 790;
}

.daily-zero {
  color: rgba(255, 255, 255, 0.25);
  font-weight: 650;
}

.daily-sheet-footbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: start;
  gap: 14px;
  min-width: 0;
  padding-top: 2px;
}

.daily-platform-form {
  display: grid;
  grid-template-columns: minmax(420px, 1.4fr) minmax(220px, 0.6fr) auto;
  align-items: end;
  gap: 10px;
  min-width: 0;
}

.daily-platform-form label {
  display: grid;
  gap: 7px;
  min-width: 0;
}

.daily-platform-picker {
  display: grid;
  gap: 8px;
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}

.daily-platform-picker legend {
  margin-bottom: 7px;
  padding: 0;
  color: var(--daily-muted);
  font-size: 0.7rem;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.daily-platform-options {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.daily-platform-options label {
  position: relative;
  display: inline-flex;
  cursor: pointer;
}

.daily-platform-options input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}

.daily-platform-options span {
  display: inline-flex;
  align-items: center;
  min-height: 34px;
  padding: 6px 10px;
  border: 1px solid var(--daily-line);
  border-radius: 999px;
  background: #0d0d0d;
  color: var(--daily-muted);
  font-size: 0.72rem;
  font-weight: 820;
  letter-spacing: 0;
  text-transform: none;
  transition: border-color 160ms ease, background 160ms ease, color 160ms ease, box-shadow 160ms ease;
}

.daily-platform-options input:focus-visible + span {
  outline: 2px solid rgba(255, 228, 94, 0.58);
  outline-offset: 2px;
}

.daily-platform-options input:checked + span {
  border-color: rgba(255, 228, 94, 0.55);
  background: rgba(255, 228, 94, 0.12);
  color: #fff4a8;
  box-shadow: inset 0 0 0 1px rgba(255, 228, 94, 0.08);
}

.daily-platform-feedback {
  grid-column: 1 / -1;
  margin: 0;
  color: var(--daily-qty);
  font-size: 0.76rem;
  font-weight: 760;
}

.daily-platform-feedback.is-error {
  color: #ff8585;
}

.daily-platform-list {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  min-width: 0;
}

.daily-platform-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  max-width: 320px;
  padding: 6px 9px 6px 11px;
  border: 1px solid var(--daily-line);
  border-radius: 999px;
  background: transparent;
  color: var(--daily-text);
  font-size: 0.76rem;
  font-weight: 820;
  cursor: default;
}

.daily-platform-chip-label {
  min-width: 0;
  overflow: hidden;
  flex: 1 1 auto;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.daily-platform-chip-actions {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex: 0 0 auto;
}

.daily-platform-chip-actions button {
  display: inline-grid;
  width: 26px;
  height: 26px;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: rgba(255, 255, 255, 0.62);
  cursor: pointer;
  place-items: center;
}

.daily-platform-chip-actions button:is(:hover, :focus-visible) {
  outline: none;
  background: rgba(255, 255, 255, 0.1);
  color: #ffffff;
}

.daily-platform-chip-actions svg {
  width: 15px;
  height: 15px;
  flex: 0 0 auto;
}

.daily-column-remove-dialog strong,
.daily-column-edit-dialog strong {
  color: var(--admin-text);
}

.daily-column-remove-dialog [data-daily-column-remove-submit]:disabled {
  cursor: wait;
  opacity: 0.58;
}

@media (max-width: 820px) {
  .daily-sheet-shell {
    padding: 12px;
  }

  .daily-sheet-toolbar,
  .daily-sheet-actions,
  .daily-sheet-footbar {
    align-items: stretch;
    grid-template-columns: 1fr;
    flex-direction: column;
  }

  .daily-trend-head,
  .daily-trend-grid {
    grid-template-columns: 1fr;
  }

  .daily-trend-head {
    flex-direction: column;
    align-items: stretch;
  }

  .daily-trend-toggle {
    width: 100%;
  }

  .daily-trend-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .daily-month-picker,
  .daily-export-btn {
    width: 100%;
  }

  .daily-platform-form {
    grid-template-columns: 1fr;
  }

  .daily-day-header,
  .daily-day-cell {
    min-width: 132px !important;
    max-width: 132px;
  }
}

