  height: 9px;
  border-radius: 999px;
  background: #f5f5f5;
  opacity: 0.34;
  animation: admin-loader-worm 1.18s ease-in-out infinite;
}

.admin-loader-worm span:nth-child(2) {
  animation-delay: 0.09s;
}

.admin-loader-worm span:nth-child(3) {
  animation-delay: 0.18s;
}

.admin-loader-worm span:nth-child(4) {
  animation-delay: 0.27s;
}

.admin-loader-worm span:nth-child(5) {
  animation-delay: 0.36s;
}

.admin-loader-bar {
  position: relative;
  height: 10px;
  margin-top: 18px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.admin-loader-progress {
  border-radius: inherit;
  background: linear-gradient(90deg, #ffffff 0%, #afff00 48%, #00e0b8 100%);
  box-shadow: 0 0 20px rgba(175, 255, 0, 0.18);
}

.admin-loader-label {
  display: block;
  min-height: 22px;
  margin-top: 12px;
  font-size: 13px;
  letter-spacing: 0.03em;
}

@keyframes admin-loader-worm {
  0%,
  100% {
    opacity: 0.28;
    transform: translateY(0) scale(0.82);
  }

  38% {
    opacity: 1;
    transform: translateY(-9px) scale(1.14);
  }

  68% {
    opacity: 0.52;
    transform: translateY(2px) scale(0.94);
  }
}

