/* SKU database workspace reconstruction */
.admin-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.admin-app[data-sku-db] {
  --sku-bg: #050606;
  --sku-ink: #f6f7f2;
  --sku-muted: #8d958d;
  --sku-line: rgba(246, 247, 242, 0.11);
  --sku-panel: rgba(246, 247, 242, 0.045);
  --sku-panel-strong: rgba(246, 247, 242, 0.075);
  --sku-lime: #b7ff35;
  --sku-teal: #29d8bd;
  --sku-blue: #75a7ff;
  --sku-coral: #ff746b;
  --sku-amber: #f3c45f;
  --sku-radius: 8px;
  width: min(100%, 1880px);
  padding: 18px 22px 32px;
  background:
    linear-gradient(90deg, rgba(246, 247, 242, 0.025) 1px, transparent 1px) 0 0 / 48px 48px,
    linear-gradient(180deg, rgba(246, 247, 242, 0.018) 1px, transparent 1px) 0 0 / 48px 48px,
    var(--sku-bg);
  color: var(--sku-ink);
}

:root[data-admin-theme='light'] .admin-app[data-sku-db] {
  --sku-bg: #f7f8f5;
  --sku-ink: #111511;
  --sku-muted: #667064;
  --sku-line: rgba(17, 21, 17, 0.13);
  --sku-panel: rgba(17, 21, 17, 0.045);
  --sku-panel-strong: rgba(17, 21, 17, 0.075);
}

.admin-app[data-sku-db] .admin-backdrop {
  display: none;
}

body:has(.admin-app[data-sku-db]) .admin-build-badge {
  display: none;
}

.admin-app[data-sku-db] :where(h1, h2, h3, h4, p, span, small, strong, label, th, td, input, select, button, a) {
  letter-spacing: 0;
}

.admin-app[data-sku-db] .admin-shell {
  gap: 18px;
}

.admin-sku-shell-main {
  display: grid;
  gap: 14px;
}

.admin-app[data-sku-db] .admin-sku-commandbar {
  position: sticky;
  top: 14px;
  z-index: 30;
  display: grid;
  grid-template-columns: auto minmax(280px, 1fr) auto;
  align-items: center;
  gap: 12px;
  min-height: 64px;
  padding: 8px;
  border: 1px solid var(--sku-line);
  border-radius: var(--sku-radius);
  background: color-mix(in srgb, var(--sku-bg) 86%, transparent);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.admin-sku-commandmark,
.admin-sku-command-actions,
.admin-sku-commandmetrics,
.admin-sku-commandmetrics span,
.admin-sku-live-gauge,
.admin-sku-dock-head,
.admin-sku-actions {
  display: flex;
  align-items: center;
}

.admin-sku-commandmark {
  gap: 10px;
  min-width: 118px;
  padding: 0 10px;
}

.admin-sku-commandglyph {
  width: 34px;
  height: 34px;
  border: 1px solid rgba(183, 255, 53, 0.5);
  border-radius: var(--sku-radius);
  background:
    linear-gradient(90deg, transparent 44%, var(--sku-lime) 44%, var(--sku-lime) 56%, transparent 56%),
    linear-gradient(0deg, transparent 44%, var(--sku-teal) 44%, var(--sku-teal) 56%, transparent 56%),
    rgba(183, 255, 53, 0.08);
}

.admin-sku-mode {
  color: var(--sku-ink);
  font-size: 0.82rem;
  font-weight: 800;
}

.admin-sku-commandmetrics {
  justify-content: center;
  gap: 8px;
}

.admin-sku-commandmetrics span {
  justify-content: space-between;
  gap: 10px;
  min-width: 118px;
  min-height: 44px;
  padding: 7px 10px;
  border: 1px solid var(--sku-line);
  border-radius: var(--sku-radius);
  background: var(--sku-panel);
}

.admin-sku-commandmetrics strong {
  font-family: "Space Grotesk", Inter, sans-serif;
  font-size: 1.05rem;
  line-height: 1;
}

.admin-sku-commandmetrics small,
.admin-sku-live-gauge span,
.admin-sku-dock-head strong,
.admin-app[data-sku-db] label span {
  color: var(--sku-muted);
  font-size: 0.68rem;
  font-weight: 800;
  text-transform: uppercase;
}

.admin-sku-command-actions {
  justify-content: end;
  gap: 8px;
}

.admin-app[data-sku-db] .admin-status-pill,
.admin-app[data-sku-db] .admin-ghost-btn,
.admin-app[data-sku-db] .admin-primary-btn,
.admin-app[data-sku-db] .admin-menu-trigger,
.admin-app[data-sku-db] .admin-menu-item {
  min-height: 38px;
  border-radius: var(--sku-radius);
}

.admin-app[data-sku-db] .admin-status-pill {
  max-width: 220px;
  padding: 8px 10px;
  border: 1px solid var(--sku-line);
  background: var(--sku-panel);
}

.admin-sku-layout {
  display: grid;
  gap: 14px;
}

.admin-sku-workbench {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(360px, 0.75fr);
  gap: 14px;
  align-items: start;
}

.admin-sku-workbench-request {
  grid-template-columns: minmax(0, 1fr) minmax(320px, 0.42fr);
}

.admin-sku-composer,
.admin-sku-dock,
.admin-sku-apply-band,
.admin-sku-reference-band,
.admin-sku-table-shell {
  border: 1px solid var(--sku-line);
  border-radius: var(--sku-radius);
  background: var(--sku-panel);
}

.admin-sku-composer {
  display: grid;
  gap: 12px;
  padding: 12px;
}

.admin-sku-preview-surface {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(340px, 0.8fr);
  gap: 12px;
  align-items: end;
  min-height: 162px;
  padding: 16px;
  border: 1px solid rgba(183, 255, 53, 0.22);
  border-radius: var(--sku-radius);
  background:
    linear-gradient(135deg, rgba(183, 255, 53, 0.1), rgba(41, 216, 189, 0.06) 52%, rgba(117, 167, 255, 0.05)),
    rgba(246, 247, 242, 0.035);
}

.admin-sku-preview-surface > .admin-control-label {
  grid-column: 1 / -1;
}

.admin-sku-preview-surface strong {
  min-width: 0;
  overflow-wrap: anywhere;
  font-family: "Space Grotesk", Inter, sans-serif;
  font-size: 3.25rem;
  line-height: 0.95;
  color: var(--sku-ink);
}

.admin-sku-segment-strip {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 6px;
}

.admin-sku-segment-strip span {
  display: grid;
  gap: 4px;
  min-width: 0;
  padding: 9px;
  border: 1px solid var(--sku-line);
  border-radius: var(--sku-radius);
  background: rgba(0, 0, 0, 0.22);
}

:root[data-admin-theme='light'] .admin-sku-segment-strip span {
  background: rgba(255, 255, 255, 0.48);
}

.admin-sku-segment-strip b {
  color: var(--sku-muted);
  font-size: 0.62rem;
}

.admin-sku-segment-strip em {
  color: var(--sku-lime);
  font-family: "Space Grotesk", Inter, sans-serif;
  font-size: 1.12rem;
  font-style: normal;
  font-weight: 800;
  line-height: 1;
}

.admin-sku-segment-strip small {
  min-width: 0;
  overflow: hidden;
  color: var(--sku-muted);
  font-size: 0.68rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-sku-builder-compact {
  grid-template-columns: repeat(6, minmax(110px, 1fr));
  gap: 10px;
}

.admin-sku-builder-compact label,
.admin-sku-mini-form label,
.admin-sku-filter-strip label,
.admin-sku-apply-band label {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.admin-sku-builder-tag {
  grid-column: span 2;
}

.admin-sku-builder-actions {
  align-self: end;
}

.admin-app[data-sku-db] :where(.admin-select, .admin-sku-builder input, .admin-sku-mini-form input, .admin-sku-form-grid input, .admin-sku-cell-input) {
  min-height: 40px;
  padding: 9px 11px;
  border-radius: var(--sku-radius);
  border: 1px solid var(--sku-line);
  background: var(--sku-panel-strong);
  color: var(--sku-ink);
}

.admin-app[data-sku-db] :where(.admin-select:focus, .admin-sku-builder input:focus, .admin-sku-mini-form input:focus, .admin-sku-form-grid input:focus, .admin-sku-cell-input:focus) {
  border-color: rgba(41, 216, 189, 0.58);
  box-shadow: 0 0 0 2px rgba(41, 216, 189, 0.16);
}

.admin-sku-side-stack {
  display: grid;
  gap: 14px;
}

.admin-sku-dock {
  display: grid;
  gap: 12px;
  padding: 12px;
}

.admin-sku-dock-head {
  justify-content: space-between;
  min-height: 34px;
}

.admin-app[data-sku-db] .admin-sku-collapsible {
  padding: 10px 12px;
}

.admin-app[data-sku-db] .admin-sku-collapse {
  display: block;
  min-width: 0;
}

.admin-app[data-sku-db] .admin-sku-collapse-toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 30px;
  color: var(--sku-ink);
  cursor: pointer;
  list-style: none;
  user-select: none;
}

.admin-app[data-sku-db] .admin-sku-collapse-toggle::-webkit-details-marker {
  display: none;
}

.admin-app[data-sku-db] .admin-sku-collapse-toggle strong {
  color: var(--sku-ink);
  font-size: 0.78rem;
  font-weight: 900;
  letter-spacing: 0;
  line-height: 1;
}

.admin-app[data-sku-db] .admin-sku-collapse-arrow {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  color: var(--sku-muted);
  flex: 0 0 auto;
}

.admin-app[data-sku-db] .admin-sku-collapse-arrow::before {
  content: '>';
  font-family: "Space Grotesk", Inter, sans-serif;
  font-size: 0.78rem;
  font-weight: 900;
  line-height: 1;
  transform-origin: center;
  transition: transform 160ms ease, color 160ms ease;
}

.admin-app[data-sku-db] .admin-sku-collapse[open] > .admin-sku-collapse-toggle .admin-sku-collapse-arrow::before {
  color: var(--sku-ink);
  transform: rotate(90deg);
}

.admin-app[data-sku-db] .admin-sku-collapse-toggle:hover .admin-sku-collapse-arrow::before,
.admin-app[data-sku-db] .admin-sku-collapse-toggle:focus-visible .admin-sku-collapse-arrow::before {
  color: var(--sku-ink);
}

.admin-app[data-sku-db] .admin-sku-collapse-toggle:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--sku-ink) 24%, transparent);
  outline-offset: 3px;
}

.admin-app[data-sku-db] .admin-sku-collapse-body {
  display: grid;
  gap: 12px;
  min-width: 0;
  padding-top: 12px;
}

.admin-app[data-sku-db] .admin-sku-apply-band.admin-sku-collapsible {
  display: block;
  padding: 12px;
}

.admin-app[data-sku-db] .admin-sku-apply-band.admin-sku-collapsible[hidden] {
  display: none;
}

.admin-app[data-sku-db] .admin-sku-apply-collapse-body {
  grid-template-columns: minmax(220px, 0.34fr) minmax(0, 1fr);
  align-items: center;
}

.admin-sku-dock-mark {
  display: inline-grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: var(--sku-radius);
  background: rgba(117, 167, 255, 0.14);
  color: var(--sku-blue);
  font-family: "Space Grotesk", Inter, sans-serif;
  font-weight: 800;
}

.admin-sku-request-dock .admin-sku-dock-mark {
  background: rgba(255, 116, 107, 0.14);
  color: var(--sku-coral);
}

.admin-sku-master-create-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.admin-sku-master-create-grid .admin-sku-mini-form {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: end;
}

.admin-sku-master-create-grid .admin-sku-mini-form:has(select) {
  grid-template-columns: minmax(110px, 0.48fr) minmax(0, 1fr) auto;
}

.admin-sku-apply-band {
  display: grid;
  grid-template-columns: minmax(220px, 0.34fr) minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding: 12px;
  border-color: rgba(183, 255, 53, 0.22);
  background: rgba(183, 255, 53, 0.055);
}

.admin-sku-apply-band[hidden] {
  display: none;
}

.admin-sku-apply-preview {
  display: grid;
  gap: 5px;
  padding: 12px;
  border: 1px solid rgba(183, 255, 53, 0.2);
  border-radius: var(--sku-radius);
  background: rgba(0, 0, 0, 0.16);
}

:root[data-admin-theme='light'] .admin-sku-apply-preview {
  background: rgba(255, 255, 255, 0.45);
}

.admin-sku-apply-preview strong {
  overflow-wrap: anywhere;
  font-family: "Space Grotesk", Inter, sans-serif;
  font-size: 1.6rem;
}

.admin-sku-apply-band .admin-sku-form-grid {
  grid-template-columns: repeat(6, minmax(96px, 1fr));
  gap: 10px;
  align-items: end;
}

.admin-sku-reference-band {
  padding: 12px;
}

.admin-sku-reference-band .admin-sku-master-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.admin-sku-reference-band .admin-sku-master-card {
  min-height: 142px;
  padding: 12px;
  border-radius: var(--sku-radius);
  background: rgba(246, 247, 242, 0.035);
}

.admin-sku-reference-band .admin-sku-master-card-wide {
  grid-column: span 2;
}

.admin-sku-master-card h2,
.admin-request-card h4 {
  margin: 0 0 10px;
  color: var(--sku-ink);
  font-size: 0.78rem;
  font-weight: 900;
}

.admin-sku-token-list,
.admin-sku-master-stack {
  gap: 7px;
}

.admin-sku-token {
  min-height: 30px;
  padding: 6px 9px;
  border-radius: var(--sku-radius);
  background: var(--sku-panel);
  color: var(--sku-ink);
  font-size: 0.76rem;
}

.admin-sku-brand-block {
  gap: 7px;
}

.admin-sku-brand-block strong {
  color: var(--sku-muted);
  font-size: 0.68rem;
}

.admin-request-stack {
  gap: 8px;
}

.admin-request-card {
  padding: 10px;
  border-radius: var(--sku-radius);
  border-color: var(--sku-line);
  background: rgba(246, 247, 242, 0.04);
}

.admin-request-card .admin-chip,
.admin-request-result {
  border-radius: var(--sku-radius);
}

.admin-request-card h4 {
  font-family: "Space Grotesk", Inter, sans-serif;
  font-size: 1.25rem;
}

.admin-sku-table-shell {
  overflow: hidden;
}

.admin-sku-table-toolbar {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 10px;
  border-bottom: 1px solid var(--sku-line);
}

.admin-sku-live-gauge {
  justify-content: center;
  gap: 8px;
  min-width: 112px;
  min-height: 46px;
  padding: 8px 10px;
  border-radius: var(--sku-radius);
  background: rgba(41, 216, 189, 0.1);
  color: var(--sku-teal);
}

.admin-sku-live-gauge strong {
  font-family: "Space Grotesk", Inter, sans-serif;
  font-size: 1.55rem;
  line-height: 1;
}

.admin-sku-filter-strip {
  display: grid;
  grid-template-columns: minmax(220px, 1.2fr) repeat(4, minmax(130px, 0.7fr));
  gap: 8px;
  align-items: end;
}

.admin-sku-table-wrap {
  max-height: calc(100svh - 188px);
  padding-bottom: var(--sku-row-menu-space, 0px);
  border: 0;
  border-radius: 0;
  background: transparent;
}

.admin-sku-data-table {
  min-width: 1580px;
  border-collapse: separate;
  border-spacing: 0 6px;
  padding: 4px 8px 8px;
}

.admin-sku-data-table th {
  position: sticky;
  top: 0;
  z-index: 5;
  padding: 9px 10px;
  border: 0;
  background: var(--sku-bg);
  color: var(--sku-muted);
  font-size: 0.68rem;
  font-weight: 900;
}

.admin-sku-data-table td {
  padding: 8px 10px;
  border-top: 1px solid var(--sku-line);
  border-bottom: 1px solid var(--sku-line);
  background: rgba(246, 247, 242, 0.035);
  color: var(--sku-ink);
  vertical-align: middle;
}

.admin-sku-data-table tr td:first-child {
  border-left: 3px solid rgba(141, 149, 141, 0.5);
  border-radius: var(--sku-radius) 0 0 var(--sku-radius);
}

.admin-sku-data-table tr td:last-child {
  border-right: 1px solid var(--sku-line);
  border-radius: 0 var(--sku-radius) var(--sku-radius) 0;
}

.admin-sku-data-table tr.is-low td:first-child {
  border-left-color: var(--sku-coral);
}

.admin-sku-data-table tr.is-watch td:first-child {
  border-left-color: var(--sku-amber);
}

.admin-sku-data-table tr.is-ok td:first-child {
  border-left-color: var(--sku-teal);
}

.admin-sku-data-table :is(th:nth-child(1), td:nth-child(1)) {
  min-width: 136px;
}

.admin-sku-data-table :is(th:nth-child(2), td:nth-child(2)) {
  min-width: 200px;
}

.admin-sku-data-table :is(th:nth-child(4), td:nth-child(4)) {
  min-width: 180px;
}

.admin-sku-row-code,
.admin-sku-data-table td[data-col='Vol'],
.admin-sku-data-table td[data-col='ASTRA'],
.admin-sku-data-table td[data-col='Trigger'],
.admin-sku-data-table td[data-col='COGS'] {
  font-family: "Space Grotesk", Inter, sans-serif;
  font-weight: 800;
}

.admin-sku-tag-copy {
  max-width: 260px;
  padding: 0;
  color: var(--sku-ink);
}

.admin-sku-data-table td[data-col='SKU'] .admin-sku-tag-copy,
.admin-sku-row-code {
  white-space: nowrap;
}

.admin-sku-tag-copy:hover,
.admin-sku-tag-copy:focus-visible {
  color: var(--sku-lime);
}

.admin-sku-brand-pill,
.admin-sku-stock-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 30px;
  padding: 5px 8px;
  border-radius: var(--sku-radius);
  border: 1px solid var(--sku-line);
}

.admin-sku-brand-pill {
  background: rgba(117, 167, 255, 0.1);
  color: var(--sku-blue);
  font-size: 0.78rem;
  font-weight: 800;
}

.admin-sku-stock-pill {
  min-width: 86px;
  justify-content: space-between;
  background: rgba(41, 216, 189, 0.1);
}

.admin-sku-stock-pill.is-low {
  background: rgba(255, 116, 107, 0.12);
}

.admin-sku-stock-pill.is-watch {
  background: rgba(243, 196, 95, 0.12);
}

.admin-sku-stock-pill strong {
  font-family: "Space Grotesk", Inter, sans-serif;
}

.admin-sku-stock-pill small {
  color: var(--sku-muted);
  font-size: 0.66rem;
  font-weight: 900;
}

.admin-sku-rupiah-input {
  display: inline-flex;
  align-items: center;
  width: 124px;
  overflow: hidden;
  border: 1px solid var(--sku-line);
  border-radius: var(--sku-radius);
  background: var(--sku-panel);
}

.admin-sku-rupiah-input:focus-within {
  border-color: var(--sku-lime);
}

.admin-sku-rupiah-input > span {
  padding-left: 9px;
  color: var(--sku-muted);
  font-size: 0.72rem;
  font-weight: 850;
}

.admin-app[data-sku-db] .admin-sku-rupiah-input .admin-sku-sale-price-input {
  width: 88px;
  min-width: 0;
  padding: 8px 8px 8px 4px;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.admin-sku-row-menu-panel {
  border-radius: var(--sku-radius);
  background: color-mix(in srgb, var(--sku-bg) 92%, transparent);
}

.admin-sku-copy-message {
  border-radius: var(--sku-radius);
}

@media (max-width: 1320px) {
  .admin-sku-commandbar,
  .admin-sku-workbench,
  .admin-sku-workbench-request,
  .admin-sku-preview-surface,
  .admin-sku-apply-band,
  .admin-app[data-sku-db] .admin-sku-apply-collapse-body {
    grid-template-columns: 1fr;
  }

  .admin-sku-command-actions {
    justify-content: start;
    flex-wrap: wrap;
  }

  .admin-sku-commandmetrics {
    justify-content: start;
    flex-wrap: wrap;
  }

  .admin-sku-reference-band .admin-sku-master-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 820px) {
  .admin-app[data-sku-db] {
    padding: 12px;
  }

  .admin-app[data-sku-db] .admin-shell {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .admin-app[data-sku-db] .admin-rail {
    position: sticky;
    top: 0;
    display: flex;
    flex-direction: row;
    align-items: center;
    min-height: 0;
    padding: 8px;
    overflow-x: auto;
    border-right: 0;
    border-bottom: 1px solid var(--sku-line);
    background: var(--sku-bg);
  }

  .admin-app[data-sku-db] .admin-rail-brand {
    flex: 0 0 auto;
    padding: 0 8px 0 0;
  }

  .admin-app[data-sku-db] .admin-rail-nav,
  .admin-app[data-sku-db] .admin-rail-footer {
    display: flex;
    flex: 0 0 auto;
    gap: 6px;
    padding: 0;
    margin: 0;
  }

  .admin-app[data-sku-db] .admin-rail-link {
    flex: 0 0 auto;
    width: 42px;
    height: 42px;
  }

  .admin-app[data-sku-db] .admin-rail-link::after {
    display: none;
  }

  .admin-sku-commandbar {
    min-height: 0;
    gap: 8px;
  }

  .admin-sku-commandmark {
    min-width: 0;
  }

  .admin-sku-commandmetrics {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 6px;
  }

  .admin-sku-commandmetrics span {
    display: grid;
    align-content: center;
    gap: 3px;
    min-height: 42px;
    padding: 7px;
  }

  .admin-sku-commandmetrics strong {
    font-size: 0.96rem;
  }

  .admin-sku-commandmetrics small {
    font-size: 0.58rem;
  }

  .admin-sku-command-actions {
    display: grid;
    grid-template-columns: repeat(3, max-content);
    justify-content: start;
  }

  .admin-sku-preview-surface {
    min-height: 0;
    padding: 12px;
  }

  .admin-sku-preview-surface strong {
    font-size: 2.25rem;
  }

  .admin-sku-apply-band .admin-sku-form-grid,
  .admin-sku-filter-strip,
  .admin-sku-master-create-grid,
  .admin-sku-master-create-grid .admin-sku-mini-form,
  .admin-sku-master-create-grid .admin-sku-mini-form:has(select),
  .admin-sku-table-toolbar,
  .admin-sku-reference-band .admin-sku-master-grid {
    grid-template-columns: 1fr;
  }

  .admin-sku-segment-strip {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }

  .admin-sku-segment-strip span {
    min-height: 58px;
    padding: 7px 5px;
  }

  .admin-sku-segment-strip em {
    font-size: 0.98rem;
  }

  .admin-sku-segment-strip small {
    display: none;
  }

  .admin-sku-builder-compact {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .admin-sku-builder-tag,
  .admin-sku-reference-band .admin-sku-master-card-wide {
    grid-column: auto;
  }

  .admin-sku-builder-tag {
    grid-column: 1 / -1;
  }

  .admin-sku-side-stack {
    max-height: 420px;
    overflow: auto;
  }

  .admin-sku-commandmetrics span {
    min-width: 0;
  }
}

/* SKU DB correction: monochrome Store Ops-aligned workspace */
body:has(.admin-app[data-sku-db])::before,
body:has(.admin-app[data-sku-db])::after {
  display: none;
}

.admin-app[data-sku-db] {
  --sku-bg: #050505;
  --sku-ink: #f6f6f2;
  --sku-muted: rgba(246, 246, 242, 0.52);
  --sku-line: rgba(246, 246, 242, 0.12);
  --sku-panel: rgba(246, 246, 242, 0.035);
  --sku-panel-strong: rgba(246, 246, 242, 0.055);
  --sku-toggle: #9dff00;
  --sku-radius: 24px;
  background: var(--sku-bg);
}

:root[data-admin-theme='light'] .admin-app[data-sku-db] {
  --sku-bg: #f7f7f4;
  --sku-ink: #111111;
  --sku-muted: rgba(17, 17, 17, 0.52);
  --sku-line: rgba(17, 17, 17, 0.13);
  --sku-panel: rgba(17, 17, 17, 0.035);
  --sku-panel-strong: rgba(17, 17, 17, 0.055);
}

.admin-app[data-sku-db] :where(svg) {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex: 0 0 auto;
}

.admin-app[data-sku-db] .admin-sku-commandbar {
  grid-template-columns: minmax(0, 1fr) auto;
  min-height: 54px;
  padding: 8px;
  border-radius: 999px;
  background: var(--sku-panel);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.admin-sku-commandmark {
  min-width: 0;
  padding: 0 12px 0 4px;
}

.admin-sku-commandglyph {
  display: inline-grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1px solid var(--sku-line);
  border-radius: 999px;
  background: var(--sku-panel-strong);
  color: var(--sku-ink);
}

.admin-sku-commandglyph svg {
  width: 19px;
  height: 19px;
}

.admin-sku-mode {
  font-size: 0.84rem;
  font-weight: 850;
}

.admin-sku-commandmetrics {
  display: none;
}

.admin-sku-command-actions {
  gap: 8px;
}

.admin-sku-user-chip,
.admin-icon-btn,
.admin-sku-action-btn,
.admin-app[data-sku-db] .admin-primary-btn,
.admin-app[data-sku-db] .admin-ghost-btn,
.admin-app[data-sku-db] .admin-menu-trigger,
.admin-app[data-sku-db] .admin-menu-item,
.admin-sku-tag-copy,
.admin-sku-brand-pill,
.admin-sku-stock-pill,
.admin-request-result,
.admin-request-card .admin-chip,
.admin-sku-token {
  border-radius: 999px;
}

.admin-sku-user-chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  max-width: 230px;
  padding: 0 13px;
  border: 1px solid var(--sku-line);
  background: var(--sku-panel-strong);
  color: var(--sku-ink);
  font-weight: 750;
}

.admin-sku-user-chip span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-icon-btn {
  display: inline-grid;
  place-items: center;
  width: 38px;
  min-width: 38px;
  height: 38px;
  padding: 0;
}

.admin-sku-action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 40px;
  padding: 0 16px;
}

.admin-app[data-sku-db] .admin-primary-btn,
.admin-app[data-sku-db] .admin-primary-btn:hover {
  border-color: var(--sku-ink);
  background: var(--sku-ink);
  color: var(--sku-bg);
}

.admin-app[data-sku-db] .admin-ghost-btn,
.admin-app[data-sku-db] .admin-menu-trigger,
.admin-app[data-sku-db] .admin-menu-item {
  border-color: var(--sku-line);
  background: var(--sku-panel-strong);
  color: var(--sku-ink);
}

.admin-sku-composer,
.admin-sku-dock,
.admin-sku-apply-band,
.admin-sku-reference-band,
.admin-sku-table-shell,
.admin-sku-reference-band .admin-sku-master-card,
.admin-request-card {
  border-color: var(--sku-line);
  border-radius: var(--sku-radius);
  background: var(--sku-panel);
