  max-width: 920px;
  padding-right: 120px;
  font-size: clamp(3.2rem, 8.6vw, 7.4rem);
}

.admin-launch-card-executive .admin-launch-open {
  background: #ffffff;
  color: #111312;
}

.admin-launch-card-store {
  --launch-accent: #00a878;
  background: #f3fff9;
}

.admin-launch-card-jenang {
  --launch-accent: #ff6b4a;
  background: #fff8f5;
}

.admin-launch-card-zero {
