/* Shared topbar chrome for non-dashboard admin pages. */
.admin-topbar {
  position: relative;
  z-index: 3200;
}

.admin-topbar-actions-shared {
  --admin-topbar-control-height: 44px;
  position: relative;
  z-index: 4200;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: nowrap;
  gap: 10px;
  min-width: 0;
}

.admin-topbar-actions-status {
  flex-wrap: wrap;
}

.admin-topbar-actions-profit-loss {
  flex-wrap: wrap;
}

.admin-topbar-actions-profit-loss .profit-loss-controls {
  flex: 0 1 auto;
}

.admin-topbar-actions-shared > .admin-primary-btn,
.admin-topbar-actions-shared > .admin-ghost-btn,
.admin-topbar-actions-shared > .admin-link-btn,
.admin-topbar-actions-shared > .admin-view-indicator {
  height: var(--admin-topbar-control-height);
  min-height: var(--admin-topbar-control-height);
  padding-block: 0;
}

.admin-topbar-actions-shared .admin-menu-shell {
  position: relative;
  z-index: 6400;
  flex: 0 0 auto;
  width: auto;
}

.admin-topbar-actions-shared .admin-menu-trigger,
.admin-topbar-actions-shared .admin-search-shell.admin-search-shell-topbar {
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  background: #111114;
  color: rgba(255, 255, 255, 0.88);
  box-shadow:
    0 18px 60px rgba(0, 0, 0, 0.45),
    inset 0 1px 0 rgba(255, 255, 255, 0.09);
}

.admin-topbar-actions-shared .admin-menu-trigger {
  position: relative;
  display: grid;
  place-items: center;
  width: var(--admin-topbar-control-height);
  min-width: var(--admin-topbar-control-height);
  height: var(--admin-topbar-control-height);
  min-height: var(--admin-topbar-control-height);
  padding: 0;
  overflow: hidden;
  border-radius: 999px;
  letter-spacing: 0;
  transition:
    border-radius 0.34s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.16s ease,
    border-color 0.18s ease,
    background 0.18s ease;
}

.admin-topbar-actions-shared .admin-menu-trigger::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(to bottom, rgba(255, 255, 255, 0.09), transparent);
}

.admin-topbar-actions-shared .admin-menu-trigger:hover,
.admin-topbar-actions-shared .admin-menu-trigger[aria-expanded="true"] {
  border-color: rgba(255, 255, 255, 0.14);
  background: #151518;
  color: #ffffff;
  box-shadow:
    0 18px 60px rgba(0, 0, 0, 0.45),
    inset 0 1px 0 rgba(255, 255, 255, 0.09);
  filter: none;
  transform: none;
}

.admin-topbar-actions-shared .admin-menu-trigger[aria-expanded="true"] {
  border-radius: 22px;
}

.admin-topbar-actions-shared .admin-menu-trigger svg {
  position: absolute;
  width: 24px;
  height: 24px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2.2;
  transition:
    opacity 0.24s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.24s cubic-bezier(0.22, 1, 0.36, 1);
}

.admin-topbar-actions-shared .admin-menu-close-icon {
  opacity: 0;
  transform: rotate(-90deg) scale(0.7);
}

.admin-topbar-actions-shared .admin-menu-trigger[aria-expanded="true"] .admin-menu-open-icon {
  opacity: 0;
  transform: rotate(90deg) scale(0.7);
}

.admin-topbar-actions-shared .admin-menu-trigger[aria-expanded="true"] .admin-menu-close-icon {
  opacity: 1;
  transform: rotate(0deg) scale(1);
}

.admin-topbar-actions-shared .admin-menu-panel {
  right: 0;
  left: auto;
  top: 100%;
  z-index: 6500;
  width: min(270px, calc(100vw - 32px));
  min-width: 0;
  max-height: min(580px, calc(100vh - 140px));
  gap: 4px;
  padding: 10px;
  overflow: hidden auto;
  isolation: isolate;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 24px;
  background: rgba(16, 16, 18, 0.96);
  box-shadow:
    0 28px 90px rgba(0, 0, 0, 0.62),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
  transform: translateY(14px);
  transform-origin: top center;
  animation: adminFloatingMenuIn 0.42s cubic-bezier(0.16, 1, 0.3, 1);
  animation-fill-mode: both;
}

.admin-topbar-actions-shared .admin-menu-panel::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background: linear-gradient(to bottom, rgba(255, 255, 255, 0.07), transparent);
}

.admin-topbar-actions-shared .admin-menu-panel[hidden] {
  display: none !important;
}

.admin-topbar-actions-shared .admin-menu-item {
  position: relative;
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  min-height: 48px;
  padding: 0 12px;
  overflow: hidden;
  border: 0;
  border-radius: 16px;
  background: transparent;
  color: rgba(255, 255, 255, 0.6);
  text-align: left;
  letter-spacing: 0;
  box-shadow: none;
  filter: none;
  transform: none;
  animation: adminMenuItemIn 0.32s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.admin-topbar-actions-shared .admin-menu-item::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: rgba(255, 255, 255, 0.075);
  opacity: 0;
  transition: opacity 0.18s ease;
}

.admin-topbar-actions-shared .admin-menu-item:hover,
.admin-topbar-actions-shared .admin-menu-item:focus-visible {
  background: transparent;
  color: rgba(255, 255, 255, 0.9);
  box-shadow: none;
  filter: none;
  transform: none;
}

.admin-topbar-actions-shared .admin-menu-item:hover::before,
.admin-topbar-actions-shared .admin-menu-item:focus-visible::before {
  opacity: 1;
}

.admin-topbar-actions-shared .admin-menu-item > span {
  position: relative;
  z-index: 1;
}

.admin-topbar-actions-shared .admin-menu-icon {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.055);
  color: currentColor;
}

.admin-topbar-actions-shared .admin-menu-icon svg {
  width: 19px;
  height: 19px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.admin-topbar-actions-shared .admin-menu-item strong {
  color: currentColor;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0;
}

.admin-topbar-actions-shared .admin-menu-item small {
  display: none;
}

.admin-topbar-actions-shared .admin-menu-item-danger:hover,
.admin-topbar-actions-shared .admin-menu-item-danger:focus-visible {
  color: #ffd2d2;
}

.admin-topbar-actions-shared .admin-search-shell.admin-search-shell-topbar {
  position: relative;
  display: block;
  flex: 0 0 var(--admin-topbar-control-height);
  width: var(--admin-topbar-control-height);
  min-width: var(--admin-topbar-control-height);
  max-width: min(360px, calc(100vw - 118px));
  height: var(--admin-topbar-control-height);
  min-height: var(--admin-topbar-control-height);
  padding: 0;
  overflow: visible;
  border-radius: 999px;
  transition:
