    min-width 0.46s cubic-bezier(0.22, 1, 0.36, 1),
    border-radius 0.34s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.18s ease,
    background 0.18s ease;
}

.admin-topbar-actions-shared .admin-search-shell.admin-search-shell-topbar.is-search-open {
