/* Settings UX and shared card-radius protocol */
:root,
:root[data-admin-theme='dark'],
:root[data-admin-theme='light'] {
  --admin-card-radius: 24px;
  --admin-card-inner-radius: 16px;
}

.admin-app.admin-app-suite :is(
  .admin-panel,
  .admin-metric-card,
  .admin-note-card,
  .admin-event-item,
  .admin-affiliate-card,
  .admin-request-card,
  .admin-sku-master-card,
  .admin-modal-card
),
.admin-app[data-sku-db] :where(
  .admin-sku-composer,
  .admin-sku-dock,
  .admin-sku-apply-band,
  .admin-sku-reference-band,
  .admin-sku-table-shell,
  .admin-sku-reference-band .admin-sku-master-card,
  .admin-request-card,
  .admin-sku-preview-surface,
  .admin-modal-card
) {
  border-radius: var(--admin-card-radius);
}

.admin-view-settings {
  width: 100%;
  max-width: none;
  margin-inline: 0;
}

.admin-settings-grid-minimal {
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: start;
}

.admin-settings-grid-minimal .admin-settings-card {
  gap: 18px;
  padding: 22px;
}

.admin-settings-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  min-width: 0;
}

.admin-settings-card-head > div:first-child {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.admin-settings-card-head h3 {
  margin: 0;
}

.admin-settings-theme-card {
  min-height: 96px;
}

.admin-regional-card {
  grid-column: 1 / -1;
}

.admin-regional-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.admin-regional-grid label {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.admin-regional-grid select {
  width: 100%;
  min-height: 44px;
  border-radius: 12px;
}

.admin-regional-preview {
  display: grid;
  gap: 4px;
  min-width: min(260px, 100%);
  padding: 12px 14px;
  border: 1px solid var(--admin-border);
  border-radius: var(--admin-card-inner-radius);
  background: var(--admin-surface-soft);
  text-align: right;
}

.admin-regional-preview strong,
.admin-regional-preview span {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-regional-preview strong {
  color: var(--admin-text);
  font-size: 0.86rem;
}

.admin-regional-preview span {
  color: var(--admin-muted);
  font-size: 0.78rem;
  font-weight: 800;
}

.admin-theme-toggle {
  display: grid;
  grid-template-columns: repeat(3, minmax(84px, 1fr));
  gap: 4px;
  min-width: min(100%, 312px);
  padding: 4px;
  border: 1px solid var(--admin-border);
  border-radius: var(--admin-card-inner-radius);
  background: var(--admin-surface-soft);
}

.admin-theme-toggle .admin-theme-option,
.admin-theme-toggle .admin-theme-option:hover {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 38px;
  padding: 0 14px;
  border: 0;
  border-radius: 12px;
  background: transparent;
  color: var(--admin-muted);
  box-shadow: none;
  transform: none;
}

.admin-theme-toggle .admin-theme-option span {
  color: inherit;
  font-size: 0.82rem;
  font-weight: 800;
  line-height: 1;
}

.admin-theme-toggle .admin-theme-option.is-active {
  background: var(--admin-text);
  color: var(--admin-bg);
}

.admin-settings-lock-zone {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 96px;
}

.admin-settings-lock-icon {
  display: inline-grid;
  place-items: center;
  width: 42px;
  height: 42px;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: var(--admin-text);
}

.admin-settings-lock-icon:hover,
.admin-settings-lock-icon:focus-visible {
  opacity: 0.68;
