  flex: 0 0 auto;
  min-height: 46px;
  padding: 0 18px;
  border: 1px solid var(--admin-text);
  border-radius: 14px;
  background: var(--admin-text);
  color: var(--admin-bg);
  font: 800 0.8rem/1 "Space Grotesk", sans-serif;
  text-decoration: none;
  transition: opacity 160ms ease, transform 160ms ease;
}

.admin-destination-button svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: transform 160ms ease;
}

.admin-destination-button:hover {
  color: var(--admin-bg);
  opacity: 0.82;
  transform: translateY(-1px);
}

.admin-destination-button:hover svg {
  transform: translateX(2px);
}

.admin-destination-button:focus-visible {
  outline: 2px solid var(--admin-text);
  outline-offset: 3px;
}

@media (min-width: 1280px) {
  .admin-settings-grid-minimal {
    grid-template-columns: minmax(680px, 1fr) minmax(380px, 0.46fr) 42px;
    align-items: stretch;
  }

  .admin-settings-theme-card {
    grid-column: 1;
    grid-row: 1;
    align-self: start;
  }

  .admin-settings-lock-zone {
    grid-column: 3;
    grid-row: 1;
    align-self: start;
  }

  .admin-regional-card {
    grid-column: 2;
    grid-row: 1 / span 2;
    align-content: start;
    align-self: stretch;
  }

  .admin-regional-card .admin-settings-card-head {
    align-items: stretch;
    flex-direction: column;
    gap: 16px;
  }

  .admin-regional-grid {
    grid-template-columns: 1fr;
    gap: 14px;
  }

  .admin-regional-preview {
    min-width: 0;
    padding: 14px 16px;
    text-align: left;
  }

  .admin-settings-device-card {
    grid-column: 1;
    grid-row: 2;
  }

  .admin-settings-device-card .admin-device-current {
    grid-template-columns: 1fr;
    align-items: stretch;
  }

  .admin-settings-device-card .admin-device-current-actions {
    grid-template-columns: minmax(0, 1fr) auto;
  }
}

.admin-device-current {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(320px, 0.62fr);
  gap: 16px;
  align-items: end;
  padding: 16px;
  border: 1px solid var(--admin-border);
  border-radius: var(--admin-card-inner-radius);
  background: var(--admin-surface-soft);
}

.admin-device-current-main {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.admin-device-current-main span,
.admin-settings-device-list-head span,
.admin-device-manual-entry summary {
  color: var(--admin-muted);
  font-size: 0.72rem;
  font-weight: 850;
  letter-spacing: 0;
}

.admin-device-current-main code,
.admin-settings-device-copy code {
  display: block;
  min-width: 0;
  overflow: hidden;
  color: var(--admin-text);
  font-family: "Space Grotesk", ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.86rem;
  font-weight: 750;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-device-current-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: end;
}

.admin-device-label-field {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.admin-device-label-field input,
.admin-device-manual-entry .admin-affiliate-field input {
  width: 100%;
  min-height: 44px;
  padding: 0 12px;
  border: 1px solid var(--admin-border);
  border-radius: 12px;
  background: var(--admin-surface);
  color: var(--admin-text);
  box-shadow: none;
}

.admin-device-label-field input:focus,
.admin-device-manual-entry .admin-affiliate-field input:focus {
  border-color: color-mix(in srgb, var(--admin-text) 28%, transparent);
  outline: none;
}

.admin-device-ignore-btn {
  min-height: 44px;
  white-space: nowrap;
}

.admin-device-manual-entry {
  border: 1px solid var(--admin-border);
  border-radius: var(--admin-card-inner-radius);
  background: transparent;
}

.admin-device-manual-entry summary {
  min-height: 48px;
  padding: 0 16px;
  cursor: pointer;
  list-style: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.admin-device-manual-entry summary::-webkit-details-marker {
  display: none;
}

.admin-device-manual-entry summary::after {
  content: "+";
  color: var(--admin-text);
  font-size: 1.1rem;
  line-height: 1;
}

.admin-device-manual-entry[open] summary::after {
  content: "-";
}

.admin-device-manual-entry .admin-settings-form {
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr) auto;
  gap: 12px;
  align-items: end;
  padding: 0 16px 16px;
}

.admin-settings-device-list-head {
  display: flex;
  align-items: center;
  min-height: 20px;
}

.admin-settings-device-list {
  display: grid;
  gap: 10px;
}

.admin-settings-device-list .admin-empty {
  margin: 0;
  padding: 16px;
  border: 1px dashed var(--admin-border);
  border-radius: var(--admin-card-inner-radius);
  text-align: center;
}

.admin-settings-device-row {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 40px;
  align-items: center;
  gap: 12px;
  min-height: 62px;
  padding: 10px 10px 10px 14px;
  border: 1px solid var(--admin-border);
  border-radius: var(--admin-card-inner-radius);
  background: var(--admin-surface-soft);
}

.admin-settings-device-mark {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #22c55e;
  box-shadow: 0 0 0 6px rgba(34, 197, 94, 0.12);
}

.admin-settings-device-copy {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.admin-settings-device-copy strong {
  min-width: 0;
  overflow: hidden;
  color: var(--admin-text);
  font-size: 0.9rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-settings-device-copy code {
  color: var(--admin-muted);
  font-size: 0.76rem;
}

.admin-settings-device-remove {
  display: inline-grid;
  place-items: center;
  width: 40px;
  height: 40px;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--admin-muted);
  cursor: pointer;
}

.admin-settings-device-remove:hover,
.admin-settings-device-remove:focus-visible {
  opacity: 0.68;
  outline: none;
}

.admin-marketplace-auth-card {
  grid-column: 1 / -1;
}

.admin-marketplace-auth-head > div:first-child {
  max-width: 760px;
}

.admin-marketplace-auth-head p,
.admin-marketplace-auth-footnote {
  margin: 0;
  color: var(--admin-muted);
  font-size: 0.8rem;
  line-height: 1.55;
}

.admin-marketplace-auth-list {
  display: grid;
  gap: 10px;
}

.admin-marketplace-auth-row {
  display: grid;
  grid-template-columns: minmax(180px, 1fr) minmax(150px, 0.7fr) minmax(190px, 0.8fr) auto;
  align-items: center;
  gap: 16px;
  min-height: 76px;
  padding: 14px 16px;
  border: 1px solid var(--admin-border);
  border-radius: var(--admin-card-inner-radius);
  background: var(--admin-surface-soft);
}

.admin-marketplace-auth-shop,
.admin-marketplace-auth-date {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.admin-marketplace-auth-shop strong,
.admin-marketplace-auth-date strong {
  overflow: hidden;
  color: var(--admin-text);
  font-size: 0.9rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-marketplace-auth-shop span,
.admin-marketplace-auth-date span {
  color: var(--admin-muted);
  font-size: 0.72rem;
  line-height: 1.4;
}

.admin-marketplace-auth-status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  width: max-content;
  max-width: 100%;
  min-height: 30px;
  padding: 0 11px;
  border: 1px solid var(--admin-border);
  border-radius: 999px;
  color: var(--admin-muted);
  font-size: 0.72rem;
  font-weight: 850;
}

.admin-marketplace-auth-status::before {
  content: "";
  flex: 0 0 auto;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}

.admin-marketplace-auth-status.is-connected {
  border-color: rgba(34, 197, 94, 0.28);
  background: rgba(34, 197, 94, 0.09);
  color: #22c55e;
}

.admin-marketplace-auth-status.is-renewal-due {
  border-color: rgba(245, 158, 11, 0.32);
  background: rgba(245, 158, 11, 0.1);
  color: #f59e0b;
}

.admin-marketplace-auth-status.is-expired,
.admin-marketplace-auth-status.is-not-connected {
  border-color: rgba(239, 68, 68, 0.3);
  background: rgba(239, 68, 68, 0.09);
  color: #ef4444;
}

.admin-marketplace-auth-row .admin-primary-btn {
  min-width: 168px;
  min-height: 42px;
  white-space: nowrap;
}

.admin-marketplace-auth-row .admin-primary-btn:disabled,
.admin-marketplace-auth-head button:disabled {
  cursor: wait;
  opacity: 0.55;
}

.admin-marketplace-auth-notice {
  padding: 12px 14px;
  border: 1px solid rgba(34, 197, 94, 0.28);
  border-radius: 12px;
  background: rgba(34, 197, 94, 0.09);
  color: #22c55e;
  font-size: 0.8rem;
  font-weight: 750;
  line-height: 1.5;
}

.admin-marketplace-auth-notice.is-error {
  border-color: rgba(239, 68, 68, 0.3);
  background: rgba(239, 68, 68, 0.09);
  color: #ef4444;
}

.admin-marketplace-auth-dialog {
  width: min(580px, calc(100vw - 32px));
  max-height: calc(100vh - 40px);
  padding: 0;
  overflow: auto;
  border: 1px solid var(--admin-border);
  border-radius: 22px;
  background: var(--admin-surface);
  color: var(--admin-text);
  box-shadow: 0 28px 90px rgba(0, 0, 0, 0.4);
}

.admin-marketplace-auth-dialog::backdrop {
  background: rgba(2, 6, 23, 0.72);
  backdrop-filter: blur(5px);
}

.admin-marketplace-auth-dialog-card {
  display: grid;
  grid-template-columns: 50px minmax(0, 1fr);
  gap: 16px;
  margin: 0;
  padding: 24px;
}

.admin-marketplace-auth-dialog-icon {
  display: grid;
  place-items: center;
  width: 50px;
  height: 50px;
  border-radius: 16px;
  background: #ee4d2d;
  color: #fff;
  font: 800 1.45rem/1 "Space Grotesk", sans-serif;
}

.admin-marketplace-auth-dialog-card h3,
.admin-marketplace-auth-dialog-card p {
  margin: 0;
}

.admin-marketplace-auth-dialog-card > div:nth-child(2) {
  display: grid;
  gap: 6px;
}

.admin-marketplace-auth-dialog-card > div:nth-child(2) p,
.admin-marketplace-auth-dialog-card ol,
.admin-marketplace-auth-dialog-warning {
  color: var(--admin-muted);
  font-size: 0.82rem;
  line-height: 1.55;
}

.admin-marketplace-auth-dialog-card ol,
.admin-marketplace-auth-dialog-warning,
.admin-marketplace-auth-dialog-card .admin-form-error,
.admin-marketplace-auth-dialog-actions {
  grid-column: 1 / -1;
}

.admin-marketplace-auth-dialog-card ol {
  display: grid;
  gap: 10px;
  margin: 4px 0 0;
  padding-left: 24px;
}

.admin-marketplace-auth-dialog-warning {
  padding: 12px 14px;
  border: 1px solid rgba(245, 158, 11, 0.25);
  border-radius: 12px;
  background: rgba(245, 158, 11, 0.08);
}

.admin-marketplace-auth-dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 4px;
}

:root[data-admin-theme='light'] .admin-settings-grid-minimal .admin-panel,
:root[data-admin-theme='light'] .admin-regional-preview,
:root[data-admin-theme='light'] .admin-device-current,
:root[data-admin-theme='light'] .admin-device-manual-entry,
:root[data-admin-theme='light'] .admin-settings-device-row,
:root[data-admin-theme='light'] .admin-marketplace-auth-row {
  border-color: rgba(15, 23, 42, 0.1);
  background: #ffffff;
}

:root[data-admin-theme='light'] .admin-theme-toggle {
  border-color: rgba(15, 23, 42, 0.1);
  background: #f1f5f9;
}

:root[data-admin-theme='light'] .admin-device-current,
:root[data-admin-theme='light'] .admin-settings-device-row {
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.05);
}

@media (max-width: 940px) {
  .admin-settings-grid-minimal,
  .admin-regional-grid,
  .admin-device-current,
  .admin-device-current-actions,
  .admin-device-manual-entry .admin-settings-form {
    grid-template-columns: 1fr;
  }

  .admin-settings-lock-zone {
    justify-content: flex-start;
    min-height: 42px;
  }

  .admin-settings-card-head {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-settings-destination-card {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-settings-destination-card .admin-destination-button {
    align-self: flex-start;
  }

  .admin-regional-preview {
    text-align: left;
  }

  .admin-theme-toggle {
    width: 100%;
    min-width: 0;
  }

  .admin-marketplace-auth-row {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .admin-marketplace-auth-date {
    grid-column: 1;
  }

  .admin-marketplace-auth-row .admin-primary-btn {
    grid-column: 2;
    grid-row: 1 / span 2;
  }
}

@media (max-width: 540px) {
  .admin-settings-grid-minimal .admin-settings-card {
    padding: 18px;
  }

  .admin-theme-toggle {
    grid-template-columns: 1fr;
  }

  .admin-settings-destination-copy,
  .admin-accounting-wallet-destination-copy {
    align-items: flex-start;
  }

  .admin-settings-destination-card .admin-destination-button,
  .admin-accounting-wallet-destination .admin-destination-button {
    width: 100%;
  }

  .admin-marketplace-auth-row {
    grid-template-columns: 1fr;
    align-items: stretch;
  }

  .admin-marketplace-auth-date,
  .admin-marketplace-auth-row .admin-primary-btn {
    grid-column: auto;
    grid-row: auto;
  }

  .admin-marketplace-auth-row .admin-primary-btn {
    width: 100%;
  }

  .admin-marketplace-auth-dialog-card {
    grid-template-columns: 42px minmax(0, 1fr);
    padding: 20px;
  }

  .admin-marketplace-auth-dialog-icon {
    width: 42px;
    height: 42px;
    border-radius: 13px;
  }

  .admin-marketplace-auth-dialog-actions {
    flex-direction: column-reverse;
  }

  .admin-marketplace-auth-dialog-actions button {
    width: 100%;
  }
}

.admin-wallet-view {
  gap: 18px;
  width: 100%;
  max-width: none;
}

.admin-wallet-command {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  min-height: 64px;
  padding: 12px;
  border: 1px solid var(--admin-border);
  border-radius: var(--admin-card-radius);
  background: var(--admin-surface);
  box-shadow: var(--admin-shadow);
}

.admin-wallet-mode {
  width: min(280px, 100%);
}

.admin-wallet-actions {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  min-width: 0;
}

.admin-wallet-refresh svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2;
}

.admin-wallet-refresh.is-loading svg {
  animation: admin-wallet-spin 900ms linear infinite;
}

.admin-wallet-backtrack {
  min-height: 36px;
  padding: 0 14px;
  border: 1px solid var(--admin-border);
  border-radius: 8px;
  background: var(--admin-surface);
  color: var(--admin-text);
  font: 800 0.76rem/1 "Space Grotesk", sans-serif;
  cursor: pointer;
}

.admin-wallet-backtrack:hover:not(:disabled),
.admin-wallet-backtrack:focus-visible:not(:disabled) {
  border-color: color-mix(in srgb, var(--admin-accent) 58%, var(--admin-border));
  outline: none;
}

.admin-wallet-backtrack:disabled {
  color: var(--admin-muted);
  cursor: not-allowed;
  opacity: 0.66;
}

.admin-wallet-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.admin-wallet-stat {
  display: grid;
  gap: 8px;
  min-width: 0;
  padding: 18px;
  border: 1px solid var(--admin-border);
  border-radius: var(--admin-card-radius);
  background: var(--admin-surface);
  box-shadow: var(--admin-shadow);
}

.admin-wallet-stat span {
  color: var(--admin-muted);
  font-size: 0.72rem;
  font-weight: 850;
  letter-spacing: 0;
}

.admin-wallet-stat strong {
  min-width: 0;
  overflow: hidden;
  color: var(--admin-text);
  font: 800 clamp(1.35rem, 2.4vw, 2.2rem)/1 "Space Grotesk", sans-serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-wallet-panel {
  gap: 16px;
}

.admin-wallet-table-wrap[hidden] {
  display: none;
}

.admin-wallet-table th,
.admin-wallet-table td {
  white-space: nowrap;
}

.admin-wallet-table th:nth-child(5),
.admin-wallet-table td:nth-child(5) {
  text-align: center;
}

.admin-wallet-account {
  min-width: min(280px, 42vw);
}

.admin-wallet-account-title {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  max-width: 100%;
  min-width: 0;
}

.admin-wallet-account strong,
.admin-wallet-account small {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.admin-wallet-account strong {
  color: var(--admin-text);
  font-size: 0.9rem;
}

.admin-wallet-total-row td {
  background: color-mix(in srgb, var(--admin-surface) 84%, var(--admin-bg));
  color: var(--admin-text);
  font-weight: 850;
}

.admin-wallet-total-row .admin-wallet-account strong {
  font-size: 0.94rem;
}

.admin-wallet-total-row .admin-wallet-updated {
  color: var(--admin-text);
}

.admin-wallet-row-unset td {
  background: color-mix(in srgb, var(--admin-muted) 24%, var(--admin-bg));
  color: color-mix(in srgb, var(--admin-muted) 90%, var(--admin-bg));
}

.admin-wallet-row-unset :is(strong, .admin-wallet-orders-cell, .admin-wallet-updated) {
