.admin-wallet-row-unset .admin-wallet-set-link {
  color: var(--admin-text);
  font-weight: 900;
}

.admin-wallet-set-link {
  flex: 0 0 auto;
  border: 0;
  background: transparent;
  color: var(--admin-muted);
  font: 850 0.68rem/1 "Space Grotesk", sans-serif;
  padding: 0;
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
}

.admin-wallet-set-link:hover:not(:disabled),
.admin-wallet-set-link:focus-visible:not(:disabled) {
  color: var(--admin-text);
  outline: none;
}

.admin-wallet-set-link:disabled {
  cursor: not-allowed;
  opacity: 0.58;
}

.admin-wallet-account small {
  margin-top: 4px;
  color: var(--admin-muted);
  font-size: 0.72rem;
}

.admin-wallet-orders-cell {
  color: var(--admin-text);
  font: 800 0.82rem/1 "Space Grotesk", sans-serif;
}

.admin-wallet-updated {
  display: block;
  max-width: 150px;
  overflow: hidden;
  color: var(--admin-muted);
  font: 700 0.68rem/1.15 "Space Grotesk", sans-serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-wallet-action-cell {
  text-align: right;
}

.admin-wallet-release-control {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  min-width: 220px;
}

.admin-wallet-balance-summary {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  min-width: 0;
}

.admin-wallet-balance-control {
  display: grid;
  grid-template-columns: minmax(96px, 0.8fr) minmax(168px, 1fr) auto;
