  border-radius: 8px;
  background: var(--admin-surface);
  color: var(--admin-text);
  font: 800 0.76rem/1 "Space Grotesk", sans-serif;
}

.admin-wallet-balance-amount,
.admin-wallet-balance-at {
  width: 100%;
  min-height: 36px;
  min-width: 0;
  padding: 0 10px;
  border: 1px solid var(--admin-border);
  border-radius: 8px;
  background: var(--admin-surface);
  color: var(--admin-text);
  font: 800 0.74rem/1 "Space Grotesk", sans-serif;
}

.admin-wallet-release-amount:focus {
  border-color: color-mix(in srgb, var(--admin-accent) 58%, var(--admin-border));
  outline: none;
}

.admin-wallet-balance-amount:focus,
.admin-wallet-balance-at:focus {
  border-color: color-mix(in srgb, var(--admin-accent) 58%, var(--admin-border));
  outline: none;
}

.admin-wallet-release-amount:disabled {
  color: var(--admin-muted);
  opacity: 0.66;
}

.admin-wallet-balance-amount:disabled,
.admin-wallet-balance-at:disabled {
  color: var(--admin-muted);
  opacity: 0.66;
}

.admin-wallet-action {
  min-width: 92px;
  min-height: 36px;
  padding: 0 14px;
  border: 1px solid var(--admin-border);
  border-radius: 999px;
  background: var(--admin-text);
  color: var(--admin-bg);
  font: 800 0.76rem/1 "Space Grotesk", sans-serif;
  cursor: pointer;
}

.admin-wallet-action:hover:not(:disabled),
.admin-wallet-action:focus-visible:not(:disabled) {
  opacity: 0.82;
  outline: none;
}

.admin-wallet-action:disabled {
  background: transparent;
  color: var(--admin-muted);
  cursor: not-allowed;
  opacity: 0.66;
}

.admin-wallet-action.is-secondary {
  background: var(--admin-surface);
  color: var(--admin-text);
}

.admin-wallet-api[hidden] {
  display: none;
}

.admin-wallet-api {
  display: grid;
  gap: 12px;
}

.admin-wallet-api-bar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 10px;
  align-items: center;
}

.admin-wallet-api-bar input {
  width: 100%;
  min-height: 42px;
  min-width: 0;
  padding: 0 12px;
  border: 1px solid var(--admin-border);
  border-radius: 8px;
  background: var(--admin-surface);
  color: var(--admin-text);
  font: 800 0.82rem/1 "Space Grotesk", sans-serif;
}

.admin-wallet-api-bar input:focus {
  border-color: color-mix(in srgb, var(--admin-accent) 58%, var(--admin-border));
  outline: none;
}

.admin-wallet-api-output {
  min-height: 320px;
  max-height: min(58vh, 620px);
  margin: 0;
  overflow: auto;
  padding: 16px;
  border: 1px solid var(--admin-border);
  border-radius: 8px;
  background: color-mix(in srgb, var(--admin-surface) 82%, var(--admin-bg));
  color: var(--admin-text);
  font: 700 0.78rem/1.55 ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  white-space: pre-wrap;
}

.admin-order-wallet-cell {
  text-align: center;
}

.admin-order-wallet-symbol {
  display: inline-grid;
  place-items: center;
  width: 32px;
  min-width: 32px;
  height: 28px;
  border: 1px solid var(--admin-border);
  border-radius: 999px;
  color: var(--admin-muted);
  font: 850 0.7rem/1 "Space Grotesk", sans-serif;
}

.admin-order-wallet-symbol.is-released {
  border-color: color-mix(in srgb, var(--admin-text) 40%, transparent);
  background: var(--admin-text);
  color: var(--admin-bg);
}

.admin-order-payment-dot {
  display: inline-block;
  width: 14px;
  height: 14px;
  padding: 0;
  border: 2px solid color-mix(in srgb, currentColor 32%, var(--admin-surface));
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px color-mix(in srgb, currentColor 12%, transparent);
}

button.admin-order-payment-dot {
  cursor: pointer;
  transition: transform 150ms ease, box-shadow 150ms ease;
}

button.admin-order-payment-dot:hover,
button.admin-order-payment-dot:focus-visible {
  transform: scale(1.2);
  box-shadow: 0 0 0 5px color-mix(in srgb, currentColor 18%, transparent);
  outline: none;
}

.admin-order-payment-dot.is-paid { color: #16a34a; }
.admin-order-payment-dot.is-unpaid { color: #dc2626; }
.admin-order-payment-dot.is-canceled { color: #6b7280; }

.admin-orders-payment-audit {
  display: block;
  width: min(620px, 100%);
  margin-top: 5px;
  color: var(--admin-muted);
  font: 750 0.66rem/1.25 "Plus Jakarta Sans", sans-serif;
  letter-spacing: 0.04em;
}

.admin-orders-payment-audit.is-automatic { color: #16a34a; }

.admin-orders-payment-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.admin-orders-payment-filters button {
  min-height: 40px;
  padding: 9px 16px;
  border: 1px solid var(--admin-border);
  border-radius: 999px;
  color: var(--admin-muted);
  background: var(--admin-surface-soft);
  font: 800 12px/1 "Plus Jakarta Sans", sans-serif;
  cursor: pointer;
}

.admin-orders-payment-filters button.is-selected {
  color: var(--admin-bg);
  background: var(--admin-text);
}

.admin-order-payment-dialog form {
  min-width: min(460px, calc(100vw - 40px));
}

.admin-order-payment-methods {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin: 20px 0;
}

.admin-order-payment-methods label {
  position: relative;
  cursor: pointer;
}

.admin-order-payment-methods input {
  position: absolute;
  opacity: 0;
}

.admin-order-payment-methods label > span {
  display: grid;
  gap: 5px;
  padding: 16px;
  border: 1px solid var(--admin-border);
  border-radius: 12px;
  color: var(--admin-text);
  background: var(--admin-surface-soft);
  font-weight: 800;
}

.admin-order-payment-methods small {
  color: var(--admin-muted);
  font-size: 10px;
}

.admin-order-payment-methods input:checked + span {
  border-color: var(--admin-text);
  box-shadow: inset 0 0 0 1px var(--admin-text);
}

.admin-rail-unpaid-dot {
  position: absolute;
  top: 8px;
  right: 8px;
  display: none;
  width: 8px;
  height: 8px;
  border: 2px solid var(--admin-surface);
  border-radius: 50%;
  background: #dc2626;
  box-shadow: 0 0 0 3px rgba(220, 38, 38, .16);
}

.admin-rail-link.has-unpaid-direct-order .admin-rail-unpaid-dot {
  display: block;
}

.admin-menu-trigger.has-critical-dot::after,
.admin-menu-item.has-critical-dot .admin-menu-alert-dot {
  content: "";
  position: absolute;
  display: block;
  width: 9px;
  height: 9px;
  border: 2px solid var(--admin-surface);
  border-radius: 999px;
  background: #dc2626;
  box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.16);
}

.admin-menu-trigger.has-critical-dot::after {
  top: 8px;
  right: 8px;
}

.admin-menu-item {
  position: relative;
}

.admin-menu-alert-dot {
  display: none;
  top: 13px;
  left: 39px;
}

.admin-inventory-recap-view {
  gap: 18px;
  width: 100%;
  max-width: none;
}

.admin-inventory-recap-command {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  min-height: 64px;
  padding: 12px 14px;
  border: 1px solid var(--admin-border);
  border-radius: var(--admin-card-radius);
  background: var(--admin-surface);
  box-shadow: var(--admin-shadow);
}

.admin-inventory-recap-command > div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.admin-inventory-recap-command strong {
  overflow: hidden;
  color: var(--admin-text);
  font: 850 0.9rem/1.15 "Space Grotesk", sans-serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-inventory-recap-refresh svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2;
}

.admin-inventory-recap-refresh.is-loading svg {
  animation: admin-wallet-spin 900ms linear infinite;
}

.admin-inventory-recap-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.admin-inventory-recap-stat {
  display: grid;
  gap: 8px;
  min-width: 0;
  padding: 18px;
  border: 1px solid var(--admin-border);
  border-radius: var(--admin-card-radius);
  background: var(--admin-surface);
  box-shadow: var(--admin-shadow);
}

.admin-inventory-recap-stat span,
.admin-inventory-recap-stat small {
  min-width: 0;
  overflow: hidden;
  color: var(--admin-muted);
  font-size: 0.72rem;
  font-weight: 850;
  letter-spacing: 0;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-inventory-recap-stat strong {
  min-width: 0;
  overflow: hidden;
  color: var(--admin-text);
  font: 800 clamp(1.35rem, 2.4vw, 2.2rem)/1 "Space Grotesk", sans-serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-inventory-recap-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.02fr) minmax(320px, 0.98fr);
  gap: 12px;
}

.admin-inventory-recap-panel {
  gap: 14px;
  min-width: 0;
}

.admin-inventory-recap-risk-list {
  display: grid;
  gap: 10px;
}

.admin-inventory-recap-risk-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px 14px;
  align-items: center;
  min-width: 0;
  padding: 12px;
  border: 1px solid var(--admin-border);
  border-left: 4px solid var(--admin-muted);
  border-radius: 8px;
  background: color-mix(in srgb, var(--admin-surface) 88%, var(--admin-bg));
}

.admin-inventory-recap-risk-card > div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.admin-inventory-recap-risk-card strong,
.admin-inventory-recap-risk-card small {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-inventory-recap-risk-card small {
  color: var(--admin-muted);
  font-size: 0.72rem;
  font-weight: 760;
}

.admin-inventory-recap-risk-card > span {
  display: grid;
  gap: 4px;
  justify-items: end;
  min-width: 130px;
  color: var(--admin-text);
  font: 850 0.84rem/1.1 "Space Grotesk", sans-serif;
  text-align: right;
}

.admin-inventory-recap-risk-card > span small {
  display: block;
  max-width: 190px;
  color: var(--admin-muted);
  font: 760 0.68rem/1.25 "Plus Jakarta Sans", sans-serif;
  white-space: normal;
}

.admin-inventory-recap-risk-card.is-critical,
.admin-inventory-recap-table tr.is-critical {
  border-left-color: #dc2626;
}

.admin-inventory-recap-risk-card.is-high,
.admin-inventory-recap-table tr.is-high {
  border-left-color: #ea580c;
}

.admin-inventory-recap-risk-card.is-medium,
.admin-inventory-recap-table tr.is-medium,
.admin-inventory-recap-risk-card.is-watch,
.admin-inventory-recap-table tr.is-watch {
  border-left-color: #d97706;
}

.admin-inventory-recap-risk-card.is-low,
.admin-inventory-recap-table tr.is-low {
  border-left-color: #65a30d;
}

.admin-inventory-recap-risk-card.is-covered,
.admin-inventory-recap-table tr.is-covered {
  border-left-color: #16a34a;
}

.admin-inventory-recap-play {
  display: grid;
  gap: 5px;
  min-width: 220px;
}

.admin-inventory-recap-play-track {
  position: relative;
  height: 8px;
  overflow: hidden;
  border-radius: 999px;
  background: color-mix(in srgb, var(--admin-muted) 18%, var(--admin-bg));
}

.admin-inventory-recap-play-track i,
.admin-inventory-recap-play-track b {
  position: absolute;
  inset: 0 auto 0 0;
  display: block;
}

.admin-inventory-recap-play-track i {
  width: var(--inventory-min);
  background: color-mix(in srgb, #16a34a 82%, var(--admin-surface));
}

.admin-inventory-recap-play-track b {
  left: var(--inventory-min);
  width: var(--inventory-buffer);
  background: color-mix(in srgb, #d97706 80%, var(--admin-surface));
}

.admin-inventory-recap-play small {
  overflow: hidden;
  color: var(--admin-muted);
  font-size: 0.68rem;
  font-weight: 820;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: normal;
}

.admin-inventory-recap-draft {
  min-height: 280px;
  max-height: min(52vh, 520px);
  margin: 0;
  overflow: auto;
  padding: 14px;
  border: 1px solid var(--admin-border);
  border-radius: 8px;
  background: color-mix(in srgb, var(--admin-surface) 84%, var(--admin-bg));
  color: var(--admin-text);
  font: 720 0.78rem/1.55 ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  white-space: pre-wrap;
}

.admin-inventory-recap-table-panel {
  gap: 16px;
}

.admin-inventory-recap-table {
  min-width: 1120px;
}

.admin-inventory-recap-table tr {
  border-left: 4px solid transparent;
}

.admin-inventory-recap-table th,
.admin-inventory-recap-table td {
  white-space: nowrap;
}

.admin-inventory-recap-risk {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 10px;
  border: 1px solid var(--admin-border);
  border-radius: 999px;
  color: var(--admin-text);
  font: 850 0.68rem/1 "Space Grotesk", sans-serif;
}

.admin-inventory-recap-risk.is-critical {
  border-color: rgba(220, 38, 38, 0.34);
  background: rgba(220, 38, 38, 0.12);
  color: #fca5a5;
}

.admin-inventory-recap-risk.is-high {
  border-color: rgba(234, 88, 12, 0.34);
  background: rgba(234, 88, 12, 0.12);
  color: #fdba74;
}

.admin-inventory-recap-risk.is-medium,
.admin-inventory-recap-risk.is-watch {
  border-color: rgba(217, 119, 6, 0.34);
  background: rgba(217, 119, 6, 0.12);
  color: #fcd34d;
}

.admin-inventory-recap-risk.is-low,
.admin-inventory-recap-risk.is-covered {
  border-color: rgba(22, 163, 74, 0.34);
  background: rgba(22, 163, 74, 0.12);
  color: #86efac;
}

:root[data-admin-theme='light'] .admin-inventory-recap-command,
:root[data-admin-theme='light'] .admin-inventory-recap-stat {
  border-color: rgba(15, 23, 42, 0.1);
  background: #ffffff;
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.05);
}

:root[data-admin-theme='light'] .admin-inventory-recap-risk.is-critical {
  color: #b91c1c;
}

:root[data-admin-theme='light'] .admin-inventory-recap-risk.is-high {
  color: #c2410c;
}

:root[data-admin-theme='light'] .admin-inventory-recap-risk.is-medium,
:root[data-admin-theme='light'] .admin-inventory-recap-risk.is-watch {
  color: #a16207;
}

:root[data-admin-theme='light'] .admin-inventory-recap-risk.is-low,
:root[data-admin-theme='light'] .admin-inventory-recap-risk.is-covered {
  color: #15803d;
}

/* Inventory coverage and editable purchase plan */
.admin-inventory-recap-view,
.admin-purchase-order-view {
  --inventory-red: #ef4444;
  --inventory-amber: #d97706;
  --inventory-green: #22a55b;
  --inventory-line: color-mix(in srgb, var(--admin-text) 13%, transparent);
  gap: 0;
  padding-bottom: 36px;
}

.admin-inventory-recap-controls,
.admin-purchase-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 0 0 18px;
  border-bottom: 1px solid var(--inventory-line);
}

.admin-inventory-filters {
  display: flex;
  min-width: 0;
  overflow-x: auto;
  border: 1px solid var(--inventory-line);
  border-radius: 7px;
}

.admin-inventory-filters button {
  min-height: 40px;
  padding: 0 14px;
  border: 0;
  border-right: 1px solid var(--inventory-line);
  border-radius: 0;
  background: transparent;
  color: var(--admin-muted);
  font: 760 0.72rem/1.2 "Plus Jakarta Sans", sans-serif;
  white-space: nowrap;
  cursor: pointer;
}

.admin-inventory-filters button:last-child {
  border-right: 0;
}

.admin-inventory-filters button.is-active {
  background: var(--admin-text);
  color: var(--admin-bg);
}

.admin-inventory-filter-alert {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-left: 5px;
  border-radius: 50%;
  background: var(--inventory-red);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--inventory-red) 22%, transparent);
  vertical-align: 1px;
}

.admin-inventory-filter-alert[hidden] {
  display: none;
}

.admin-inventory-recap-brief,
.admin-purchase-ledger-meta {
  display: flex;
  align-items: center;
  gap: 18px;
  min-width: 0;
  color: var(--admin-muted);
  font-size: 0.72rem;
  font-weight: 700;
}

.admin-purchase-mode-picker {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  padding: 16px 0;
  border-bottom: 1px solid var(--inventory-line);
}

.admin-purchase-mode-picker button {
  display: grid;
  gap: 5px;
  min-height: 70px;
  padding: 13px 15px;
  border: 1px solid var(--inventory-line);
  border-radius: 8px;
  background: transparent;
  color: var(--admin-text);
  text-align: left;
  cursor: pointer;
}

.admin-purchase-mode-picker button.is-active {
  border-color: var(--admin-text);
  background: color-mix(in srgb, var(--admin-text) 7%, transparent);
  box-shadow: inset 3px 0 0 var(--admin-text);
}

.admin-purchase-mode-picker strong {
  font: 780 0.78rem/1.2 "Plus Jakarta Sans", sans-serif;
}

.admin-purchase-mode-picker span {
  color: var(--admin-muted);
  font: 650 0.66rem/1.35 "Plus Jakarta Sans", sans-serif;
}

.admin-overflow-product-adder {
  position: relative;
  display: grid;
  grid-template-columns: minmax(260px, 0.75fr) minmax(280px, 1fr);
  gap: 18px 28px;
  align-items: end;
  padding: 18px;
  border: 1px solid var(--inventory-line);
  border-radius: 9px;
  background: color-mix(in srgb, var(--admin-text) 3%, transparent);
  margin: 14px 0 4px;
}

.admin-overflow-product-adder[hidden] {
  display: none;
}

.admin-overflow-product-adder > div:first-child {
  display: grid;
  gap: 6px;
}

.admin-overflow-product-adder > div:first-child > strong {
  color: var(--admin-text);
  font: 780 0.92rem/1.25 "Plus Jakarta Sans", sans-serif;
}

.admin-overflow-product-adder p {
  margin: 0;
  color: var(--admin-muted);
  font: 650 0.68rem/1.5 "Plus Jakarta Sans", sans-serif;
}

.admin-overflow-product-search {
  display: grid;
  gap: 6px;
  color: var(--admin-muted);
  font-size: 0.64rem;
  font-weight: 720;
}

.admin-overflow-product-search input {
  width: 100%;
  min-height: 44px;
  padding: 0 12px;
  border: 1px solid var(--inventory-line);
  border-radius: 7px;
  outline: 0;
  background: var(--admin-bg);
  color: var(--admin-text);
  font: 720 0.78rem/1.2 "Plus Jakarta Sans", sans-serif;
}

.admin-overflow-product-search input:focus {
  border-color: var(--admin-text);
}

.admin-overflow-product-results {
  display: grid;
  grid-column: 2;
  gap: 6px;
  max-height: 238px;
  overflow-y: auto;
}

.admin-overflow-product-result {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 4px 12px;
  align-items: center;
  min-height: 52px;
  padding: 8px 10px;
  border: 1px solid var(--inventory-line);
  border-radius: 7px;
  background: var(--admin-bg);
  color: var(--admin-text);
}

.admin-overflow-product-result strong {
  overflow: hidden;
  font: 740 0.72rem/1.25 "Plus Jakarta Sans", sans-serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-overflow-product-result span {
  grid-column: 1;
  color: var(--admin-muted);
  font: 650 0.62rem/1.25 "Plus Jakarta Sans", sans-serif;
}

.admin-overflow-product-result button {
  grid-column: 2;
  grid-row: 1 / span 2;
  min-height: 34px;
  padding: 0 12px;
  border: 1px solid var(--admin-text);
  border-radius: 6px;
  background: var(--admin-text);
  color: var(--admin-bg);
  font: 760 0.67rem/1 "Plus Jakarta Sans", sans-serif;
  cursor: pointer;
}

.admin-overflow-product-result button:disabled {
  opacity: 0.45;
  cursor: default;
}

.admin-inventory-recap-brief > span:first-child {
  max-width: 320px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-inventory-recap-brief strong,
.admin-purchase-ledger-meta strong {
  color: var(--admin-text);
  font: 800 0.88rem/1 "Space Grotesk", sans-serif;
}

.admin-inventory-recap-brief button,
.admin-purchase-actions button {
  min-height: 40px;
  padding: 0 14px;
  border: 1px solid var(--admin-text);
  border-radius: 7px;
  background: var(--admin-text);
  color: var(--admin-bg);
  font: 760 0.74rem/1 "Plus Jakarta Sans", sans-serif;
  cursor: pointer;
}

.admin-inventory-coverage-key {
  display: grid;
  grid-template-columns: auto auto auto 1fr;
  gap: 0;
  align-items: center;
  padding: 16px 0 10px;
  color: var(--admin-muted);
  font-size: 0.68rem;
  font-weight: 700;
}

.admin-inventory-coverage-key > span {
  padding: 0 14px;
  border-right: 1px solid var(--inventory-line);
}

.admin-inventory-coverage-key > span:first-child {
  padding-left: 0;
}

.admin-inventory-coverage-key b {
  margin-left: 4px;
  color: var(--admin-text);
}

.admin-inventory-coverage-key .is-critical::before,
.admin-inventory-coverage-key .is-high::before,
.admin-inventory-coverage-key .is-covered::before {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 6px;
  border-radius: 50%;
  background: var(--inventory-red);
  content: "";
}

.admin-inventory-coverage-key .is-high::before {
  background: var(--inventory-amber);
}

.admin-inventory-coverage-key .is-covered::before {
  background: var(--inventory-green);
}

.admin-inventory-coverage-key small {
  justify-self: end;
  color: var(--admin-muted);
  font: inherit;
}

.admin-inventory-visual-list,
.admin-purchase-list {
  display: grid;
  border-top: 1px solid var(--inventory-line);
}

.admin-inventory-coverage-row {
  display: grid;
  grid-template-columns: minmax(220px, 1.2fr) minmax(105px, 0.45fr) minmax(130px, 0.55fr) minmax(260px, 1.35fr) minmax(165px, 0.75fr);
  gap: 20px;
  align-items: center;
  min-height: 92px;
  padding: 14px 0;
  border-bottom: 1px solid var(--inventory-line);
}

.admin-inventory-product,
.admin-inventory-stock-now,
.admin-inventory-days,
.admin-inventory-action {
  display: grid;
  gap: 5px;
  min-width: 0;
}

.admin-inventory-product strong,
.admin-inventory-action strong {
  overflow: hidden;
  color: var(--admin-text);
  font: 750 0.84rem/1.25 "Plus Jakarta Sans", sans-serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-inventory-product span,
.admin-inventory-stock-now span,
.admin-inventory-days span,
.admin-inventory-action span {
  overflow: hidden;
  color: var(--admin-muted);
  font-size: 0.67rem;
  font-weight: 680;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-inventory-stock-now strong,
.admin-inventory-days strong {
  color: var(--admin-text);
  font: 800 1.08rem/1 "Space Grotesk", sans-serif;
}

.admin-inventory-coverage-row.is-critical .admin-inventory-days strong,
.admin-inventory-coverage-row.is-critical .admin-inventory-action strong {
  color: #f87171;
}

.admin-inventory-coverage-row.is-high .admin-inventory-days strong,
.admin-inventory-coverage-row.is-high .admin-inventory-action strong {
  color: #f3a93b;
}

.admin-inventory-coverage-row.is-covered .admin-inventory-action strong {
  color: #4ade80;
}

.admin-inventory-coverage-rail {
  display: grid;
  gap: 7px;
  min-width: 0;
}

.admin-inventory-coverage-rail > div {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr 4fr;
  gap: 3px;
  height: 10px;
}

.admin-inventory-coverage-rail i,
.admin-inventory-coverage-rail b,
.admin-inventory-coverage-rail em {
  display: block;
  min-width: 0;
  background: color-mix(in srgb, var(--inventory-red) 72%, var(--admin-bg));
}

.admin-inventory-coverage-rail b {
  background: color-mix(in srgb, var(--inventory-amber) 72%, var(--admin-bg));
}

.admin-inventory-coverage-rail em {
  background: color-mix(in srgb, var(--inventory-green) 62%, var(--admin-bg));
}

.admin-inventory-coverage-rail mark {
  position: absolute;
  top: -5px;
  bottom: -5px;
  left: var(--coverage-position);
  width: 2px;
  border: 0;
  background: var(--admin-text);
  transform: translateX(-1px);
}

.admin-inventory-coverage-rail mark::after {
  position: absolute;
  top: -2px;
  left: 50%;
  width: 7px;
  height: 7px;
  border: 2px solid var(--admin-bg);
  border-radius: 50%;
  background: var(--admin-text);
  content: "";
  transform: translate(-50%, -50%);
}

.admin-inventory-coverage-rail > span {
  display: grid;
  grid-template-columns: 1fr 1fr 2fr 2fr;
  color: var(--admin-muted);
}

.admin-inventory-coverage-rail small {
  font-size: 0.6rem;
  font-weight: 700;
}

.admin-inventory-coverage-rail small:last-child {
  text-align: right;
}

.admin-purchase-toolbar > div:first-child {
  display: grid;
  gap: 5px;
}

.admin-purchase-back {
  margin-bottom: 7px;
}

.admin-purchase-toolbar > div:first-child strong {
  color: var(--admin-text);
  font: 800 1.25rem/1.15 "Space Grotesk", sans-serif;
}

.admin-purchase-toolbar > div:first-child span {
  color: var(--admin-muted);
  font-size: 0.72rem;
  font-weight: 680;
}

.admin-purchase-actions {
  display: flex;
  gap: 8px;
}

.admin-purchase-actions button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.admin-purchase-actions [data-purchase-plan-copy] {
  border-color: var(--inventory-line);
  background: transparent;
  color: var(--admin-text);
}

.admin-purchase-selection-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 0 10px;
  border-bottom: 1px solid var(--inventory-line);
}

.admin-purchase-selection-bar[hidden],
.admin-purchase-rule[hidden] {
  display: none;
}

.admin-purchase-selection-bar button {
  min-height: 36px;
  padding: 0 13px;
  border: 1px solid var(--admin-text);
  border-radius: 6px;
  background: var(--admin-text);
  color: var(--admin-bg);
  font: 760 0.7rem/1 "Plus Jakarta Sans", sans-serif;
  cursor: pointer;
}

.admin-purchase-selection-bar button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.admin-purchase-selection-bar span {
  color: var(--admin-muted);
  font-size: 0.66rem;
  font-weight: 680;
}

.admin-purchase-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.admin-purchase-actions svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.8;
}

.admin-purchase-ledger-meta {
  justify-content: flex-end;
  padding: 14px 0;
  border-bottom: 1px solid var(--inventory-line);
}

.admin-purchase-ledger-meta span {
  padding-left: 18px;
  border-left: 1px solid var(--inventory-line);
}

.admin-purchase-ledger-meta .is-short {
  color: #f87171;
}

.admin-purchase-row {
  display: grid;
  grid-template-columns: 36px minmax(220px, 1.4fr) minmax(150px, 0.6fr) minmax(130px, 0.5fr) minmax(170px, 0.7fr);
  gap: 18px;
  align-items: center;
  min-height: 104px;
  padding: 16px 0;
  border-bottom: 1px solid var(--inventory-line);
}

.admin-purchase-row.is-selected {
  background: color-mix(in srgb, var(--admin-text) 3%, transparent);
}

.admin-purchase-index {
  color: var(--admin-muted);
  font: 750 0.7rem/1 "Space Grotesk", sans-serif;
}

.admin-purchase-product,
.admin-purchase-cost {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.admin-purchase-product strong,
.admin-purchase-cost strong {
  overflow: hidden;
  color: var(--admin-text);
  font: 760 0.84rem/1.25 "Plus Jakarta Sans", sans-serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-purchase-product span,
.admin-purchase-cost span {
  overflow: hidden;
  color: var(--admin-muted);
  font-size: 0.67rem;
  font-weight: 680;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-purchase-row.is-critical .admin-purchase-product span {
  color: #f87171;
}

.admin-purchase-row.is-high .admin-purchase-product span {
  color: #f3a93b;
}

.admin-purchase-quantity,
.admin-purchase-line-note,
.admin-purchase-order-note {
  display: grid;
  gap: 6px;
  min-width: 0;
  color: var(--admin-muted);
  font-size: 0.64rem;
  font-weight: 720;
}

.admin-purchase-quantity {
  grid-template-columns: minmax(70px, 100px) 1fr;
}

.admin-purchase-quantity > span {
  grid-column: 1 / -1;
}

.admin-purchase-quantity input,
.admin-purchase-line-note input,
.admin-purchase-order-note textarea {
  width: 100%;
  min-height: 40px;
  padding: 0 11px;
  border: 1px solid var(--inventory-line);
  border-radius: 6px;
  outline: 0;
  background: transparent;
  color: var(--admin-text);
  font: 720 0.78rem/1.2 "Plus Jakarta Sans", sans-serif;
}

.admin-purchase-quantity input:focus,
.admin-purchase-line-note input:focus,
.admin-purchase-order-note textarea:focus {
  border-color: var(--admin-text);
}

.admin-purchase-quantity small {
  align-self: center;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-purchase-select {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 40px;
  cursor: pointer;
}

.admin-purchase-select input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.admin-purchase-select span {
  position: relative;
  display: block;
  width: 20px;
  height: 20px;
  border: 1px solid var(--inventory-line);
  border-radius: 4px;
  background: transparent;
}

.admin-purchase-select input:checked + span {
  border-color: var(--admin-text);
  background: var(--admin-text);
}

.admin-purchase-select input:checked + span::after {
  position: absolute;
  top: 3px;
  left: 6px;
  width: 5px;
  height: 9px;
  border: solid var(--admin-bg);
  border-width: 0 2px 2px 0;
  content: '';
  transform: rotate(45deg);
}

.admin-purchase-select input:focus-visible + span {
  outline: 2px solid var(--admin-text);
  outline-offset: 3px;
}

.admin-purchase-remove {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border: 1px solid var(--inventory-line);
  border-radius: 50%;
  background: transparent;
  color: var(--admin-muted);
  font: 500 1.1rem/1 sans-serif;
  cursor: pointer;
}

.admin-purchase-remove:hover,
.admin-purchase-remove:focus-visible {
  border-color: #ef4444;
  color: #ef4444;
}

.admin-purchase-order-note {
  margin-top: 18px;
}

.admin-purchase-order-note textarea {
  min-height: 84px;
  padding: 11px;
  resize: vertical;
}

.admin-purchase-total {
  display: flex;
  align-items: baseline;
  justify-content: flex-end;
  gap: 24px;
  padding-top: 20px;
  color: var(--admin-muted);
  font-size: 0.72rem;
  font-weight: 700;
}

.admin-purchase-total strong {
  color: var(--admin-text);
  font: 800 clamp(1.45rem, 2.8vw, 2.2rem)/1 "Space Grotesk", sans-serif;
}

:root[data-admin-theme='light'] .admin-inventory-recap-view,
:root[data-admin-theme='light'] .admin-purchase-order-view {
  --inventory-red: #dc2626;
  --inventory-amber: #b45309;
  --inventory-green: #15803d;
}

:root[data-admin-theme='light'] .admin-inventory-coverage-row.is-critical .admin-inventory-days strong,
:root[data-admin-theme='light'] .admin-inventory-coverage-row.is-critical .admin-inventory-action strong,
:root[data-admin-theme='light'] .admin-purchase-row.is-critical .admin-purchase-product span {
  color: #b91c1c;
}

:root[data-admin-theme='light'] .admin-inventory-coverage-row.is-high .admin-inventory-days strong,
:root[data-admin-theme='light'] .admin-inventory-coverage-row.is-high .admin-inventory-action strong,
:root[data-admin-theme='light'] .admin-purchase-row.is-high .admin-purchase-product span {
  color: #a16207;
}

:root[data-admin-theme='light'] .admin-inventory-coverage-row.is-covered .admin-inventory-action strong {
  color: #15803d;
}

@media (max-width: 1180px) {
  .admin-inventory-recap-controls {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-inventory-recap-brief {
    justify-content: space-between;
  }

  .admin-inventory-coverage-row {
    grid-template-columns: minmax(210px, 1fr) 110px 130px minmax(230px, 1.2fr);
  }

  .admin-inventory-action {
    grid-column: 1 / -1;
    grid-template-columns: auto 1fr;
  }

  .admin-purchase-row {
    grid-template-columns: 32px minmax(210px, 1fr) minmax(140px, 0.6fr) minmax(130px, 0.5fr);
  }

  .admin-purchase-line-note {
    grid-column: 2 / -1;
  }
}

@media (max-width: 760px) {
  .admin-inventory-recap-brief {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .admin-inventory-recap-brief > span:first-child {
    flex-basis: 100%;
    max-width: none;
  }

  .admin-inventory-coverage-key {
    grid-template-columns: 1fr;
    gap: 8px;
  }

  .admin-inventory-coverage-key > span {
    padding: 0;
    border: 0;
  }

  .admin-inventory-coverage-key small {
    justify-self: start;
  }

  .admin-inventory-coverage-row {
    grid-template-columns: 1fr 1fr;
    gap: 14px;
    padding: 18px 0;
  }

  .admin-inventory-product,
  .admin-inventory-coverage-rail,
  .admin-inventory-action {
    grid-column: 1 / -1;
  }

  .admin-purchase-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-purchase-actions button {
    flex: 1;
    justify-content: center;
  }

  .admin-purchase-mode-picker,
  .admin-overflow-product-adder {
    grid-template-columns: 1fr;
  }

  .admin-overflow-product-results {
    grid-column: 1;
  }

  .admin-purchase-ledger-meta {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }

  .admin-purchase-ledger-meta span {
    padding: 0;
    border: 0;
  }

  .admin-purchase-row {
    grid-template-columns: 28px 1fr;
    gap: 12px;
  }

  .admin-purchase-quantity,
  .admin-purchase-cost,
  .admin-purchase-line-note {
    grid-column: 2;
  }

  .admin-purchase-total {
    justify-content: space-between;
  }
}

/* Quantity-trigger inventory model */
.admin-inventory-trigger-hero {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 28px;
  padding: 4px 0 24px;
