.admin-inventory-product-search select,
.admin-inventory-product-search-filter input,
.admin-inventory-product-search-volume input {
  padding-top: 10px;
}

.admin-inventory-product-search select {
  padding-right: 26px;
  padding-left: 9px;
}

.admin-inventory-trigger-row {
  display: grid;
  grid-template-columns: minmax(210px, 0.9fr) minmax(255px, 0.85fr) minmax(260px, 1.15fr) minmax(285px, 1.2fr);
  gap: 22px;
  align-items: center;
  min-height: 170px;
  padding: 20px 0 20px 15px;
  border-bottom: 1px solid var(--inventory-line);
  border-left: 3px solid transparent;
}

.admin-inventory-trigger-row.is-urgent {
  border-left-color: var(--inventory-red);
}

.admin-inventory-trigger-row.is-triggered,
.admin-inventory-trigger-row.is-near {
  border-left-color: var(--inventory-amber);
}

.admin-inventory-trigger-row.is-healthy {
  border-left-color: var(--inventory-green);
}

.admin-inventory-trigger-row.is-initial {
  border-left-color: #8b5cf6;
}

.admin-inventory-trigger-product,
.admin-inventory-trigger-balance,
.admin-inventory-trigger-signal {
  display: grid;
  gap: 7px;
  min-width: 0;
}

.admin-inventory-trigger-product strong {
  overflow: hidden;
  color: var(--admin-text);
  font: 760 0.88rem/1.3 "Plus Jakarta Sans", sans-serif;
  text-overflow: ellipsis;
}

.admin-inventory-trigger-product small,
.admin-inventory-trigger-balance small,
.admin-inventory-trigger-signal small,
.admin-inventory-trigger-settings > small,
.admin-purchase-product small {
  color: var(--admin-muted);
  font-size: 0.63rem;
  font-weight: 680;
  line-height: 1.4;
}

.admin-inventory-incoming-qty {
  width: max-content;
  color: #60a5fa;
  font-size: 0.63rem;
  font-weight: 800;
}

:root[data-admin-theme='light'] .admin-inventory-incoming-qty {
  color: #2563eb;
}

.admin-inventory-trigger-state {
  width: max-content;
  padding: 4px 7px;
  border: 1px solid var(--inventory-line);
  border-radius: 999px;
  color: var(--admin-muted);
  font-size: 0.59rem;
  font-weight: 800;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.is-urgent .admin-inventory-trigger-state {
  border-color: color-mix(in srgb, var(--inventory-red) 45%, transparent);
  color: #f87171;
}

.is-triggered .admin-inventory-trigger-state,
.is-near .admin-inventory-trigger-state {
  border-color: color-mix(in srgb, var(--inventory-amber) 45%, transparent);
  color: #f3a93b;
}

.is-initial .admin-inventory-trigger-state {
  border-color: color-mix(in srgb, #8b5cf6 48%, transparent);
  color: #a78bfa;
}

.admin-inventory-trigger-balance {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.admin-inventory-trigger-balance > div:not(.admin-inventory-trigger-meter) {
  display: grid;
  gap: 5px;
}

.admin-inventory-trigger-balance span {
  color: var(--admin-muted);
  font-size: 0.62rem;
  font-weight: 700;
}

.admin-inventory-trigger-balance strong {
  color: var(--admin-text);
  font: 800 1.35rem/1 "Space Grotesk", sans-serif;
}

.admin-inventory-commitment-details {
  position: relative;
  width: max-content;
}

.admin-inventory-commitment-details summary {
  display: flex;
  align-items: center;
  gap: 4px;
  width: max-content;
  cursor: pointer;
  list-style: none;
}

.admin-inventory-commitment-details summary::-webkit-details-marker {
  display: none;
}

.admin-inventory-commitment-details summary strong {
  text-decoration: underline dotted color-mix(in srgb, currentColor 55%, transparent);
  text-underline-offset: 4px;
}

.admin-inventory-commitment-details summary::after {
  color: currentColor;
  content: "›";
  font-size: 0.85rem;
  font-weight: 850;
  transform: rotate(90deg);
  transition: transform 140ms ease;
}

.admin-inventory-commitment-details[open] summary::after {
  transform: rotate(-90deg);
}

.admin-inventory-commitment-details summary:focus-visible {
  border-radius: 3px;
  outline: 2px solid color-mix(in srgb, currentColor 45%, transparent);
  outline-offset: 3px;
}

.admin-inventory-commitment-panel {
  position: absolute;
  z-index: 40;
  top: calc(100% + 9px);
  left: 0;
  width: min(300px, 78vw);
  padding: 12px;
  border: 1px solid var(--inventory-line);
  border-radius: 8px;
  background: var(--admin-bg);
  box-shadow: 0 16px 38px rgb(0 0 0 / 36%);
}

.admin-inventory-commitment-panel header {
  display: grid;
  gap: 3px;
  padding-bottom: 9px;
  border-bottom: 1px solid var(--inventory-line);
}

.admin-inventory-commitment-panel header > b {
  color: var(--admin-text);
  font-size: 0.69rem;
}

.admin-inventory-commitment-panel ul {
  display: grid;
  max-height: 220px;
  margin: 0;
  padding: 5px 0 0;
  overflow: auto;
  list-style: none;
}

.admin-inventory-commitment-panel li {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  padding: 7px 2px;
  border-bottom: 1px solid color-mix(in srgb, var(--inventory-line) 70%, transparent);
}

.admin-inventory-commitment-panel li:last-child {
  border-bottom: 0;
}

.admin-inventory-trigger-balance .admin-inventory-commitment-panel li > a {
  display: inline-flex;
  gap: 5px;
  align-items: baseline;
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--admin-text);
  font: 720 0.66rem/1.35 "Plus Jakarta Sans", sans-serif;
  text-decoration: none;
}

.admin-inventory-trigger-balance .admin-inventory-commitment-panel li > a:hover span,
.admin-inventory-trigger-balance .admin-inventory-commitment-panel li > a:focus-visible span {
  color: var(--admin-accent, #735cff);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.admin-inventory-trigger-balance .admin-inventory-commitment-panel li > a i {
  flex: 0 0 auto;
  color: var(--admin-muted);
  font-style: normal;
}

.admin-inventory-commitment-panel li > b {
  flex: 0 0 auto;
  color: var(--admin-muted);
  font-size: 0.64rem;
}

:root[data-admin-theme='light'] .admin-inventory-commitment-panel {
  background: #ffffff;
  box-shadow: 0 16px 38px rgb(15 23 42 / 18%);
}

.admin-inventory-trigger-meter {
  position: relative;
  grid-column: 1 / -1;
  height: 7px;
  margin-top: 5px;
  background: color-mix(in srgb, var(--admin-text) 10%, transparent);
}

.admin-inventory-trigger-meter i {
  display: block;
  height: 100%;
  background: var(--inventory-green);
}

.is-urgent .admin-inventory-trigger-meter i {
  background: var(--inventory-red);
}

.is-triggered .admin-inventory-trigger-meter i,
.is-near .admin-inventory-trigger-meter i {
  background: var(--inventory-amber);
}

.is-urgent .admin-inventory-predicted-stock strong {
  color: #f87171;
}

.is-triggered .admin-inventory-predicted-stock strong,
.is-near .admin-inventory-predicted-stock strong {
  color: #f3a93b;
}

.admin-inventory-trigger-meter mark {
  position: absolute;
  top: -4px;
  bottom: -4px;
  width: 2px;
  border: 0;
  background: var(--admin-text);
  transform: translateX(-2px);
}

.admin-inventory-bucket-chart {
  display: grid;
  grid-template-columns: repeat(var(--bucket-count, 9), 1fr);
  gap: 3px;
  align-items: end;
  height: 45px;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--inventory-line);
}

.admin-inventory-bucket-chart i {
  display: block;
  height: var(--bucket-height);
  min-height: 3px;
  background: color-mix(in srgb, var(--admin-text) 55%, transparent);
}

.admin-inventory-bucket-chart i:nth-last-child(-n+3) {
  background: var(--admin-text);
}

.admin-inventory-signal-metrics {
  display: flex;
  flex-wrap: wrap;
  gap: 5px 13px;
}

.admin-inventory-signal-metrics span {
  color: var(--admin-muted);
  font-size: 0.61rem;
  font-weight: 680;
}

.admin-inventory-signal-metrics b {
  color: var(--admin-text);
}

.admin-inventory-trigger-settings {
  display: grid;
  grid-template-columns: minmax(115px, 1.2fr) minmax(86px, 0.8fr) minmax(65px, 0.55fr) auto;
  gap: 8px;
  align-items: end;
  min-width: 0;
  padding: 13px;
  border: 1px solid var(--inventory-line);
  border-radius: 8px;
  background: color-mix(in srgb, var(--admin-text) 3%, transparent);
}

.admin-inventory-trigger-settings label:not(.admin-inventory-auto-switch) {
  display: grid;
  gap: 5px;
  min-width: 0;
}

.admin-inventory-trigger-settings label > span,
.admin-inventory-auto-switch b {
  color: var(--admin-muted);
  font-size: 0.59rem;
  font-weight: 750;
}

.admin-inventory-trigger-settings input[type="number"] {
  width: 100%;
  min-height: 36px;
  padding: 0 8px;
  border: 1px solid var(--inventory-line);
  border-radius: 5px;
  outline: 0;
  background: var(--admin-bg);
  color: var(--admin-text);
  font: 740 0.72rem/1 "Plus Jakarta Sans", sans-serif;
}

.admin-inventory-trigger-settings input:focus {
  border-color: var(--admin-text);
}

.admin-inventory-trigger-settings input:disabled {
  opacity: 0.4;
}

.admin-inventory-trigger-settings button {
  min-height: 36px;
  padding: 0 11px;
  border: 1px solid var(--admin-text);
  border-radius: 5px;
  background: var(--admin-text);
  color: var(--admin-bg);
  font: 760 0.65rem/1 "Plus Jakarta Sans", sans-serif;
  cursor: pointer;
}

.admin-inventory-trigger-settings button:disabled {
  cursor: wait;
  opacity: 0.5;
}

.admin-inventory-setting-status {
  grid-column: 1 / -1;
}

.admin-inventory-setting-status > small {
  color: var(--admin-muted);
  font-size: 0.63rem;
  font-weight: 680;
  line-height: 1.4;
}

.admin-inventory-setting-status > small.is-error {
  color: #f87171;
}

.admin-inventory-trigger-why {
  position: relative;
  display: inline-block;
  margin-left: 6px;
}

.admin-inventory-trigger-why summary {
  color: var(--admin-muted);
  font-size: 0.61rem;
  font-weight: 760;
  text-decoration: underline;
  text-underline-offset: 2px;
  cursor: pointer;
  list-style: none;
}

.admin-inventory-trigger-why summary::-webkit-details-marker {
  display: none;
}

.admin-inventory-trigger-why > div {
  position: absolute;
  z-index: 20;
  right: 0;
  bottom: calc(100% + 8px);
  display: grid;
  gap: 6px;
  width: min(310px, 76vw);
  padding: 11px;
  border: 1px solid var(--inventory-line);
  border-radius: 7px;
  background: var(--admin-bg);
  box-shadow: 0 14px 32px rgb(0 0 0 / 34%);
}

.admin-inventory-trigger-why > div span {
  color: var(--admin-muted);
  font-size: 0.61rem;
  line-height: 1.35;
}

.admin-inventory-trigger-why > div b {
  color: var(--admin-text);
}

.admin-inventory-auto-switch {
  display: grid;
  grid-template-columns: 32px 1fr;
  gap: 4px 8px;
  align-items: center;
  align-self: center;
  cursor: pointer;
}

.admin-inventory-auto-switch input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.admin-inventory-auto-switch > span {
  position: relative;
  width: 32px;
  height: 18px;
  border: 1px solid var(--inventory-line);
  border-radius: 999px;
  background: color-mix(in srgb, var(--admin-text) 10%, transparent);
}

.admin-inventory-auto-switch > span::after {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--admin-muted);
  content: "";
  transition: transform 140ms ease;
}

.admin-inventory-auto-switch input:checked + span {
  border-color: var(--inventory-green);
  background: color-mix(in srgb, var(--inventory-green) 22%, transparent);
}

.admin-inventory-auto-switch input:checked + span::after {
  background: #4ade80;
  transform: translateX(14px);
}

.admin-purchase-rule {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 16px;
  align-items: center;
  padding: 13px 0;
  border-bottom: 1px solid var(--inventory-line);
  color: var(--admin-muted);
  font-size: 0.68rem;
  font-weight: 680;
}

.admin-purchase-rule strong {
  color: var(--admin-text);
}

.admin-purchase-rule code {
  padding: 6px 8px;
  border: 1px solid var(--inventory-line);
  border-radius: 5px;
  color: var(--admin-text);
  font: 700 0.66rem/1.2 "Space Grotesk", monospace;
}

.admin-purchase-product small {
  display: block;
}

.admin-purchase-row.is-urgent .admin-purchase-product span {
  color: #f87171;
}

.admin-purchase-row.is-triggered .admin-purchase-product span {
  color: #f3a93b;
}

:root[data-admin-theme='light'] .admin-inventory-trigger-settings {
  background: #f8fafc;
}

:root[data-admin-theme='light'] .is-urgent .admin-inventory-trigger-state,
:root[data-admin-theme='light'] .admin-purchase-row.is-urgent .admin-purchase-product span,
:root[data-admin-theme='light'] .is-urgent .admin-inventory-predicted-stock strong {
  color: #b91c1c;
}

:root[data-admin-theme='light'] .is-triggered .admin-inventory-trigger-state,
:root[data-admin-theme='light'] .admin-purchase-row.is-triggered .admin-purchase-product span,
:root[data-admin-theme='light'] .is-triggered .admin-inventory-predicted-stock strong,
:root[data-admin-theme='light'] .is-near .admin-inventory-predicted-stock strong {
  color: #b45309;
}

@media (max-width: 1240px) {
  .admin-inventory-trigger-row {
    grid-template-columns: minmax(210px, 0.8fr) minmax(255px, 0.85fr) minmax(250px, 1fr);
  }

  .admin-inventory-trigger-settings {
    grid-column: 1 / -1;
  }
}

@media (max-width: 820px) {
  .admin-inventory-trigger-hero {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-inventory-global-actions {
    align-items: stretch;
    width: 100%;
  }

  .admin-inventory-global-actions button {
    flex: 1;
    justify-content: center;
  }

  .admin-inventory-utility-bar {
    justify-content: space-between;
  }

  .admin-inventory-recap-controls {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-inventory-product-search {
    grid-template-columns: minmax(220px, 1fr) repeat(3, minmax(95px, 1fr)) 92px;
    width: 100%;
  }

  .admin-inventory-global-days {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .admin-inventory-trigger-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .admin-inventory-trigger-summary > div,
  .admin-inventory-trigger-summary > div:first-child,
  .admin-inventory-trigger-summary > div:last-child {
    min-height: 100px;
    padding: 16px 12px;
    border-right: 1px solid var(--inventory-line);
  }

  .admin-inventory-trigger-summary > div:nth-child(even) {
    border-right: 0;
  }

  .admin-inventory-trigger-row {
    grid-template-columns: 1fr 1fr;
  }

  .admin-inventory-trigger-signal,
  .admin-inventory-trigger-settings {
    grid-column: 1 / -1;
  }

  .admin-purchase-rule {
    grid-template-columns: 1fr;
    gap: 7px;
  }
}

@media (max-width: 560px) {
	.admin-inventory-product-search {
	  grid-template-columns: minmax(0, 1fr) 96px;
	}

	.admin-inventory-product-search-query {
	  grid-column: 1 / -1;
	}

  .admin-inventory-trigger-summary,
  .admin-inventory-trigger-row {
    grid-template-columns: 1fr;
  }

  .admin-inventory-trigger-summary > div {
    border-right: 0;
  }

  .admin-inventory-trigger-signal,
  .admin-inventory-trigger-settings {
    grid-column: auto;
  }

  .admin-inventory-trigger-settings {
    grid-template-columns: 1fr 1fr;
  }

  .admin-inventory-trigger-settings button {
    grid-column: 1 / -1;
  }
}

.admin-inventory-po-board {
  display: grid;
  gap: 14px;
  padding: 20px 0;
  border-bottom: 1px solid var(--inventory-line);
}

.admin-inventory-po-board-head,
.admin-inventory-po-card-head,
.admin-inventory-po-card-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.admin-inventory-po-board-head h3 {
  margin: 5px 0 0;
  color: var(--admin-text);
  font: 800 1.05rem/1.2 "Space Grotesk", sans-serif;
}

.admin-inventory-po-board-tools {
  display: grid;
  justify-items: end;
  gap: 7px;
}

.admin-inventory-po-board-tools > span {
  color: var(--admin-muted);
  font-size: 0.68rem;
  font-weight: 750;
}

.admin-inventory-po-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.admin-inventory-po-toggle {
  grid-column: 1 / -1;
  justify-self: center;
  min-height: 36px;
  padding: 8px 18px;
  border: 1px solid var(--inventory-line);
  border-radius: 999px;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 0.8rem;
  font-weight: 700;
  cursor: pointer;
}

.admin-inventory-po-toggle:hover,
.admin-inventory-po-toggle:focus-visible {
  border-color: currentColor;
}

.admin-inventory-po-card {
  display: grid;
  gap: 10px;
  min-width: 0;
  padding: 14px;
  border: 1px solid var(--inventory-line);
  border-radius: 9px;
  background: color-mix(in srgb, var(--admin-text) 3%, transparent);
}

.admin-inventory-po-card-head > div {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.admin-inventory-po-card-head strong {
  color: var(--admin-text);
  font: 800 0.76rem/1.2 "Space Grotesk", sans-serif;
}

.admin-inventory-po-card-head span,
.admin-inventory-po-card-meta,
.admin-inventory-po-card > small {
  overflow: hidden;
  color: var(--admin-muted);
  font-size: 0.59rem;
  font-weight: 690;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-inventory-po-card-head > b {
  color: var(--admin-text);
  font: 800 1rem/1 "Space Grotesk", sans-serif;
}

.admin-inventory-po-card-head > .admin-inventory-po-card-actions {
  display: flex;
  align-items: center;
  gap: 9px;
}

.admin-inventory-po-card-actions > b {
  color: var(--admin-text);
  font: 800 1rem/1 "Space Grotesk", sans-serif;
}

.admin-inventory-po-card-actions button {
  min-height: 30px;
  padding: 0 9px;
  border: 1px solid color-mix(in srgb, #ef4444 50%, var(--inventory-line));
  border-radius: 6px;
  background: transparent;
  color: #f87171;
  font: 750 0.6rem/1 "Plus Jakarta Sans", sans-serif;
  cursor: pointer;
}

.admin-inventory-po-card-actions button:hover,
.admin-inventory-po-card-actions button:focus-visible {
  border-color: #ef4444;
  color: #ef4444;
}

.admin-inventory-po-card-actions button:disabled {
  cursor: wait;
  opacity: 0.55;
}

.admin-inventory-po-progress {
  height: 6px;
  overflow: hidden;
  border-radius: 999px;
  background: color-mix(in srgb, var(--admin-text) 10%, transparent);
}

.admin-inventory-po-progress i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: #3b82f6;
}

.admin-inventory-po-card.is-received .admin-inventory-po-progress i {
  background: var(--inventory-green);
}

.admin-inventory-po-card-meta {
  align-items: flex-start;
  flex-wrap: wrap;
  justify-content: flex-start;
}

.admin-inventory-po-card-meta b {
  color: var(--admin-text);
}

.admin-inventory-trigger-row.is-incoming,
.admin-inventory-trigger-row.is-partial {
  border-left-color: #3b82f6;
}

.is-incoming .admin-inventory-trigger-state,
.is-partial .admin-inventory-trigger-state {
  border-color: color-mix(in srgb, #3b82f6 48%, transparent);
  color: #60a5fa;
}

.is-incoming .admin-inventory-trigger-meter i,
.is-partial .admin-inventory-trigger-meter i {
  background: #3b82f6;
}

.admin-purchase-actions button.is-primary {
  border-color: #9dff00;
  background: #9dff00;
  color: #0b0d0f;
}

.admin-purchase-success-modal {
  position: fixed;
  inset: 0;
  z-index: 12000;
  display: grid;
  place-items: center;
  padding: 22px;
}

.admin-purchase-success-modal[hidden] {
  display: none;
}

.admin-purchase-success-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.78);
  backdrop-filter: blur(10px);
}

.admin-purchase-success-modal > section {
  position: relative;
  display: grid;
  gap: 13px;
  width: min(480px, 100%);
  padding: 30px;
  border: 1px solid color-mix(in srgb, #9dff00 34%, var(--inventory-line));
  border-radius: 16px;
  background: var(--admin-bg);
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.45);
}

.admin-purchase-success-icon {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: #9dff00;
  color: #0b0d0f;
  font: 900 1.2rem/1 "Space Grotesk", sans-serif;
}

.admin-purchase-success-modal h3,
.admin-purchase-success-modal p {
  margin: 0;
}

.admin-purchase-success-modal h3 {
