  font-size: 1rem;
}

.admin-accounting-metric strong {
  min-width: 0;
  overflow: hidden;
  color: var(--accounting-text);
  font: 800 clamp(1.05rem, 1.45vw, 1.45rem)/1 "Space Grotesk", sans-serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-accounting-metric.is-danger {
  border-color: color-mix(in srgb, var(--accounting-text) 28%, var(--accounting-border));
}

.admin-accounting-workspace,
.admin-accounting-secondary {
