}

.admin-accounting-wallet-destination .admin-accounting-wallet-destination-copy h2 {
  color: var(--accounting-text);
}

.admin-accounting-wallet-destination .admin-accounting-wallet-destination-copy p {
  color: var(--accounting-muted);
}

.admin-accounting-secondary {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.admin-accounting-secondary .admin-accounting-panel-wide {
  grid-column: 1 / -1;
}

.admin-accounting-panel {
  min-width: 0;
  padding: 24px;
}

.admin-accounting-alert-grid,
.admin-accounting-summary-list,
.admin-accounting-insight-list,
.admin-accounting-drawer-body {
  display: grid;
  gap: 10px;
}

.admin-accounting-alert {
