  white-space: nowrap;
}

.admin-accounting-alert span,
.admin-accounting-helper,
.admin-accounting-warning {
  color: var(--accounting-muted);
  font-size: 0.78rem;
  line-height: 1.45;
}

.admin-accounting-helper,
.admin-accounting-warning {
