.admin-accounting-chip-overdue,
.admin-accounting-chip-critical,
.admin-accounting-chip-void,
.admin-accounting-chip-unpaid,
.admin-accounting-chip-warning,
.admin-accounting-chip-missing,
.admin-accounting-chip-paid,
.admin-accounting-chip-posted,
.admin-accounting-chip-clean,
.admin-accounting-chip-attached,
.admin-accounting-chip-partially-paid,
.admin-accounting-chip-info,
.admin-accounting-chip-transfer {
