}

.admin-accounting-bar {
  height: 6px;
  overflow: hidden;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accounting-muted) 18%, transparent);
}

.admin-accounting-bar span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--accounting-text);
}

.admin-accounting-drawer-card {
  width: min(520px, calc(100vw - 24px));
  max-height: calc(100svh - 28px);
