/* Finance surfaces: quiet hierarchy shared by Accounting and P&L. */
.admin-finance-page-head,
:root[data-admin-theme='light'] .admin-finance-page-head,
:root[data-admin-theme='dark'] .admin-finance-page-head {
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  padding: 8px 2px 22px;
  position: static;
  min-height: 0;
  backdrop-filter: none;
}

.admin-finance-page-head .admin-topbar-brand h1 {
  font-size: clamp(2.15rem, 4vw, 3.45rem);
}

.admin-finance-page-head .admin-admin-mark {
  color: var(--admin-muted) !important;
}

.admin-finance-page-head .admin-topbar-brand p {
  max-width: 620px;
  margin-top: 8px;
  font-size: 0.9rem;
  line-height: 1.5;
}

.admin-accounting-topbar.admin-finance-page-head .admin-topbar-actions {
  display: flex;
}

.admin-accounting-command {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
}

.admin-accounting-command .admin-accounting-status,
.admin-accounting-command .admin-accounting-alert-strip {
  grid-column: 1 / -1;
}

.admin-accounting-month-step {
  flex: 0 0 auto;
}

.admin-accounting-mode-picker {
  display: grid;
  grid-template-columns: auto minmax(240px, 380px);
  gap: 12px;
  align-items: center;
  width: fit-content;
  max-width: 100%;
  margin-bottom: 10px;
}

.admin-accounting-mode-picker > span {
  color: var(--accounting-muted);
  font-size: 0.72rem;
  font-weight: 850;
}

.admin-accounting-mode-picker select,
.admin-accounting-edit-form :is(input, select, textarea) {
  width: 100%;
  min-height: 42px;
  border: 1px solid var(--accounting-border);
  border-radius: 8px;
  outline: none;
  background: var(--accounting-surface);
  color: var(--accounting-text);
  padding: 0 12px;
  font: 800 0.82rem/1 "Space Grotesk", sans-serif;
}

.admin-accounting-export-menu {
  position: relative;
}

.admin-accounting-export-menu > summary {
  display: flex;
  align-items: center;
  list-style: none;
  cursor: pointer;
}

.admin-accounting-export-menu > summary::-webkit-details-marker {
  display: none;
}

.admin-accounting-export-menu > div {
  position: absolute;
  z-index: 20;
  top: calc(100% + 8px);
  right: 0;
  display: grid;
  width: 220px;
  padding: 8px;
  border: 1px solid var(--accounting-border);
  border-radius: 10px;
  background: var(--accounting-surface);
  box-shadow: var(--admin-shadow);
}

.admin-accounting-export-menu button {
  padding: 11px 10px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--accounting-text);
  font: 750 0.78rem/1.2 "Plus Jakarta Sans", sans-serif;
  text-align: left;
  cursor: pointer;
}

.admin-accounting-export-menu button:hover {
  background: color-mix(in srgb, var(--accounting-text) 6%, transparent);
}

.admin-accounting-edit-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.admin-accounting-edit-form label {
  display: grid;
  gap: 6px;
}

.admin-accounting-edit-form label span {
  color: var(--accounting-muted);
  font-size: 0.72rem;
  font-weight: 800;
}

.admin-accounting-edit-form textarea {
  min-height: 100px;
  padding-block: 12px;
}

.admin-accounting-edit-form > :is(button, .admin-form-error) {
  grid-column: 1 / -1;
}

.admin-accounting-category-combobox {
  position: relative;
  width: 100%;
  min-width: 0;
}

.admin-accounting-bill-field {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.admin-accounting-bill-field > span {
  color: var(--accounting-muted);
  font-size: 0.72rem;
  font-weight: 800;
}

.admin-accounting-bill-picker {
  position: relative;
  min-width: 0;
}

.admin-accounting-bill-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  min-height: 44px;
  padding: 0 12px;
  border: 1px solid var(--accounting-border);
  border-radius: 8px;
  background: var(--accounting-surface);
  color: var(--accounting-text);
  font: 800 0.82rem/1 "Space Grotesk", sans-serif;
  text-align: left;
  cursor: pointer;
}

.admin-accounting-bill-trigger:focus-visible,
.admin-accounting-bill-trigger[aria-expanded='true'] {
  outline: none;
  border-color: color-mix(in srgb, var(--admin-accent) 58%, var(--accounting-border));
}

.admin-accounting-bill-trigger > b {
  color: var(--accounting-muted);
  transition: transform 140ms ease;
}

.admin-accounting-bill-trigger[aria-expanded='true'] > b {
  transform: rotate(180deg);
}

.admin-accounting-bill-menu {
  position: absolute;
  z-index: 85;
  top: calc(100% + 6px);
  left: 0;
  width: 100%;
  padding: 10px;
  border: 1px solid var(--accounting-border);
  border-radius: 11px;
  background: var(--accounting-surface);
  box-shadow: 0 18px 48px rgb(0 0 0 / 26%);
}

.admin-accounting-bill-menu[hidden] {
  display: none !important;
}

.admin-accounting-bill-menu > p {
  margin: 0 0 8px;
  color: var(--accounting-muted);
  font-size: 0.7rem;
  line-height: 1.45;
}

.admin-accounting-bill-results {
  display: grid;
  gap: 5px;
  max-height: 330px;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.admin-accounting-bill-option {
  padding: 10px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: color-mix(in srgb, var(--accounting-text) 3%, transparent);
}

.admin-accounting-bill-option.is-selected {
  border-color: color-mix(in srgb, var(--admin-accent) 45%, var(--accounting-border));
  background: color-mix(in srgb, var(--admin-accent) 7%, var(--accounting-surface));
}

.admin-accounting-bill-option.is-disabled {
  opacity: 0.46;
}

.admin-accounting-bill-option > label:first-child {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  cursor: pointer;
}

.admin-accounting-bill-option > label:first-child input {
  width: 16px;
  min-height: 16px;
  margin: 0;
  accent-color: var(--admin-accent);
}

.admin-accounting-bill-option > label:first-child > span {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.admin-accounting-bill-option > label:first-child strong,
.admin-accounting-bill-option > label:first-child b {
  color: var(--accounting-text);
  font-size: 0.76rem;
}

.admin-accounting-bill-option > label:first-child small {
  overflow: hidden;
  color: var(--accounting-muted);
  font-size: 0.65rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-accounting-bill-allocation {
  display: grid;
  grid-template-columns: minmax(130px, 1fr) minmax(140px, .55fr) auto;
  align-items: center;
  gap: 8px;
  margin: 9px 0 0 26px;
}

.admin-accounting-bill-allocation > span,
.admin-accounting-bill-allocation > small {
  color: var(--accounting-muted);
  font-size: 0.64rem;
  font-weight: 750;
}

.admin-accounting-bill-allocation > input {
  min-height: 36px;
}

@media (max-width: 680px) {
  .admin-accounting-bill-menu {
    width: calc(100vw - 48px);
    max-width: 100%;
  }

  .admin-accounting-bill-option > label:first-child {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .admin-accounting-bill-option > label:first-child > b {
    grid-column: 2;
  }

  .admin-accounting-bill-allocation {
    grid-template-columns: 1fr;
  }
}

.admin-accounting-category-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  width: 100%;
  min-height: 42px;
  padding: 0 12px;
  border: 1px solid var(--accounting-border);
  border-radius: 8px;
  outline: none;
  background: var(--accounting-surface);
  color: var(--accounting-text);
  font: 800 0.82rem/1 "Space Grotesk", sans-serif;
  text-align: left;
  cursor: pointer;
}

.admin-accounting-category-trigger:focus-visible,
.admin-accounting-category-trigger[aria-expanded='true'] {
  border-color: color-mix(in srgb, var(--admin-accent) 58%, var(--accounting-border));
}

.admin-accounting-category-trigger > span {
  overflow: hidden;
  color: var(--accounting-text) !important;
  font: inherit !important;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-accounting-category-trigger > b {
  flex: 0 0 auto;
  color: var(--accounting-muted);
  font-size: 0.9rem;
  transition: transform 140ms ease;
}

.admin-accounting-category-trigger[aria-expanded='true'] > b {
  transform: rotate(180deg);
}

.admin-accounting-category-menu {
  position: absolute;
  z-index: 80;
  top: calc(100% + 6px);
  right: 0;
  width: min(380px, calc(100vw - 32px));
  min-width: 100%;
  padding: 8px;
  border: 1px solid var(--accounting-border);
  border-radius: 11px;
  background: var(--accounting-surface);
  box-shadow: 0 18px 48px rgb(0 0 0 / 26%);
}

.admin-accounting-category-menu[hidden] {
  display: none !important;
}

.admin-accounting-category-menu.opens-upward {
  top: auto;
  bottom: calc(100% + 6px);
}

.admin-accounting-category-menu.aligns-left {
  right: auto;
  left: 0;
}

.admin-accounting-category-search {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 7px;
  padding: 0 10px;
  border: 1px solid var(--accounting-border);
  border-radius: 8px;
  background: color-mix(in srgb, var(--accounting-text) 4%, transparent);
}

.admin-accounting-category-search > span {
  flex: 0 0 auto;
  color: var(--accounting-muted) !important;
  font: 800 0.9rem/1 "Space Grotesk", sans-serif !important;
}

.admin-accounting-category-search input[data-accounting-category-search] {
  width: 100%;
  min-width: 0;
  min-height: 38px;
  padding: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--accounting-text);
  box-shadow: none;
  font: 750 0.78rem/1 "Space Grotesk", sans-serif;
}

.admin-accounting-category-results {
  display: grid;
  gap: 2px;
  max-height: min(250px, var(--accounting-category-results-max-height, 250px));
  overflow: auto;
  overscroll-behavior: contain;
}

.admin-accounting-category-results > button {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 3px 10px;
  width: 100%;
  padding: 9px 10px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--accounting-text);
  text-align: left;
  cursor: pointer;
}

.admin-accounting-category-results > button:hover,
.admin-accounting-category-results > button:focus-visible,
.admin-accounting-category-results > button[aria-selected='true'] {
  outline: none;
  background: color-mix(in srgb, var(--accounting-text) 7%, transparent);
}

.admin-accounting-category-results > button > span {
  overflow: hidden;
  color: var(--accounting-text) !important;
  font: 800 0.77rem/1.25 "Space Grotesk", sans-serif !important;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-accounting-category-results > button > small {
  grid-column: 1;
  overflow: hidden;
  color: var(--accounting-muted);
  font: 700 0.65rem/1.2 "Plus Jakarta Sans", sans-serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-accounting-category-results > button > b {
  grid-column: 2;
  grid-row: 1 / 3;
  align-self: center;
  color: var(--accounting-text);
  font-size: 0.75rem;
}

.admin-accounting-category-empty {
  margin: 0;
  padding: 18px 10px;
  color: var(--accounting-muted);
  font-size: 0.72rem;
  text-align: center;
}

.pnl-layout {
  --pnl-surface: var(--admin-surface);
  --pnl-border: var(--admin-border);
  --pnl-text: var(--admin-text);
  --pnl-muted: var(--admin-muted);
  display: grid;
  gap: 18px;
  width: 100%;
  min-width: 0;
}

.pnl-controls,
.pnl-kpis article,
.pnl-panel,
.pnl-assurance {
  border: 1px solid var(--pnl-border);
  border-radius: var(--admin-card-radius);
  background: var(--pnl-surface);
  box-shadow: var(--admin-shadow);
}

.pnl-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: end;
  padding: 14px;
}

.pnl-controls label {
  display: grid;
  gap: 6px;
  min-width: 150px;
}

.pnl-controls label span,
.pnl-panel-head > div > span,
.pnl-kpis span,
.pnl-kpis small {
  color: var(--pnl-muted);
  font-size: 0.7rem;
  font-weight: 800;
}

.pnl-controls select {
  min-height: 40px;
  border: 1px solid var(--pnl-border);
  border-radius: 8px;
  background: var(--pnl-surface);
  color: var(--pnl-text);
  padding: 0 34px 0 12px;
  font: 800 0.8rem/1 "Space Grotesk", sans-serif;
}

.pnl-controls p {
  flex: 1 1 240px;
  margin: 0 0 10px;
  color: var(--pnl-muted);
  font-size: 0.72rem;
  font-weight: 750;
  text-align: right;
}

.pnl-kpis {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 12px;
}

.pnl-kpis article {
  display: grid;
  gap: 8px;
  min-width: 0;
  padding: 18px;
}

.pnl-kpis strong {
  overflow: hidden;
  color: var(--pnl-text);
  font: 800 clamp(1rem, 1.35vw, 1.35rem)/1 "Space Grotesk", sans-serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pnl-net-card {
  border-color: color-mix(in srgb, var(--admin-accent) 38%, var(--pnl-border)) !important;
}

.pnl-net-card.is-negative {
  border-color: color-mix(in srgb, #ef4444 46%, var(--pnl-border)) !important;
}

.pnl-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(300px, 0.65fr);
  gap: 18px;
  align-items: start;
}

.pnl-panel {
  min-width: 0;
  padding: 24px;
}

.pnl-panel-head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
  margin-bottom: 18px;
}

.pnl-panel-head h2 {
  margin: 5px 0 0;
  color: var(--pnl-text);
  font: 800 1.35rem/1.1 "Space Grotesk", sans-serif;
}

.pnl-panel-head a,
.pnl-panel-head > small {
  color: var(--pnl-muted);
  font-size: 0.72rem;
  font-weight: 750;
}

.pnl-bridge,
.pnl-expense-mix {
  display: grid;
}

.pnl-bridge > div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 16px;
  padding: 11px 0;
  border-bottom: 1px solid var(--pnl-border);
  color: var(--pnl-muted);
  font-size: 0.8rem;
  font-weight: 700;
}

.pnl-bridge > div strong {
  color: var(--pnl-text);
}

.pnl-bridge > div.is-subtotal,
.pnl-bridge > div.is-total {
  color: var(--pnl-text);
  font-weight: 850;
}

.pnl-bridge > div.is-total {
  margin-top: 4px;
  border-bottom: 0;
  font-size: 1rem;
}

.pnl-expense-mix > div {
  display: grid;
  grid-template-columns: minmax(110px, 1fr) minmax(70px, 0.8fr) auto;
  gap: 10px;
  align-items: center;
  padding: 13px 0;
  border-bottom: 1px solid var(--pnl-border);
  color: var(--pnl-muted);
  font-size: 0.75rem;
  font-weight: 750;
}

.pnl-expense-mix i {
  height: 6px;
  overflow: hidden;
  border-radius: 99px;
  background: color-mix(in srgb, var(--pnl-muted) 17%, transparent);
}

.pnl-expense-mix b {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--pnl-text);
}

.pnl-expense-mix strong {
  color: var(--pnl-text);
  font-size: 0.76rem;
}

.pnl-expense-mix > div > span {
  display: grid;
  gap: 3px;
}

.pnl-expense-mix > div > span small {
  color: color-mix(in srgb, var(--pnl-muted) 80%, transparent);
  font-size: 0.62rem;
  font-weight: 650;
}

.pnl-allocation-panel {
  overflow: hidden;
}

.pnl-settings-button {
  flex: 0 0 auto;
}

.pnl-allocation-intro {
  margin: -6px 0 14px;
  color: var(--pnl-muted);
  font-size: 0.74rem;
  line-height: 1.5;
}

.pnl-allocation-tree {
  display: grid;
}

.pnl-allocation-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
  min-height: 58px;
  padding: 10px 0 10px calc(10px + (var(--pnl-allocation-depth) * 28px));
  border-bottom: 1px solid var(--pnl-border);
}

.pnl-allocation-row:last-child {
  border-bottom: 0;
}

.pnl-allocation-row > span {
  position: relative;
  display: grid;
  gap: 4px;
}

.pnl-allocation-row[style*="depth:1"] > span::before,
.pnl-allocation-row[style*="depth:2"] > span::before,
.pnl-allocation-row[style*="depth:3"] > span::before,
.pnl-allocation-row[style*="depth:4"] > span::before,
.pnl-allocation-row[style*="depth:5"] > span::before,
.pnl-allocation-row[style*="depth:6"] > span::before,
.pnl-allocation-row[style*="depth:7"] > span::before,
.pnl-allocation-row[style*="depth:8"] > span::before {
  position: absolute;
  top: 2px;
  bottom: 2px;
  left: -15px;
  width: 1px;
  background: color-mix(in srgb, var(--pnl-muted) 35%, transparent);
  content: "";
}

.pnl-allocation-row > span strong,
.pnl-allocation-row > b {
  color: var(--pnl-text);
  font-size: 0.82rem;
}

.pnl-allocation-row.has-children > span strong {
  font-weight: 850;
}

.pnl-allocation-row > span small {
  color: var(--pnl-muted);
  font-size: 0.68rem;
  font-weight: 700;
}

.pnl-allocation-empty {
  margin: 0;
  padding: 20px;
  color: var(--pnl-muted);
  text-align: center;
}

.pnl-allocation-dialog {
  width: min(980px, calc(100vw - 32px));
  max-height: min(850px, calc(100vh - 32px));
  padding: 0;
  overflow: hidden;
  border: 1px solid var(--pnl-border, var(--admin-border));
  border-radius: 16px;
  background: var(--pnl-surface, var(--admin-surface));
  color: var(--pnl-text, var(--admin-text));
  box-shadow: 0 28px 80px rgba(0, 0, 0, 0.42);
}

.pnl-allocation-dialog::backdrop {
  background: rgba(0, 0, 0, 0.72);
  backdrop-filter: blur(3px);
}

.pnl-allocation-form {
  display: grid;
  gap: 16px;
  max-height: min(850px, calc(100vh - 32px));
  padding: 22px;
}

.pnl-allocation-dialog-head {
  display: flex;
  justify-content: space-between;
  gap: 20px;
}

.pnl-allocation-dialog-head span,
.pnl-allocation-editor-row label > span {
  color: var(--admin-muted);
  font-size: 0.66rem;
  font-weight: 800;
}

.pnl-allocation-dialog-head h2 {
  margin: 4px 0;
  font: 800 1.35rem/1.1 "Space Grotesk", sans-serif;
}

.pnl-allocation-dialog-head p {
  margin: 0;
  color: var(--admin-muted);
  font-size: 0.74rem;
}

.pnl-dialog-close,
.pnl-allocation-remove {
  border: 0;
  background: transparent;
  color: var(--admin-muted);
  cursor: pointer;
}

.pnl-dialog-close {
  width: 36px;
  height: 36px;
  font-size: 1.7rem;
  line-height: 1;
}

.pnl-allocation-editor {
  display: grid;
  gap: 12px;
  max-height: min(570px, calc(100vh - 280px));
  padding: 14px;
  overflow: auto;
  border: 1px solid var(--admin-border);
  border-radius: 12px;
  background: color-mix(in srgb, var(--admin-surface) 94%, var(--admin-text) 6%);
}

.pnl-allocation-editor-level {
  display: grid;
  gap: 10px;
}

.pnl-allocation-editor-level .pnl-allocation-editor-level {
  margin: 12px 0 0 24px;
  padding-left: 14px;
  border-left: 1px solid var(--admin-border);
}

.pnl-allocation-level-summary {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  color: var(--admin-muted);
  font-size: 0.68rem;
  font-weight: 800;
}

.pnl-allocation-level-summary strong.is-valid {
  color: #4ade80;
}

.pnl-allocation-level-summary strong.is-invalid,
.pnl-allocation-error {
  color: #f87171;
}

.pnl-allocation-editor-item {
  min-width: 0;
}

.pnl-allocation-editor-row {
  display: grid;
  grid-template-columns: minmax(180px, 1fr) minmax(120px, 0.35fr) auto auto;
  gap: 8px;
  align-items: end;
}

.pnl-allocation-editor-row label {
  position: relative;
  display: grid;
  gap: 5px;
  min-width: 0;
}

.pnl-allocation-editor-row input {
  width: 100%;
  min-height: 40px;
  border: 1px solid var(--admin-border);
  border-radius: 8px;
  background: var(--admin-surface);
  color: var(--admin-text);
  padding: 0 11px;
  font: 750 0.78rem/1 "Plus Jakarta Sans", sans-serif;
}

.pnl-allocation-percentage input {
  padding-right: 28px;
}

.pnl-allocation-percentage > b {
  position: absolute;
  right: 10px;
  bottom: 12px;
  color: var(--admin-muted);
  font-size: 0.72rem;
}

.pnl-allocation-editor-row .admin-ghost-btn {
  min-height: 40px;
  white-space: nowrap;
}

.pnl-allocation-remove {
  min-height: 40px;
  padding: 0 6px;
  font-size: 0.7rem;
  font-weight: 800;
}

.pnl-allocation-error {
  margin: 0;
  font-size: 0.74rem;
  font-weight: 750;
}

.pnl-allocation-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

:root[data-admin-theme='light'] .pnl-allocation-dialog {
  border-color: rgba(15, 23, 42, 0.12);
  background: #fff;
}

:root[data-admin-theme='light'] .pnl-allocation-editor {
  background: #f8fafc;
}

:root[data-admin-theme='light'] .pnl-allocation-level-summary strong.is-valid {
  color: #15803d;
}

:root[data-admin-theme='light'] .pnl-allocation-level-summary strong.is-invalid,
:root[data-admin-theme='light'] .pnl-allocation-error {
  color: #b91c1c;
}

.pnl-trend {
  display: grid;
  grid-template-columns: repeat(12, minmax(28px, 1fr));
  gap: 8px;
  align-items: end;
  height: 150px;
  margin: 4px 0 22px;
  padding: 12px 10px 0;
  border-bottom: 1px solid var(--pnl-border);
}

.pnl-trend button {
  display: grid;
  grid-template-rows: minmax(0, 1fr) 20px;
  align-items: end;
  height: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: pointer;
}

.pnl-trend i {
  display: block;
  width: min(70%, 32px);
  min-height: 4px;
  margin: 0 auto;
  border-radius: 5px 5px 0 0;
  background: var(--pnl-text);
}

.pnl-trend i.is-negative {
  opacity: 0.35;
}

.pnl-trend span {
  color: var(--pnl-muted);
  font-size: 0.62rem;
  font-weight: 800;
}

.pnl-table-wrap {
  max-height: 460px;
  border-top: 1px solid var(--pnl-border);
}

.pnl-table {
  min-width: 900px;
}

.pnl-table th,
.pnl-table td {
  padding: 12px 10px;
  font-size: 0.75rem;
  white-space: nowrap;
}

.pnl-table tbody tr.is-selected {
  background: color-mix(in srgb, var(--pnl-text) 6%, transparent);
}

.pnl-table td button {
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--pnl-text);
  font: inherit;
  font-weight: 800;
  cursor: pointer;
}

.pnl-assurance {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0;
  padding: 18px 20px;
}

.pnl-assurance > div {
  display: grid;
  gap: 6px;
  padding: 0 20px;
  border-right: 1px solid var(--pnl-border);
}

.pnl-assurance > div:first-child {
  padding-left: 0;
}

.pnl-assurance > div:last-child {
  padding-right: 0;
  border-right: 0;
}

.pnl-assurance strong {
  color: var(--pnl-text);
  font-size: 0.76rem;
}

.pnl-assurance span {
  color: var(--pnl-muted);
  font-size: 0.72rem;
  line-height: 1.5;
}

:root[data-admin-theme='light'] :is(.pnl-controls, .pnl-kpis article, .pnl-panel, .pnl-assurance) {
  border-color: rgba(15, 23, 42, 0.1);
  background: #fff;
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.05);
}

@media (max-width: 1320px) {
  .pnl-kpis {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

@media (max-width: 980px) {
  .pnl-grid {
    grid-template-columns: 1fr;
  }

  .pnl-assurance {
    grid-template-columns: 1fr;
  }

  .pnl-assurance > div,
  .pnl-assurance > div:first-child,
  .pnl-assurance > div:last-child {
    padding: 12px 0;
    border-right: 0;
    border-bottom: 1px solid var(--pnl-border);
  }

  .pnl-assurance > div:last-child {
    border-bottom: 0;
  }
}

@media (max-width: 640px) {
  .admin-finance-page-head,
  :root[data-admin-theme='light'] .admin-finance-page-head,
  :root[data-admin-theme='dark'] .admin-finance-page-head {
    padding: 4px 4px 18px;
  }

  .admin-finance-page-head .admin-topbar-brand h1 {
    max-width: calc(100vw - 170px);
    font-size: clamp(1.7rem, 8vw, 2.2rem);
  }

  .admin-finance-page-head .admin-topbar-brand p {
    max-width: calc(100vw - 80px);
    font-size: 0.78rem;
  }

  .admin-accounting-command {
    grid-template-columns: 1fr;
  }

  .admin-accounting-command .admin-accounting-status,
  .admin-accounting-command .admin-accounting-alert-strip {
    grid-column: 1;
  }

  .admin-accounting-command-fields {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
  }

  .admin-accounting-command-fields .admin-accounting-field {
    width: 100%;
  }

  .admin-accounting-command-fields [data-accounting-current-month] {
    grid-column: 1 / -1;
  }

  .admin-accounting-mode-picker,
  .admin-accounting-edit-form {
    grid-template-columns: 1fr;
    width: 100%;
  }

  .admin-accounting-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }

  .admin-accounting-metric {
    min-height: 104px;
    padding: 14px;
  }

  .admin-accounting-metric strong {
    font-size: clamp(0.94rem, 4.4vw, 1.12rem);
  }

  .admin-accounting-edit-form > :is(button, .admin-form-error) {
    grid-column: 1;
  }

  .pnl-layout {
    gap: 12px;
  }

  .pnl-controls {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    padding: 12px;
  }

  .pnl-controls label {
    min-width: 0;
  }

  .pnl-controls button,
  .pnl-controls p {
    grid-column: 1 / -1;
    width: 100%;
    margin: 0;
    text-align: left;
  }

  .pnl-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }

  .pnl-kpis article,
  .pnl-panel {
    padding: 15px;
  }

  .pnl-kpis strong {
    font-size: clamp(0.95rem, 4.5vw, 1.15rem);
  }

  .pnl-panel-head {
    align-items: flex-start;
  }

  .pnl-expense-mix > div {
    grid-template-columns: minmax(100px, 1fr) auto;
  }

  .pnl-expense-mix i {
    display: none;
  }

  .pnl-allocation-dialog {
    width: calc(100vw - 16px);
    max-height: calc(100vh - 16px);
  }

  .pnl-allocation-form {
    max-height: calc(100vh - 16px);
    padding: 16px;
  }

  .pnl-allocation-editor-row {
    grid-template-columns: minmax(0, 1fr) 100px;
  }

  .pnl-allocation-editor-row .admin-ghost-btn,
  .pnl-allocation-remove {
    width: 100%;
  }

  .pnl-allocation-editor-level .pnl-allocation-editor-level {
    margin-left: 10px;
    padding-left: 8px;
  }

  .pnl-allocation-row {
    padding-left: calc(4px + (var(--pnl-allocation-depth) * 16px));
  }

  .pnl-trend {
    gap: 3px;
    height: 120px;
    padding-inline: 0;
  }

  .pnl-trend span {
    font-size: 0.54rem;
  }
}

/* Ad View */
.admin-ad-view-toolbar,
.admin-ad-view-kpis > :is(article, button) {
  border: 1px solid var(--admin-border);
  background: var(--admin-surface);
  box-shadow: var(--admin-shadow);
}

.admin-ad-view-disclaimer {
  color: var(--admin-muted);
}

.admin-ad-view-toolbar {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) repeat(2, minmax(160px, 0.55fr)) auto;
  gap: 14px;
  align-items: end;
  margin-bottom: 18px;
  padding: 18px;
  border-radius: 20px;
}

.admin-ad-view-toolbar label,
.admin-ad-view-track-form label,
.admin-ad-view-budget-form label,
.admin-ad-view-action-form label,
.admin-ad-view-compare-controls label {
  display: grid;
  gap: 7px;
  min-width: 0;
  color: var(--admin-muted);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.admin-ad-view-toolbar :is(input, select),
.admin-ad-view-track-form :is(input, select),
.admin-ad-view-budget-form :is(input, select),
.admin-ad-view-action-form :is(input, select, textarea),
.admin-ad-view-compare-controls select {
  width: 100%;
  min-height: 44px;
  padding: 10px 12px;
  border: 1px solid var(--admin-border);
  border-radius: 12px;
  outline: none;
  background: var(--admin-surface-soft);
  color: var(--admin-text);
  font: 600 0.86rem/1.3 'Plus Jakarta Sans', sans-serif;
  letter-spacing: 0;
  text-transform: none;
}

.admin-ad-view-action-form textarea {
  resize: vertical;
}

.admin-ad-view-kpis {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 18px;
}

.admin-ad-view-kpis > :is(article, button) {
  display: grid;
  gap: 8px;
  min-height: 132px;
  padding: 20px;
  border-radius: 20px;
}

.admin-ad-view-kpis span,
.admin-ad-view-kpis small {
  color: var(--admin-muted);
  font-size: 0.75rem;
}

.admin-ad-view-kpis strong {
  align-self: end;
  font: 700 clamp(1.25rem, 2vw, 2rem)/1 'Space Grotesk', sans-serif;
  letter-spacing: -0.04em;
}

.admin-ad-view-kpis > button {
  position: relative;
  width: 100%;
  overflow: hidden;
  color: var(--admin-text);
  text-align: left;
  cursor: pointer;
  transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}

.admin-ad-view-kpis > button:hover {
  transform: translateY(-1px);
}

.admin-ad-view-kpis > button > i {
  position: absolute;
  inset: 0 0 auto;
  height: 4px;
  background: var(--ad-metric-color);
  opacity: 0.28;
}

.admin-ad-view-kpis > button.is-selected {
  border-color: var(--ad-metric-color);
  box-shadow: 0 0 0 1px var(--ad-metric-color), var(--admin-shadow);
}

.admin-ad-view-kpis > button.is-selected > i {
  opacity: 1;
}

.admin-ad-view-grid {
  display: grid;
  grid-template-columns: 1.35fr 0.85fr;
  gap: 18px;
  margin-bottom: 18px;
}

.admin-ad-view-track-form,
.admin-ad-view-budget-form,
.admin-ad-view-action-form {
  display: grid;
  gap: 12px;
  align-items: end;
}

.admin-ad-view-track-form {
  grid-template-columns: 0.8fr 0.8fr 1.35fr auto;
}

.admin-ad-view-budget-form {
  grid-template-columns: 1fr 0.8fr 1fr;
}

.admin-ad-view-budget-form button {
  grid-column: 1 / -1;
}

.admin-ad-view-compare-panel,
.admin-ad-view-library-panel {
  margin-bottom: 18px;
}

.admin-ad-view-compare-controls {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: end;
  gap: 16px;
  margin-bottom: 20px;
}

.admin-ad-view-versus {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border: 1px solid var(--admin-border);
  border-radius: 50%;
  color: var(--admin-muted);
  font-size: 0.72rem;
  font-weight: 900;
}

.admin-ad-view-scorecard {
  overflow: hidden;
  border: 1px solid var(--admin-border);
  border-radius: 20px;
  background: color-mix(in srgb, var(--admin-surface-soft) 58%, transparent);
}

.admin-ad-score-row {
  padding: 19px 18px;
  border-bottom: 1px solid var(--admin-border);
}

.admin-ad-score-row:last-child {
  border-bottom: 0;
}

.admin-ad-score-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 14px;
  margin-bottom: 14px;
}

.admin-ad-score-head strong {
  display: block;
  margin-bottom: 3px;
  font-size: 0.88rem;
}

.admin-ad-score-head small {
  color: var(--admin-muted);
  font-size: 0.71rem;
}

.admin-ad-score-delta {
  align-self: start;
  padding: 6px 9px;
  border-radius: 9px;
  background: rgba(0, 211, 137, 0.12);
  color: #00d389;
  font-size: 0.72rem;
  font-weight: 900;
}

.admin-ad-score-delta.is-negative {
  background: rgba(255, 82, 82, 0.12);
  color: var(--admin-accent-tertiary);
}

.admin-ad-score-delta.is-cost {
  background: rgba(255, 188, 45, 0.12);
  color: #ffbc2d;
}

.admin-ad-score-line {
  display: grid;
  grid-template-columns: minmax(58px, 0.14fr) minmax(120px, 1fr) minmax(90px, auto);
  gap: 12px;
  align-items: center;
  margin-top: 9px;
  color: var(--admin-muted);
  font-size: 0.72rem;
}

.admin-ad-score-line b {
  color: var(--admin-text);
  text-align: right;
  font-size: 0.75rem;
}

.admin-ad-score-track {
  height: 11px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.045);
}

.admin-ad-score-fill {
  display: block;
  min-width: 3px;
  height: 100%;
  border-radius: inherit;
  background: #77766f;
}

.admin-ad-score-line.is-new .admin-ad-score-fill {
  background: #00d389;
}

.admin-ad-score-row.is-cost .admin-ad-score-line.is-new .admin-ad-score-fill {
  background: #ffbc2d;
}

.admin-ad-view-disclaimer {
  margin: 12px 2px 0;
  font-size: 0.72rem;
  line-height: 1.6;
}

.admin-ad-view-action-form {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.admin-ad-view-field-wide,
.admin-ad-view-action-form button {
  grid-column: 1 / -1;
}

.admin-ad-view-events-panel .admin-event-feed {
  max-height: 560px;
  overflow: auto;
}

.admin-ad-view-event {
  position: relative;
  padding: 14px 14px 14px 20px;
  border: 1px solid var(--admin-border);
  border-radius: 14px;
  background: var(--admin-surface-soft);
}

.admin-ad-view-event::before {
  content: '';
  position: absolute;
  left: 8px;
  top: 17px;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--admin-accent-primary);
}

.admin-ad-view-event-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.admin-ad-view-event small,
.admin-ad-view-event p {
  color: var(--admin-muted);
}

.admin-ad-view-event p {
  margin: 7px 0 0;
  font-size: 0.76rem;
  line-height: 1.55;
}

.admin-ad-view-tag {
  display: inline-flex;
  margin: 2px 4px 2px 0;
  padding: 4px 7px;
  border: 1px solid var(--admin-border);
  border-radius: 999px;
  background: var(--admin-surface-soft);
  color: var(--admin-muted);
  font-size: 0.65rem;
  font-weight: 800;
}

.admin-ad-view-table td:first-child {
  min-width: 250px;
}

.admin-ad-view-campaign-name {
  display: grid;
  gap: 4px;
}

.admin-ad-view-campaign-name small {
  color: var(--admin-muted);
}

.admin-ad-view-status-chip {
  display: inline-flex;
  padding: 5px 8px;
  border-radius: 999px;
  background: rgba(0, 211, 137, 0.1);
  color: #00d389;
  font-size: 0.68rem;
  font-weight: 900;
  text-transform: capitalize;
}

.admin-ad-view-status-chip.is-muted {
  background: var(--admin-surface-soft);
  color: var(--admin-muted);
}

@media (max-width: 1180px) {
  .admin-ad-view-kpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .admin-ad-view-track-form,
  .admin-ad-view-toolbar {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 820px) {
  .admin-ad-view-grid {
    display: grid;
    grid-template-columns: 1fr;
  }

  .admin-ad-view-kpis,
  .admin-ad-view-track-form,
  .admin-ad-view-toolbar,
  .admin-ad-view-budget-form,
  .admin-ad-view-action-form {
    grid-template-columns: 1fr;
  }

  .admin-ad-view-compare-controls {
    grid-template-columns: 1fr;
  }

  .admin-ad-view-versus {
    justify-self: center;
  }

  .admin-ad-view-field-wide,
  .admin-ad-view-action-form button {
    grid-column: auto;
  }
}

/* AD VIEW follows the dashboard's minimal, flat chrome. */
.admin-app[data-admin-dashboard] [data-view-panel='ad-view'] > .admin-ad-view-toolbar {
  grid-template-columns: minmax(160px, 0.48fr) minmax(320px, 0.9fr) minmax(330px, 1fr) auto;
  gap: 12px;
  margin-bottom: 16px;
  padding: 0 0 16px;
  border: 0;
  border-bottom: 1px solid var(--admin-border);
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.admin-ad-view-timeframes {
  display: grid;
  gap: 7px;
}

.admin-ad-view-timeframes > span {
  color: var(--admin-muted);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.admin-ad-view-timeframes > div {
  display: flex;
  min-height: 44px;
  padding: 3px;
  border: 1px solid var(--admin-border);
  border-radius: 12px;
  background: var(--admin-surface-soft);
}

.admin-ad-view-timeframes button {
  flex: 1;
  min-width: 70px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: var(--admin-muted);
  font: 800 0.74rem/1 'Plus Jakarta Sans', sans-serif;
  cursor: pointer;
}

.admin-ad-view-timeframes button.is-active {
  background: var(--admin-surface);
  color: var(--admin-text);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.14);
}

.admin-ad-view-custom-range {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: repeat(2, minmax(150px, 220px)) auto;
  gap: 10px;
  align-items: end;
}

.admin-ad-view-custom-range[hidden] {
  display: none;
}

.admin-ad-view-toolbar > .admin-form-error {
  grid-column: 1 / -1;
}

.admin-ad-view-credits {
  min-width: 0;
  margin: 0;
}

.admin-ad-view-credits > article {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 12px;
  min-height: 44px;
  padding: 7px 10px;
  border: 1px solid var(--admin-border);
  border-radius: 13px;
  background: var(--admin-surface-soft);
}

.admin-ad-view-credits > article > div:first-child {
  display: grid;
  gap: 3px;
  flex: 0 0 auto;
}

.admin-ad-view-credits > article > div:first-child > span {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--admin-text);
  font-size: 0.72rem;
  font-weight: 850;
}

.admin-ad-view-credit-settings {
  display: inline-grid;
  place-items: center;
  width: 24px;
  height: 24px;
  margin-left: 1px;
  padding: 0;
  border: 1px solid var(--admin-border);
  border-radius: 7px;
  background: transparent;
  color: var(--admin-muted);
  cursor: pointer;
  transition: border-color 160ms ease, color 160ms ease, background 160ms ease;
}

.admin-ad-view-credit-settings:hover,
.admin-ad-view-credit-settings:focus-visible {
  border-color: currentColor;
  background: var(--admin-surface);
  color: var(--admin-text);
}

.admin-ad-view-credit-settings svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.admin-ad-view-credits small {
  color: var(--admin-muted);
  font-size: 0.59rem;
}

.admin-ad-view-credit-breakdown {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 8px;
  min-width: 0;
}

.admin-ad-view-credit-breakdown > span {
  display: grid;
  gap: 2px;
  min-width: 0;
  padding-left: 9px;
  overflow-wrap: anywhere;
  border-left: 1px solid var(--admin-border);
}

.admin-ad-view-credit-breakdown strong {
  color: var(--admin-text);
  font: 700 0.76rem/1.2 'Space Grotesk', sans-serif;
}

@keyframes admin-ad-credit-alert-flash {
  0%, 100% {
    color: #ff334f;
    opacity: 1;
    filter: drop-shadow(0 0 7px rgba(255, 51, 79, 0.72));
  }
  50% {
    color: #ff334f;
    opacity: 0.24;
    filter: drop-shadow(0 0 1px rgba(255, 51, 79, 0.2));
  }
}

.admin-ad-view-credit-breakdown strong.is-credit-alert,
.admin-rail-link.is-credit-alert {
  animation: admin-ad-credit-alert-flash 1.15s ease-in-out infinite;
}

.admin-rail-link.is-credit-alert::before {
  width: 24px;
  background: #ff334f;
  opacity: 1;
}

.admin-ad-view-credit-alert-fields {
  display: grid;
  gap: 12px;
}

.admin-ad-view-currency-input {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  overflow: hidden;
  border: 1px solid var(--admin-border);
  border-radius: 10px;
  background: var(--admin-input-bg);
}

.admin-ad-view-currency-input:focus-within {
  border-color: color-mix(in srgb, var(--admin-text) 48%, var(--admin-border));
}

.admin-ad-view-currency-input b {
  padding-left: 12px;
  color: var(--admin-muted);
  font-size: 0.76rem;
}

.admin-ad-view-editor-card .admin-ad-view-currency-input input {
  width: 100%;
  border: 0;
  background: transparent;
}

.admin-ad-view-credit-alert-dialog .admin-form-error {
  margin: 0;
  color: #ff6073;
}

@media (prefers-reduced-motion: reduce) {
  .admin-ad-view-credit-breakdown strong.is-credit-alert,
  .admin-rail-link.is-credit-alert {
    animation: none;
    color: #ff334f;
    filter: drop-shadow(0 0 5px rgba(255, 51, 79, 0.6));
  }
}

.admin-ad-view-trend-panel {
  margin: 0;
}

.admin-ad-view-trend-panel .admin-ad-view-kpis {
  grid-template-columns: repeat(7, minmax(88px, 1fr));
  gap: 6px;
  margin: 12px 0 6px;
  overflow-x: auto;
  scrollbar-width: thin;
}

.admin-ad-view-trend-panel .admin-ad-view-kpis > button {
  gap: 3px;
  min-height: 66px;
  padding: 10px;
  border-radius: 11px;
  font-family: 'Plus Jakarta Sans', sans-serif;
}

.admin-ad-view-trend-panel .admin-ad-view-kpis span {
  color: var(--admin-muted);
  font-size: 0.68rem;
  font-weight: 650;
  letter-spacing: 0;
  line-height: 1.25;
  text-transform: none;
  white-space: nowrap;
}

.admin-ad-view-trend-panel .admin-ad-view-kpis strong {
  align-self: end;
  font: 700 clamp(0.88rem, 1vw, 1.05rem)/1.2 'Plus Jakarta Sans', sans-serif;
  letter-spacing: -0.01em;
}

.admin-ad-view-trend-panel .admin-chart-surface {
  min-height: 340px;
}

.admin-ad-view-detail-panel {
  margin-bottom: 18px;
}

.admin-ad-view-detail-panel .admin-ad-view-product-image.is-large {
  width: 58px;
  height: 58px;
}

.admin-ad-view-profit-heading {
  padding-top: 0;
}

.admin-ad-view-detail-panel .admin-ad-view-profit-grid {
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 10px;
}

.admin-ad-view-detail-panel .admin-ad-view-profit-grid article {
  min-height: 112px;
  padding: 17px;
  border-radius: 15px;
  font-family: 'Plus Jakarta Sans', sans-serif;
}

.admin-ad-view-detail-panel .admin-ad-view-profit-grid strong {
  align-self: end;
  font: 700 clamp(1rem, 1.35vw, 1.28rem)/1.2 'Plus Jakarta Sans', sans-serif;
  letter-spacing: -0.01em;
}

.admin-ad-view-detail-panel .admin-ad-view-direct-metrics .admin-ad-view-settings-grid {
  padding: 0 0 12px;
}

@media (min-width: 1480px) {
  .admin-ad-view-kpis {
    grid-template-columns: repeat(7, minmax(0, 1fr));
  }
}

.admin-ad-view-toolbar-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  min-height: 44px;
}

.admin-ad-view-sync-status {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  max-width: 190px;
  color: var(--admin-muted);
  font-size: 0.66rem;
  font-weight: 700;
  line-height: 1.35;
}

.admin-app[data-admin-dashboard] [data-view-panel='ad-view'] .admin-panel-inline-toggles.admin-sliding-chart-toggle {
  margin: 0 0 12px;
}

@media (max-width: 1180px) {
  .admin-app[data-admin-dashboard] [data-view-panel='ad-view'] > .admin-ad-view-toolbar {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .admin-ad-view-toolbar-actions {
    justify-content: flex-start;
  }

}

@media (max-width: 1100px) {
  .admin-ad-view-detail-panel .admin-ad-view-profit-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 680px) {
  .admin-app[data-admin-dashboard] [data-view-panel='ad-view'] > .admin-ad-view-toolbar {
    grid-template-columns: 1fr;
  }

  .admin-ad-view-toolbar-actions {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-ad-view-timeframes > div {
    overflow-x: auto;
  }

  .admin-ad-view-custom-range {
    grid-template-columns: 1fr;
  }

  .admin-ad-view-credits > article,
  .admin-ad-view-credit-breakdown {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-ad-view-credit-breakdown {
    grid-template-columns: minmax(0, 1fr);
    gap: 7px;
  }

  .admin-ad-view-credit-breakdown > span {
    grid-template-columns: minmax(0, 1fr) auto;
    padding: 6px 0 0;
    border-top: 1px solid var(--admin-border);
    border-left: 0;
  }

  .admin-ad-view-detail-panel .admin-ad-view-profit-grid {
    grid-template-columns: 1fr;
  }
}

/* Shipment arrangement */
.admin-shipment-arrangement {
  --arrangement-shopee: #ff6b35;
  --arrangement-tiktok: #2dd4bf;
  --arrangement-policy: #818cf8;
  gap: 18px;
}

.admin-arrangement-hero,
.admin-arrangement-hero-actions,
.admin-arrangement-toolbar,
.admin-arrangement-week-nav,
.admin-arrangement-legend,
.admin-arrangement-order,
.admin-arrangement-time-range {
  display: flex;
  align-items: center;
}

.admin-arrangement-hero {
  justify-content: space-between;
  gap: 24px;
  padding: 25px 28px;
  border: 1px solid var(--admin-border);
  border-radius: 22px;
  background: var(--admin-surface);
}

.admin-arrangement-hero h2 {
  margin: 4px 0 7px;
  font: 700 clamp(1.65rem, 2.8vw, 2.65rem)/1 'Space Grotesk', sans-serif;
  letter-spacing: -.045em;
}

.admin-arrangement-hero p,
.admin-arrangement-safety p,
[data-arrangement-unlock] > p {
  margin: 0;
  color: var(--admin-muted);
}

.admin-arrangement-hero-actions { gap: 10px; }

.admin-arrangement-live {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  padding: 0 13px;
  border: 1px solid rgba(52, 211, 153, .25);
  border-radius: 999px;
  background: rgba(52, 211, 153, .08);
  color: #34d399;
  font-size: .72rem;
  font-weight: 800;
  letter-spacing: .02em;
}

.admin-arrangement-live i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 4px rgba(52, 211, 153, .12);
}

.admin-arrangement-live.is-paused {
  border-color: rgba(251, 191, 36, .25);
  background: rgba(251, 191, 36, .08);
  color: #fbbf24;
}

.admin-arrangement-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.admin-arrangement-metrics article {
  min-height: 118px;
  padding: 18px 20px;
  border: 1px solid var(--admin-border);
  border-radius: 18px;
  background: var(--admin-surface);
}

.admin-arrangement-metrics span,
.admin-arrangement-order div > span {
  display: block;
  margin-bottom: 10px;
  color: var(--admin-muted);
  font-size: .68rem;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.admin-arrangement-metrics strong {
  display: block;
  margin-bottom: 7px;
  font: 700 1.35rem/1.1 'Space Grotesk', sans-serif;
}

.admin-arrangement-metrics small,
.admin-arrangement-order small { color: var(--admin-muted); }

.admin-arrangement-map-panel { overflow: hidden; padding: 0; }

.admin-arrangement-toolbar {
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  padding: 17px 20px;
  border-bottom: 1px solid var(--admin-border);
}

.admin-arrangement-segment,
.admin-arrangement-rule-tabs {
  display: inline-flex;
  gap: 3px;
  padding: 4px;
  border: 1px solid var(--admin-border);
  border-radius: 13px;
  background: var(--admin-bg);
}

.admin-arrangement-segment button,
.admin-arrangement-rule-tabs button {
  min-height: 34px;
  padding: 0 12px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: var(--admin-muted);
  font: inherit;
  font-size: .72rem;
  font-weight: 800;
  cursor: pointer;
}

.admin-arrangement-segment button.is-active,
.admin-arrangement-rule-tabs button.is-active {
  background: var(--admin-text);
  color: var(--admin-bg);
}

.admin-arrangement-week-nav { gap: 8px; }
.admin-arrangement-week-nav strong { min-width: 155px; text-align: center; font-size: .78rem; }

