@media (max-width: 680px) {
  .admin-shipment-arrangement .admin-arrangement-hero {
    align-items: flex-start;
    padding: 4px 0 18px;
  }

  .admin-shipment-arrangement .admin-arrangement-hero-actions {
    width: 100%;
    justify-content: space-between;
  }

  .admin-arrangement-tabs {
    padding: 0;
