  .admin-arrangement-primary {
    padding: 22px 0 30px;
  }

  .admin-arrangement-schedule-head,
  .admin-arrangement-rules-head {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-arrangement-week-nav {
    width: 100%;
  }

  .admin-arrangement-week-nav button {
    flex: 1;
  }

  .admin-arrangement-guide {
    grid-template-columns: 1fr;
    padding-right: 0;
    padding-left: 0;
  }

  .admin-arrangement-editor-head {
    display: none;
  }

  .admin-arrangement-editor-row {
    grid-template-columns: 90px 1fr;
    gap: 8px;
    padding: 12px 0;
  }

  .admin-arrangement-editor-row > label {
    grid-column: 2;
  }

  .admin-arrangement-editor-row label > span {
    display: block;
    margin-bottom: 5px;
    color: var(--admin-muted);
    font-size: .55rem;
  }

  .admin-shipment-arrangement .admin-arrangement-unlock-form {
    grid-template-columns: 1fr;
  }

  .admin-arrangement-savebar {
    align-items: flex-start;
    flex-direction: column;
  }

  .admin-arrangement-savebar > div,
  .admin-arrangement-savebar button {
    width: 100%;
  }

  .admin-shipment-arrangement .admin-arrangement-order,
  .admin-shipment-arrangement .admin-arrangement-order > :nth-child(4) {
    grid-template-columns: 1fr;
    grid-column: auto;
  }
}

/* Shipment arrangement v4 — visual timeline and card-based rule editor */
.admin-arrangement-smart-policy {
  display: grid;
  gap: 20px;
  margin-bottom: 30px;
  padding: 22px;
  border: 1px solid color-mix(in srgb, var(--arrangement-shopee) 42%, var(--admin-border));
  border-radius: 12px;
  background: color-mix(in srgb, var(--arrangement-shopee) 5%, var(--admin-surface));
}

.admin-arrangement-smart-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}

.admin-arrangement-smart-head h3,
.admin-arrangement-weekly-heading h3 {
  margin: 4px 0 5px;
  font-size: 1rem;
}

.admin-arrangement-smart-head p,
.admin-arrangement-weekly-heading p {
  margin: 0;
  color: var(--admin-muted);
  font-size: .65rem;
  line-height: 1.5;
}

.admin-arrangement-pause-lock {
  flex: 0 0 auto;
  padding: 7px 9px;
  border: 1px solid color-mix(in srgb, #fbbf24 42%, var(--admin-border));
  border-radius: 999px;
  color: #fbbf24;
  background: color-mix(in srgb, #fbbf24 8%, var(--admin-bg));
  font-size: .56rem;
  font-weight: 850;
  letter-spacing: .04em;
  text-transform: uppercase;
}

.admin-arrangement-decision-flow {
  display: grid;
  grid-template-columns: minmax(145px, 1fr) 18px minmax(145px, 1fr) 18px minmax(175px, 1.15fr) 18px minmax(185px, 1.2fr) 18px minmax(190px, 1.25fr);
  align-items: stretch;
  overflow-x: auto;
  padding-bottom: 4px;
}

.admin-arrangement-decision-step {
  position: relative;
  display: grid;
  align-content: start;
  gap: 7px;
  min-height: 126px;
  padding: 13px;
  border: 1px solid var(--admin-border);
  border-top: 3px solid var(--admin-muted);
  border-radius: 8px;
  background: var(--admin-bg);
}

.admin-arrangement-decision-step.is-pickup { border-top-color: #60a5fa; }
.admin-arrangement-decision-step.is-wait { border-top-color: #a78bfa; }
.admin-arrangement-decision-step.is-dropoff { border-top-color: #fbbf24; }
.admin-arrangement-decision-step.is-weekend { border-top-color: #f59e0b; }
.admin-arrangement-decision-step.is-hold { border-top-color: #fb7185; }
.admin-arrangement-decision-step.is-start { border-top-color: var(--arrangement-shopee); }

.admin-arrangement-decision-step i {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  color: var(--admin-bg);
  background: var(--admin-text);
  font-size: .54rem;
  font-style: normal;
  font-weight: 900;
}

.admin-arrangement-decision-step span {
  color: var(--admin-muted);
  font-size: .52rem;
  font-weight: 850;
  letter-spacing: .05em;
  text-transform: uppercase;
}

.admin-arrangement-decision-step strong {
  font-size: .62rem;
  line-height: 1.48;
}

.admin-arrangement-decision-arrow {
  display: grid;
  place-items: center;
  color: var(--admin-muted);
  font-size: .8rem;
}

.admin-arrangement-smart-controls {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 9px;
}

.admin-arrangement-smart-controls > label {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px 12px;
  min-height: 102px;
  padding: 13px;
  border: 1px solid var(--admin-border);
  border-radius: 8px;
  background: color-mix(in srgb, var(--admin-text) 2.5%, transparent);
}

.admin-arrangement-smart-controls label > span {
  font-size: .63rem;
  font-weight: 850;
}

.admin-arrangement-smart-controls label > span em {
  margin-left: 4px;
  color: #a78bfa;
  font-size: .45rem;
  font-style: normal;
  letter-spacing: .04em;
  text-transform: uppercase;
}

.admin-arrangement-smart-controls label > small {
  grid-column: 1 / -1;
  align-self: start;
  color: var(--admin-muted);
  font-size: .52rem;
  line-height: 1.45;
}

.admin-arrangement-smart-controls select,
.admin-arrangement-smart-controls input[type='time'],
.admin-arrangement-smart-controls input[type='number'] {
  min-height: 36px;
  border: 1px solid var(--admin-border);
  border-radius: 7px;
  color: var(--admin-text);
  background: var(--admin-bg);
  font: 750 .62rem/1 'Plus Jakarta Sans', sans-serif;
}

.admin-arrangement-smart-controls select,
.admin-arrangement-smart-controls input[type='time'] {
  width: 132px;
  padding: 0 8px;
}

.admin-arrangement-switch-control input[type='checkbox'] {
  appearance: none;
  position: relative;
  width: 38px;
  height: 22px;
  margin: 0;
  border: 1px solid var(--admin-border);
  border-radius: 999px;
  background: var(--admin-bg);
  cursor: pointer;
}

.admin-arrangement-switch-control input[type='checkbox']::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--admin-muted);
  transition: transform .16s ease, background .16s ease;
}

.admin-arrangement-switch-control input[type='checkbox']:checked {
  border-color: color-mix(in srgb, #34d399 55%, var(--admin-border));
  background: color-mix(in srgb, #34d399 18%, var(--admin-bg));
}

.admin-arrangement-switch-control input[type='checkbox']:checked::after {
  background: #34d399;
  transform: translateX(16px);
}

.admin-arrangement-unit-input {
  display: grid;
  grid-template-columns: 58px auto;
  align-items: center;
  gap: 6px;
}

.admin-arrangement-unit-input input { width: 58px; padding: 0 7px; }
.admin-arrangement-unit-input b { color: var(--admin-muted); font-size: .52rem; }

.admin-arrangement-weekly-heading {
  margin: 0 0 14px;
  padding-top: 2px;
}

[data-arrangement-policy-form].is-read-only .admin-arrangement-smart-controls,
[data-arrangement-policy-form].is-read-only .admin-arrangement-rule-card-grid,
[data-arrangement-policy-form].is-read-only .admin-arrangement-advanced {
  opacity: .66;
}

[data-arrangement-policy-form].is-read-only .admin-arrangement-savebar > div {
  display: none;
}

.admin-arrangement-workspace.is-schedule,
.admin-arrangement-workspace.is-rules {
  grid-template-columns: minmax(0, 1fr);
}

.admin-arrangement-workspace.is-schedule .admin-arrangement-status-strip {
  order: -1;
  grid-template-columns: minmax(0, 1fr);
  gap: 28px;
  padding: 14px 4px;
  border-bottom: 1px solid var(--admin-border);
  border-left: 0;
}

.admin-arrangement-status-strip .admin-arrangement-status-guide {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  margin-top: 8px;
}

.admin-arrangement-status-strip .admin-arrangement-attention {
  padding: 0 0 0 28px;
  border-top: 0;
  border-left: 1px solid var(--admin-border);
}

.admin-arrangement-status-strip .admin-arrangement-attention small {
  display: block;
  margin-top: 8px;
  color: var(--admin-muted);
  font-size: .61rem;
  line-height: 1.45;
}

.admin-arrangement-workspace.is-schedule .admin-arrangement-primary {
  padding: 18px 4px 28px;
}

.admin-arrangement-workspace.is-schedule .admin-arrangement-schedule-head {
  margin-bottom: 16px;
}

.admin-arrangement-window-explainer {
  display: grid;
  justify-items: end;
  gap: 4px;
  max-width: 310px;
  text-align: right;
}

.admin-arrangement-window-explainer strong {
  font-size: .68rem;
}

.admin-arrangement-window-explainer span {
  color: var(--admin-muted);
  font-size: .61rem;
  line-height: 1.45;
}

.admin-arrangement-summary .is-booked strong,
.admin-arrangement-status-guide .is-booked {
  color: #60a5fa;
}

.admin-arrangement-status-guide .is-confirmed {
  color: #34d399;
}

.admin-arrangement-status-guide .is-upcoming {
  color: #fbbf24;
}

.admin-arrangement-status-guide .is-overdue {
  color: #fb7185;
}

.admin-arrangement-agenda {
  overflow: hidden;
  border: 1px solid var(--admin-border);
  border-radius: 12px;
  background: color-mix(in srgb, var(--admin-surface) 90%, transparent);
}

.admin-arrangement-rescheduler {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(360px, .8fr);
  align-items: end;
  gap: 24px;
  margin: 0 0 14px;
  padding: 16px 18px;
  border: 1px solid color-mix(in srgb, #60a5fa 35%, var(--admin-border));
  border-radius: 10px;
  background: color-mix(in srgb, #60a5fa 6%, var(--admin-bg));
}

.admin-arrangement-rescheduler[hidden] {
  display: none;
}

.admin-arrangement-rescheduler h3 {
  margin: 4px 0;
  font-size: .9rem;
}

.admin-arrangement-rescheduler p,
.admin-arrangement-rescheduler small {
  margin: 0;
  color: var(--admin-muted);
  font-size: .62rem;
  line-height: 1.5;
}

.admin-arrangement-rescheduler p strong {
  color: var(--admin-text);
}

.admin-arrangement-rescheduler form,
.admin-arrangement-rescheduler form label {
  display: grid;
  gap: 7px;
}

.admin-arrangement-rescheduler form label > span {
  color: var(--admin-muted);
  font-size: .56rem;
  font-weight: 800;
  letter-spacing: .04em;
  text-transform: uppercase;
}

.admin-arrangement-rescheduler form select {
  width: 100%;
}

.admin-arrangement-rescheduler form > div {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.admin-arrangement-deadline-scroll {
  overflow-x: auto;
}

.admin-arrangement-deadline-chart {
  min-width: 1240px;
}

.admin-arrangement-deadline-axis {
  display: grid;
  grid-template-columns: repeat(32, minmax(0, 1fr));
  min-height: 48px;
  padding: 8px 12px 7px;
  border-bottom: 1px solid var(--admin-border);
  color: var(--admin-muted);
  background: color-mix(in srgb, var(--admin-text) 2.5%, transparent);
}

.admin-arrangement-deadline-axis span {
  grid-column: var(--tick-column) / span 4;
  display: grid;
  align-content: center;
  gap: 3px;
  min-width: 0;
}

.admin-arrangement-deadline-axis span:last-child {
  grid-column: 29 / 33;
  justify-items: end;
}

.admin-arrangement-deadline-axis strong {
  color: var(--admin-text);
  font-size: .59rem;
}

.admin-arrangement-deadline-axis span:nth-child(3) strong {
  color: #60a5fa;
}

.admin-arrangement-deadline-axis small {
  overflow: hidden;
  font-size: .49rem;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-arrangement-deadline-plot {
  position: relative;
  min-height: calc(300px + (var(--pickup-lanes, 0) * 34px));
  padding: 11px 12px;
}

.admin-arrangement-deadline-grid {
  position: absolute;
  inset: 0 12px;
  display: grid;
  grid-template-columns: repeat(32, minmax(0, 1fr));
  pointer-events: none;
}

.admin-arrangement-deadline-grid i {
  border-left: 1px solid color-mix(in srgb, var(--admin-border) 75%, transparent);
}

.admin-arrangement-deadline-grid i.is-history {
  background: color-mix(in srgb, var(--admin-text) 2.5%, transparent);
}

.admin-arrangement-now-line {
  position: absolute;
  z-index: 3;
  top: 0;
  bottom: 0;
  left: calc(25% + 6px);
  width: 2px;
  background: #60a5fa;
  box-shadow: 0 0 0 1px color-mix(in srgb, #60a5fa 18%, transparent);
  pointer-events: none;
}

.admin-arrangement-pickup-markers {
  position: absolute;
  z-index: 4;
  inset: 0 12px;
  pointer-events: none;
}

.admin-arrangement-pickup-windows {
  position: absolute;
  z-index: 4;
  inset: 0 12px auto;
  height: calc(40px + (var(--pickup-lanes, 0) * 34px));
  pointer-events: none;
}

.admin-arrangement-pickup-window {
  position: absolute;
  top: calc(6px + (var(--pickup-window-lane) * 34px));
  left: var(--pickup-window-left);
  width: var(--pickup-window-width);
  min-width: 58px;
  height: 29px;
  overflow: hidden;
  padding: 4px 6px;
  border: 1px solid color-mix(in srgb, #60a5fa 64%, var(--admin-border));
  border-radius: 4px;
  color: #bfdbfe;
  background: color-mix(in srgb, #60a5fa 20%, var(--admin-bg));
  cursor: help;
  pointer-events: auto;
}

.admin-arrangement-pickup-window.is-active {
  border-color: #60a5fa;
  color: #dbeafe;
  background: color-mix(in srgb, #60a5fa 32%, var(--admin-bg));
}

.admin-arrangement-pickup-window.is-passed {
  border-color: color-mix(in srgb, #fb7185 62%, var(--admin-border));
  color: #fecdd3;
  background: color-mix(in srgb, #fb7185 18%, var(--admin-bg));
}

.admin-arrangement-pickup-window strong,
.admin-arrangement-pickup-window small {
  display: block;
  overflow: hidden;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-arrangement-pickup-window strong {
  font-size: .48rem;
}

.admin-arrangement-pickup-window small {
  margin-top: 2px;
  color: currentColor;
  font-size: .43rem;
  opacity: .8;
}

.admin-arrangement-pickup-marker {
  position: absolute;
  top: 0;
  bottom: 0;
  left: var(--pickup-position);
  width: 12px;
  padding: 0;
  border: 0;
  border-left: 2px dotted #34d399;
  border-radius: 0;
  color: #34d399;
  background: transparent;
  cursor: help;
  pointer-events: auto;
}

.admin-arrangement-pickup-marker > span,
.admin-arrangement-pickup-marker > strong {
  position: absolute;
  left: 5px;
  display: block;
  width: max-content;
  max-width: 110px;
  color: #34d399;
  font-size: .48rem;
  line-height: 1.2;
  text-align: left;
  white-space: nowrap;
}

.admin-arrangement-pickup-marker > span {
  top: calc(5px + (var(--pickup-lanes, 0) * 34px));
}

.admin-arrangement-pickup-marker > strong {
  top: calc(17px + (var(--pickup-lanes, 0) * 34px));
  font-weight: 850;
}

.admin-arrangement-pickup-preview {
  position: absolute;
  z-index: 10;
  top: calc(38px + (var(--pickup-lanes, 0) * 34px));
  left: 8px;
  display: grid;
  gap: 5px;
  width: 232px;
  padding: 12px;
  border: 1px solid color-mix(in srgb, #34d399 48%, var(--admin-border));
  border-radius: 7px;
  color: var(--admin-text);
  background: color-mix(in srgb, var(--admin-surface) 96%, #34d399);
  box-shadow: 0 16px 42px rgba(0, 0, 0, .45);
  text-align: left;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-4px);
  transition: opacity .14s ease, transform .14s ease, visibility .14s ease;
}

.admin-arrangement-pickup-marker:hover .admin-arrangement-pickup-preview,
.admin-arrangement-pickup-marker:focus-visible .admin-arrangement-pickup-preview {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.admin-arrangement-pickup-preview small {
  color: #34d399;
  font-size: .5rem;
  font-weight: 800;
}

.admin-arrangement-pickup-preview b {
  font-size: .68rem;
}

.admin-arrangement-pickup-preview ul {
  display: grid;
  gap: 3px;
  margin: 2px 0;
  padding: 0;
  list-style: none;
}

.admin-arrangement-pickup-preview li {
  overflow: hidden;
  padding: 5px 7px;
  border: 1px solid var(--admin-border);
  border-radius: 4px;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: .55rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-arrangement-pickup-preview em,
.admin-arrangement-pickup-preview i {
  color: var(--admin-muted);
  font-size: .49rem;
  font-style: normal;
}

.admin-arrangement-pickup-preview i {
  padding-top: 5px;
  border-top: 1px solid var(--admin-border);
}

.has-arrangement-dialog {
  overflow: hidden;
}

.admin-arrangement-event-overlay {
  position: fixed;
  z-index: 120;
  inset: 0;
  display: grid;
  justify-items: end;
  background: rgba(0, 0, 0, .66);
  backdrop-filter: blur(5px);
}

.admin-arrangement-event-overlay[hidden] {
  display: none;
}

.admin-arrangement-event-dialog {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  width: min(1120px, calc(100vw - 72px));
  height: 100vh;
  border-left: 1px solid var(--admin-border);
  background: var(--admin-bg);
  box-shadow: -28px 0 70px rgba(0, 0, 0, .52);
}

.admin-arrangement-event-dialog > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 22px 26px;
  border-bottom: 1px solid var(--admin-border);
}

.admin-arrangement-event-dialog > header h3 {
  margin: 5px 0 3px;
  font-size: 1.08rem;
}

.admin-arrangement-event-dialog > header p {
  margin: 0;
  color: var(--admin-muted);
  font-size: .64rem;
}

.admin-arrangement-event-layout {
  display: grid;
  grid-template-columns: 300px minmax(0, 1fr);
  min-height: 0;
}

.admin-arrangement-event-layout > aside {
  min-height: 0;
  overflow-y: auto;
  padding: 18px;
  border-right: 1px solid var(--admin-border);
  background: color-mix(in srgb, var(--admin-surface) 52%, transparent);
}

.admin-arrangement-event-layout > main {
  min-width: 0;
  overflow-y: auto;
  padding: 24px 26px 48px;
}

.admin-arrangement-event-summary {
  display: grid;
  gap: 5px;
  margin-bottom: 16px;
  padding: 14px;
  border: 1px solid color-mix(in srgb, #34d399 38%, var(--admin-border));
  border-radius: 7px;
  background: color-mix(in srgb, #34d399 7%, var(--admin-bg));
}

.admin-arrangement-event-summary > strong {
  color: #34d399;
  font-size: 1.4rem;
  line-height: 1;
}

.admin-arrangement-event-summary > span {
  font-size: .63rem;
  font-weight: 800;
}

.admin-arrangement-event-summary > small {
  color: var(--admin-muted);
  font-size: .53rem;
  line-height: 1.45;
}

.admin-arrangement-event-order-list {
  display: grid;
  gap: 6px;
}

.admin-arrangement-event-order-list button {
  display: grid;
  justify-items: start;
  gap: 3px;
  width: 100%;
  padding: 11px 12px;
  border: 1px solid var(--admin-border);
  border-radius: 6px;
  color: var(--admin-text);
  background: transparent;
  text-align: left;
  cursor: pointer;
}

