.admin-accounting-option-row > label,.admin-accounting-language-grid label,.admin-accounting-category-settings-form > label,.admin-accounting-settings-form-grid label { display:grid; gap:5px; }
.admin-accounting-option-row label > span,.admin-accounting-language-grid label > span,.admin-accounting-category-settings-form label > span { color:var(--accounting-muted); font-size:.62rem; font-weight:800; }
.admin-accounting-option-row :is(input[type=text]),.admin-accounting-language-grid input,.admin-accounting-category-settings-form :is(input[type=text],select) { width:100%; min-height:40px; padding:0 10px; border:1px solid var(--accounting-border); border-radius:8px; outline:0; background:var(--accounting-surface); color:var(--accounting-text); }
.admin-accounting-option-row input[readonly] { color:var(--accounting-muted); background:color-mix(in srgb,var(--accounting-text) 4%,transparent); }
.admin-accounting-option-active { display:flex!important; align-items:center; min-height:40px; gap:7px!important; }
.admin-accounting-option-active input { width:16px; height:16px; }
.admin-accounting-option-row > button { width:34px; height:40px; border:0; background:transparent; color:var(--accounting-muted); font-size:1.25rem; cursor:pointer; }
.admin-accounting-add-choice { justify-self:start; padding:8px 2px; border:0; background:transparent; color:#20d98a; font-weight:800; cursor:pointer; }
[data-accounting-preferences-form] > .admin-primary-btn { float:right; margin-top:16px; }
.admin-accounting-language-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; }
.admin-accounting-category-steps { display:grid; gap:10px; max-width:820px; margin-bottom:14px; }
.admin-accounting-category-step { display:grid; grid-template-columns:32px minmax(150px,.8fr) minmax(280px,1.4fr); align-items:center; gap:12px; padding:13px; border:1px solid var(--accounting-border); border-radius:13px; background:color-mix(in srgb,var(--accounting-surface) 95%,var(--accounting-text) 5%); }
.admin-accounting-category-step > b { display:grid; place-items:center; width:28px; height:28px; border-radius:50%; background:var(--accounting-text); color:var(--accounting-surface); font-size:.72rem; }
