.admin-accounting-flow-choice { display:grid; grid-template-columns:1fr 1fr; gap:7px; }
.admin-accounting-flow-choice button { min-height:44px; border:1px solid var(--accounting-border); border-radius:10px; background:var(--accounting-surface); color:var(--accounting-text); font-weight:850; cursor:pointer; }
