.admin-accounting-flow-choice button[data-accounting-category-flow="expense"].is-active { border-color:#ef233c; background:color-mix(in srgb,#ef233c 16%,var(--accounting-surface)); color:#ff687a; box-shadow:inset 0 0 0 1px #ef233c; }
.admin-accounting-step-control { display:grid; grid-template-columns:minmax(170px,1fr) auto auto; align-items:center; gap:7px; }
.admin-accounting-step-control select { width:100%; min-height:42px; padding:0 10px; border:1px solid var(--accounting-border); border-radius:9px; background:var(--accounting-surface); color:var(--accounting-text); }
.admin-link-btn { border:0; background:transparent; color:#20d98a; font-size:.64rem; font-weight:800; cursor:pointer; }
.admin-accounting-category-settings-form { display:grid; gap:15px; width:100%; max-width:820px; box-sizing:border-box; margin-top:12px; padding:18px; border:1px solid var(--accounting-border); border-radius:14px; }
.admin-accounting-category-settings-form textarea { width:100%; max-width:100%; box-sizing:border-box; resize:vertical; }
.admin-accounting-settings-form-grid { display:grid; grid-template-columns:1.2fr .8fr 1fr; gap:10px; }
.admin-accounting-settings-form-grid--two { grid-template-columns:1fr 1fr; }
.admin-accounting-category-editor-head { display:flex; justify-content:space-between; }
.admin-accounting-category-editor-head > div { display:grid; gap:3px; }
.admin-accounting-category-editor-head strong,.admin-accounting-category-move > div > strong { color:var(--accounting-text); font-size:.8rem; }
.admin-accounting-category-editor-head small,.admin-accounting-category-move > div > small { color:var(--accounting-muted); font-size:.63rem; }
.admin-accounting-category-behavior { display:grid; gap:8px; }
.admin-accounting-plain-toggle,.admin-accounting-move-scope > label { display:grid!important; grid-template-columns:1fr auto; align-items:center!important; gap:14px!important; padding:11px; border:1px solid var(--accounting-border); border-radius:10px; cursor:pointer; }
.admin-accounting-plain-toggle input { grid-column:2; grid-row:1; position:relative; width:38px; height:22px; margin:0; border:1px solid var(--accounting-border); border-radius:999px; appearance:none; -webkit-appearance:none; background:color-mix(in srgb,var(--accounting-text) 12%,var(--accounting-surface)); cursor:pointer; transition:background-color .18s ease,border-color .18s ease; }
.admin-accounting-plain-toggle input::before { content:""; position:absolute; top:2px; left:2px; width:16px; height:16px; border-radius:50%; background:var(--accounting-muted); box-shadow:0 1px 3px rgba(0,0,0,.28); transition:transform .18s ease,background-color .18s ease; }
.admin-accounting-plain-toggle:has(input:checked) { border-color:color-mix(in srgb,#00d97e 42%,var(--accounting-border)); background:color-mix(in srgb,#00d97e 7%,transparent); }
.admin-accounting-plain-toggle input:checked { border-color:#00d97e!important; background:#00d97e!important; box-shadow:0 0 0 3px rgba(0,217,126,.14)!important; }
.admin-accounting-plain-toggle input:checked::before { transform:translateX(16px); background:#fff; }
.admin-accounting-plain-toggle input:focus-visible { outline:2px solid #20d98a; outline-offset:3px; }
.admin-accounting-move-scope input { width:16px; height:16px; margin-top:2px; }
.admin-accounting-plain-toggle span { grid-column:1; grid-row:1; }
.admin-accounting-plain-toggle span,.admin-accounting-move-scope label span { display:grid; gap:3px; color:var(--accounting-text)!important; }
.admin-accounting-plain-toggle strong,.admin-accounting-move-scope strong { font-size:.7rem; }
.admin-accounting-plain-toggle small,.admin-accounting-move-scope small { color:var(--accounting-muted); font-size:.61rem; font-weight:500; line-height:1.4; }
.admin-accounting-category-form-actions { display:flex; justify-content:flex-end; gap:8px; }
.admin-accounting-category-move { display:grid; grid-template-columns:minmax(180px,.7fr) minmax(180px,1fr); gap:12px; max-width:820px; margin-top:12px; padding:18px; border:1px dashed var(--accounting-border); border-radius:14px; }
.admin-accounting-category-move > div:first-child { display:grid; align-content:start; gap:3px; }
.admin-accounting-category-move > label { display:grid; gap:5px; }
.admin-accounting-category-move > label > span,.admin-accounting-move-dates span { color:var(--accounting-muted); font-size:.62rem; font-weight:800; }
.admin-accounting-category-move select,.admin-accounting-category-move input[type=date] { min-height:40px; padding:0 10px; border:1px solid var(--accounting-border); border-radius:8px; background:var(--accounting-surface); color:var(--accounting-text); }
.admin-accounting-move-scope { grid-column:1 / -1; display:grid; gap:8px; }
.admin-accounting-move-dates { display:grid; grid-template-columns:1fr 1fr; gap:8px; padding-left:27px; }
.admin-accounting-move-dates label { display:grid; gap:5px; }
.admin-accounting-category-move > .admin-form-error { grid-column:1 / -1; }
.admin-accounting-category-move > button { justify-self:end; grid-column:1 / -1; }
.admin-accounting-removal-card { width:min(560px,calc(100vw - 28px)); padding:22px; border-color:color-mix(in srgb,#ef233c 42%,var(--accounting-border)); }
.admin-accounting-removal-card > .admin-modal-head { padding-bottom:16px; border-bottom:1px solid var(--accounting-border); }
.admin-accounting-removal-card > .admin-modal-head p { max-width:430px; margin:5px 0 0; color:var(--accounting-muted); font-size:.69rem; line-height:1.5; }
.admin-accounting-removal-card form { display:grid; gap:13px; padding-top:16px; }
.admin-accounting-removal-card form > label { display:grid; gap:6px; }
.admin-accounting-removal-card form > label > span { color:var(--accounting-text); font-size:.7rem; font-weight:850; }
.admin-accounting-removal-card form > label > small { color:var(--accounting-muted); font-size:.61rem; line-height:1.4; }
.admin-accounting-removal-card :is(input[type=text],input[type=password],textarea) { width:100%; padding:10px 11px; border:1px solid var(--accounting-border); border-radius:9px; outline:0; background:var(--accounting-surface); color:var(--accounting-text); font:650 .75rem/1.45 "Plus Jakarta Sans",sans-serif; }
.admin-accounting-removal-card :is(input,textarea):focus { border-color:#ef233c; box-shadow:0 0 0 3px color-mix(in srgb,#ef233c 12%,transparent); }
.admin-accounting-removal-warning { padding:12px 13px; border:1px solid color-mix(in srgb,#ef233c 40%,var(--accounting-border)); border-radius:10px; background:color-mix(in srgb,#ef233c 8%,transparent); }
.admin-accounting-removal-warning strong { color:#ff6b7d; font-size:.72rem; }
.admin-accounting-removal-warning p { margin:4px 0 0; color:var(--accounting-muted); font-size:.63rem; line-height:1.45; }
.admin-accounting-removal-card code { justify-self:start; padding:6px 8px; border-radius:6px; background:color-mix(in srgb,var(--accounting-text) 8%,transparent); color:var(--accounting-text); font-size:.68rem; font-weight:850; user-select:all; }
.admin-accounting-removal-actions { display:flex; justify-content:flex-end; gap:8px; padding-top:3px; }
.admin-accounting-ledger-remove { align-self:center; border:0; background:transparent; color:var(--accounting-muted); font-size:.61rem; font-weight:800; text-decoration:underline; text-underline-offset:3px; cursor:pointer; }
.admin-accounting-ledger-remove:hover { color:#ef233c; }

@media (max-width:860px) {
  .admin-accounting-ledger-filters { grid-template-columns:1fr 1fr; }
  .admin-accounting-ledger-search { grid-column:1 / -1; }
  .admin-accounting-filter-clear { justify-self:start; }
  .admin-accounting-settings-layout { grid-template-columns:1fr; }
  .admin-accounting-settings-nav { grid-template-columns:repeat(4,1fr); padding:10px 0; border-right:0; border-bottom:1px solid var(--accounting-border); }
  .admin-accounting-settings-nav button { grid-template-columns:1fr; justify-items:center; min-height:52px; text-align:center; }
  .admin-accounting-settings-nav button small { display:none; }
  .admin-accounting-settings-content { padding:18px 0; }
  .admin-accounting-account-settings-card { overflow:auto; }
  .admin-accounting-option-row { grid-template-columns:1fr 1fr 68px 34px; }
}
@media (max-width:600px) {
  .admin-accounting-command { grid-template-columns:1fr auto; }
  .admin-accounting-ledger-filters,.admin-accounting-language-grid,.admin-accounting-settings-form-grid { grid-template-columns:1fr; }
  .admin-accounting-ledger-search { grid-column:auto; }
  .admin-accounting-option-row { grid-template-columns:1fr 1fr; padding-bottom:10px; border-bottom:1px solid var(--accounting-border); }
  .admin-accounting-settings-nav strong { font-size:.62rem; }
  .admin-accounting-category-step { grid-template-columns:30px 1fr; }
  .admin-accounting-category-step > :last-child { grid-column:1 / -1; }
  .admin-accounting-step-control,.admin-accounting-settings-form-grid--two,.admin-accounting-category-move { grid-template-columns:1fr; }
  .admin-accounting-category-move > * { grid-column:1!important; }
}

/* Neutral child-page return navigation for the Website ecosystem. */
