/* Accounting category guidance */
.admin-accounting-category-result {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 34px;
  align-items: stretch;
  border-radius: 7px;
}

.admin-accounting-category-result:has(> button:hover),
.admin-accounting-category-result:has(> button:focus-visible),
.admin-accounting-category-result:has(> button[aria-selected='true']) {
  background: color-mix(in srgb, var(--accounting-text) 7%, transparent);
}

.admin-accounting-category-result > button {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 3px 10px;
  width: 100%;
  min-width: 0;
  padding: 9px 4px 9px 10px;
  border: 0;
  border-radius: 7px 0 0 7px;
  outline: 0;
  background: transparent;
  color: var(--accounting-text);
  text-align: left;
  cursor: pointer;
}

.admin-accounting-category-result > button > span {
  overflow: hidden;
  color: var(--accounting-text) !important;
  font: 800 0.77rem/1.25 "Space Grotesk", sans-serif !important;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-accounting-category-result > button > small {
  grid-column: 1;
  overflow: hidden;
  color: var(--accounting-muted);
  font: 700 0.65rem/1.2 "Plus Jakarta Sans", sans-serif;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-accounting-category-result > button > b {
  grid-column: 2;
  grid-row: 1 / 3;
  align-self: center;
  color: var(--accounting-text);
  font-size: 0.75rem;
}

.admin-accounting-category-info {
  display: grid;
  place-items: center;
  align-self: stretch;
  width: 34px;
  padding: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--accounting-muted);
  text-decoration: none;
}

.admin-accounting-category-info:hover,
.admin-accounting-category-info:focus-visible {
  color: var(--accounting-text);
}

.admin-accounting-category-info svg {
  width: 17px;
  height: 17px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.8;
}

.admin-accounting-guidance-editor {
  overflow: hidden;
  border: 1px solid var(--accounting-border);
  border-radius: 12px;
  background: color-mix(in srgb, var(--accounting-text) 2.5%, transparent);
}

.admin-accounting-guidance-editor > summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 14px;
  color: var(--accounting-text);
  cursor: pointer;
  list-style: none;
}

.admin-accounting-guidance-editor > summary::-webkit-details-marker { display: none; }
.admin-accounting-guidance-editor > summary > span { display: grid; gap: 3px; }
.admin-accounting-guidance-editor > summary strong { font-size: .76rem; }
.admin-accounting-guidance-editor > summary small { color: var(--accounting-muted); font-size: .62rem; }
.admin-accounting-guidance-editor > summary > b { transition: transform 150ms ease; }
.admin-accounting-guidance-editor[open] > summary > b { transform: rotate(180deg); }

.admin-accounting-guidance-fields {
  display: grid;
  gap: 13px;
  padding: 2px 14px 15px;
}

.admin-accounting-guidance-fields label {
  display: grid;
  gap: 5px;
}

.admin-accounting-guidance-fields label > span {
  color: var(--accounting-muted);
  font-size: .62rem;
  font-weight: 800;
}

.admin-accounting-guidance-fields textarea {
  width: 100%;
  min-height: 76px;
  padding: 10px;
  border: 1px solid var(--accounting-border);
  border-radius: 8px;
  outline: 0;
  background: var(--accounting-surface);
  color: var(--accounting-text);
  font: 650 .71rem/1.5 "Plus Jakarta Sans", sans-serif;
  resize: vertical;
}

.admin-accounting-guidance-fields textarea:focus {
  border-color: color-mix(in srgb, var(--admin-accent) 58%, var(--accounting-border));
}

.admin-accounting-guidance-fields > p {
  margin: 0;
  color: var(--accounting-muted);
  font-size: .62rem;
  line-height: 1.45;
}

.admin-category-guide {
  display: grid;
  gap: 18px;
  width: min(1180px, calc(100% - 36px));
  margin: 0 auto;
  padding: 22px 0 54px;
}

.admin-category-guide-back {
  justify-self: start;
  color: var(--accounting-muted, var(--admin-muted));
  font-size: .72rem;
  font-weight: 800;
  text-decoration: none;
}

.admin-category-guide-back:hover { color: var(--accounting-text, var(--admin-text)); }

.admin-category-guide-hero,
.admin-category-guide-error {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(290px, .8fr);
  gap: 28px;
  padding: clamp(24px, 4vw, 46px);
  border: 1px solid var(--accounting-border, var(--admin-border));
  border-radius: 22px;
  background: linear-gradient(145deg, color-mix(in srgb, var(--admin-accent) 10%, var(--accounting-surface, var(--admin-surface))), var(--accounting-surface, var(--admin-surface)) 48%);
