.admin-category-guide-disclaimer strong { color: var(--accounting-text, var(--admin-text)); font-size: .73rem; }
.admin-category-guide-disclaimer p { margin: 4px 0 0; color: var(--accounting-muted, var(--admin-muted)); font-size: .68rem; line-height: 1.55; }

.admin-category-guide-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.admin-category-guide-card {
  min-width: 0;
  padding: clamp(20px, 3vw, 30px);
  border: 1px solid var(--accounting-border, var(--admin-border));
